async def openrouter_detect_category(
    text: str,
    transaction_type: str,
):
    if not OPENROUTER_API_KEY:
        return None

    if transaction_type == "income":
        categories = set(INCOME_CATEGORIES_RU.keys())
    else:
        categories = set(EXPENSE_CATEGORIES_RU.keys())

    if transaction_type == "income":
        category_rules = """
Правила определения ДОХОДОВ:

- salary — заработная плата, аванс, выплаты от работодателя за работу по найму.
- freelance — оплата отдельных заказов, проектов и услуг, выполненных самостоятельно.
- business — прибыль и выручка от собственного бизнеса или предпринимательской деятельности.
- scholarship — стипендия и выплаты за обучение.
- pension — пенсия.
- benefits — государственные пособия, социальные выплаты и материальная помощь.
- investment — доход от продажи акций, облигаций и других инвестиционных активов.
- rent_income — деньги, полученные за сдачу недвижимости или имущества в аренду.
- gift — полученные в подарок деньги.
- refund — возврат ранее потраченных или ошибочно списанных денег.
- interest — проценты по банковским вкладам, накопительным счетам и другим процентным инструментам.
- other_income — доход, который невозможно отнести ни к одной из перечисленных категорий.
"""
    else:
        category_rules = """
Правила определения РАСХОДОВ:

- food — продукты питания, ингредиенты и напитки, купленные для употребления дома или приготовления еды: мясо, рыба, молоко, масло, сыр, хлеб, крупы, овощи, фрукты, сладости и т. д.
- restaurants — готовая еда в кафе и ресторанах, доставка еды, фастфуд и заказ блюд.
- transport — такси, общественный транспорт, метро, автобусы, поезда и оплата проезда.
- housing — расходы на содержание и обслуживание жилья, не относящиеся к коммунальным платежам или аренде.
- utilities — электричество, вода, отопление, газ, вывоз мусора и другие коммунальные услуги.
- rent — оплата аренды квартиры, дома, комнаты или коммерческого помещения.
- shopping — покупки общего назначения, которые не подходят ни к одной более конкретной категории.
- clothing — одежда, обувь, сумки и аксессуары.
- health — лекарства, аптеки, медицинские услуги, обследования и лечение.
- education — обучение, образовательные курсы, учебники и другие учебные материалы.
- entertainment — кино, концерты, музеи, видеоигры и другие развлечения.
- subscriptions — регулярная или разовая оплата подписок на цифровые сервисы и платформы.
- communication — мобильная связь, тарифы и пополнение баланса телефона.
- internet — оплата домашнего или мобильного доступа к интернету.
- travel — туристические поездки, гостиницы, экскурсии и расходы во время путешествий.
- fuel — бензин, дизель, газ и зарядка электромобиля.
- car — ремонт, техническое обслуживание, мойка, запчасти и другие расходы на автомобиль, кроме топлива.
- home — мебель, посуда, бытовые принадлежности, декор и товары для дома.
- technology — смартфоны, компьютеры, ноутбуки, комплектующие и другая электроника.
- gifts — товары и услуги, приобретённые в качестве подарка другим людям.
- pets — корм, игрушки, ветеринарные услуги и другие расходы на домашних животных.
- sports — спортивный инвентарь, тренировки, абонементы и занятия спортом.
- beauty — косметика, парфюмерия, средства ухода, парикмахерские и косметические услуги.
- taxes — налоги, налоговые сборы и обязательные налоговые платежи.
- loans — погашение кредитов, займов и задолженностей.
- insurance — страховые полисы и страховые взносы.
- investments — покупка акций, облигаций, криптовалюты и других инвестиционных активов.
- charity — пожертвования и благотворительные взносы.
- other_expense — расход, который невозможно отнести ни к одной из перечисленных категорий.
"""

    prompt = f"""
Определи категорию финансовой операции по её смыслу.

Тип операции: {"доход" if transaction_type == "income" else "расход"}
Описание операции: {text}

Допустимые ключи категорий:
{", ".join(sorted(categories))}

{category_rules}

Дополнительные правила:

1. Определяй категорию по реальному назначению товара, услуги или платежа, а не только по отдельным словам.

2. Учитывай сокращения, опечатки, ошибки OCR и неполные названия товаров. Восстанавливай смысл по оставшейся части названия.

3. Если описание написано на английском языке, применяй те же правила классификации. Названия категорий в ответе всегда должны быть ключами из списка выше.

4. Не путай похожие категории. Например:
   - продукты из магазина — food, готовая еда из ресторана — restaurants;
   - бензин — fuel, ремонт автомобиля — car;
   - покупка смартфона — technology, покупка мебели — home;
   - аренда жилья — rent, коммунальные платежи — utilities;
   - покупка акций — investments для расходов, доход от продажи акций — investment для доходов.

5. Не выбирай shopping или other_income / other_expense, если описание позволяет определить более конкретную категорию.

6. Не придумывай новые категории и не изменяй ключи из списка.

Выбери ровно одну наиболее подходящую категорию.
Верни только её ключ, без пояснений и дополнительного текста.
"""

    try:
        response = await ask_openrouter(prompt)

        if not response:
            return None

        response = response.strip().lower()

        if response in categories:
            return response

        print("Неизвестная категория от ИИ:", response)
        return None

    except Exception as e:
        print("Ошибка определения категории:", repr(e))
        return None


# ========================================================
# ОСНОВНОЙ PROMPT
# ========================================================

    # ========================================================
    # ОСНОВНОЙ PROMPT
    # ========================================================

    prompt = f"""
Ты — интеллектуальный классификатор финансовых операций.

Твоя задача — определить ОДНУ категорию финансовой
операции на основе ПОЛНОГО текста сообщения.

Не анализируй сообщение только по отдельным словам.

Всегда учитывай весь доступный контекст.

============================================================
ТИП ОПЕРАЦИИ
============================================================

Тип операции уже определён программой:

{transaction_type}

ТЕКСТ ПОЛЬЗОВАТЕЛЯ:

{text}

Тип операции является важным ограничением:

income = пользователь получает деньги или имущество.

expense = пользователь тратит, отдаёт или вкладывает
деньги.

Не меняй тип операции самостоятельно.

============================================================
ЧТО НУЖНО АНАЛИЗИРОВАТЬ
============================================================

Перед выбором категории мысленно проанализируй всю фразу.

Учитывай:

- действие пользователя;
- получает он деньги или тратит их;
- предмет или услугу;
- бренд;
- название;
- модель;
- поколение;
- номер модели;
- количество;
- сумму;
- валюту, если она указана в тексте;
- место покупки или получения, если оно указано;
- назначение покупки;
- кому предназначен товар;
- отношения между участниками операции;
- дополнительные слова;
- разговорные сокращения;
- контекст всей фразы.

Не делай вывод только по одному слову.

============================================================
ДЕЙСТВИЕ ВАЖНЕЕ ОТДЕЛЬНОГО НАЗВАНИЯ
============================================================

Особенно внимательно анализируй глаголы и действия:

купил
купила
купили
потратил
потратила
заплатил
заплатила
отдал
отдала
получил
получила
заработал
заработала
продал
продала
подарили
подарил
подарила
нашёл
нашла
вернули
вернули деньги
оплатил
оплатила
взял
погасил
заправил
заправила
оплатил
оплатила

Одно и то же название может иметь совершенно
разную категорию в зависимости от действия.

Пример:

"купил BMW"
-> car

"заправил BMW"
-> fuel

"продал BMW"
при income
-> доход от продажи; если отдельной категории
продажи нет, используй наиболее подходящую
доступную категорию согласно правилам.

"получил BMW в подарок"
при income
-> gift

============================================================
НЕИЗВЕСТНЫЕ ТОВАРЫ, БРЕНДЫ И МОДЕЛИ
============================================================

Если встречается неизвестное название,
не отправляй операцию автоматически в
other_expense или other_income.

Сначала попытайся определить, что это такое,
используя свои общие знания и контекст.

Не требуется иметь название в локальном словаре.

Примеры:

"iPhone 16"
-> смартфон
-> technology

"RTX 4080"
-> видеокарта
-> technology

"RTX 4090"
-> видеокарта
-> technology

"RTX 20438"
-> вероятно обозначение видеокарты RTX;
учитывай общий смысл фразы и не считай число
отдельной категорией.

"MacBook Air M3"
-> ноутбук
-> technology

"AirPods Pro 2"
-> наушники
-> technology

"PS5 Slim"
-> игровая консоль
-> technology

"Dyson V15"
-> бытовая техника / пылесос
-> technology

"Rolex Submariner"
-> часы
-> shopping

"LEGO"
-> игрушка
-> shopping

"Netflix"
-> сервис подписки
-> subscriptions

Числа и буквенно-цифровые обозначения
внутри названия могут быть:

- моделью;
- поколением;
- версией;
- серией;
- размером.

Не используй число само по себе
как категорию.

Например:

"iPhone 16"
не означает категорию "16".

"RTX 4080"
не означает категорию "4080".

"M3"
может быть частью модели MacBook.

============================================================
НЕИЗВЕСТНЫЕ ПРОДУКТЫ И ЕДА
============================================================

Если пользователь указал название продукта,
блюда, напитка, сладости, фрукта, овоща или
другого съедобного продукта, которого нет
в локальном словаре, самостоятельно определи
его значение по своим общим знаниям.

Не требуй, чтобы название было заранее указано
в словаре.

При expense такие объекты обычно относятся
к категории food.

Примеры:

"дыня 2943 р"
-> дыня = фрукт/съедобный продукт
-> food

"манго 500 р"
-> манго = фрукт
-> food

"чак-чак 300 р"
-> чак-чак = сладость/еда
-> food

"суши 1200 р"
-> еда
-> food

"пельмени 500 р"
-> еда
-> food

"авокадо 400 р"
-> фрукт/продукт
-> food

"тирамису 700 р"
-> десерт
-> food

"капучино 300 р"
-> напиток
-> food

Не нужно добавлять эти слова
в локальный словарь программы.

Этот принцип распространяется
на любые другие известные тебе
названия продуктов и блюд.

Если слово незнакомо, сначала попытайся
определить его значение по общим знаниям
и контексту всей операции.

Если значение действительно невозможно
определить, используй other_expense,
а не придумывай категорию.

============================================================
КОНТЕКСТ ВАЖНЕЕ ЦЕНЫ
============================================================

Сумма и цена — только дополнительный контекст.

Никогда не выбирай категорию только
по размеру суммы.

Например дорогой товар не обязательно
является техникой.

Анализируй:

что купили;
что сделал пользователь;
зачем это было нужно;
кому это предназначено;
где это произошло;
какой бренд или модель указаны;
сумму;
валюту;
остальные слова.

============================================================
РАЗГОВОРНАЯ РЕЧЬ И СОКРАЩЕНИЯ
============================================================

Понимай обычную разговорную речь.

Примеры:

"зп" = зарплата
"аванс" = зарплата
"клава" = клавиатура
"др" = день рождения
"друган" = друг
"бро" = друг

Но не ограничивайся этим списком.

Если незнакомое слово можно понять
по контексту, используй смысл всей фразы.

============================================================
ПОДАРОК
============================================================

Различай:

"купил подарок другу"
при expense
-> gifts

"мне подарили iPhone"
при income
-> gift

"мне подарили 5000"
при income
-> gift

Слово "подарок" само по себе
не определяет направление операции.

Важно понять, кто кому что сделал.

============================================================
ДОХОДЫ
============================================================

При income учитывай причину получения денег
или имущества.

Примеры:

"получил зарплату"
-> salary

"получил аванс"
-> salary

"заработал на фрилансе"
-> freelance

"заработал на бизнесе"
-> business

"получил стипендию"
-> scholarship

"получил пенсию"
-> pension

"получил пособие"
-> benefits

"получил дивиденды"
-> investment

"получил проценты по вкладу"
-> interest

"получил деньги от аренды квартиры"
-> rent_income

"мне подарили деньги"
-> gift

"вернули деньги за покупку"
-> refund

Если пользователь написал только:

"айфон 100000"

при income,

НЕ предполагай автоматически продажу.

Причина получения денег неизвестна.

В таком случае:
-> other_income

============================================================
РАСПОЗНАВАНИЕ ОБЪЕКТА БЕЗ ЯВНОГО ГЛАГОЛА
============================================================

Если тип операции уже установлен программой
как expense, отсутствие глагола "купил",
"оплатил" или другого действия не означает,
что операция непонятна.

Если из текста понятно, что указанный объект
является товаром, продуктом, услугой или
другим расходом, классифицируй его по смыслу.

Например:

"дыня 2943 р"
-> food

"манго 500 р"
-> food

"iPhone 16 90000 р"
-> technology

"Rolex 500000 р"
-> shopping

"Netflix 1000 р"
-> subscriptions

"BMW 3000000 р"
-> car

Не возвращай unclear только потому,
что глагол покупки отсутствует.

============================================================
РАСХОДЫ
============================================================

При expense учитывай назначение расхода.

Примеры:

"купил iPhone"
-> technology

"купил RTX 4080"
-> technology

"купил Rolex"
-> shopping

"купил одежду"
-> clothing

"купил подарок другу"
-> gifts

"купил капучино"
-> food

"сходил в ресторан"
-> restaurants

"поехал на такси"
-> transport

"купил бензин"
-> fuel

"купил BMW"
-> car

"заплатил врачу"
-> health

"заплатил репетитору"
-> education

"заплатил за квартиру"
-> housing или rent
в зависимости от контекста.

"заплатил за ЖКХ"
-> utilities

"оплатил мобильную связь"
-> communication

"оплатил домашний интернет"
-> internet

"заплатил за Netflix"
-> subscriptions

"купил билет на концерт"
-> entertainment

"заплатил налог"
-> taxes

"погасил кредит"
-> loans

"заплатил за страховку"
-> insurance

"сделал пожертвование"
-> charity

============================================================
НЕ ПРИДУМЫВАЙ ФАКТЫ
============================================================

Используй разумный вывод только тогда,
когда он следует из текста или общеизвестного
значения названия.

Не выдумывай:

- причину получения денег;
- факт продажи;
- факт подарка;
- назначение неизвестного предмета;
- валюту, если её нет в тексте;
- характеристики товара, которых пользователь
  не указал и которые нельзя определить.

Если общий смысл операции понятен,
но специальной категории нет:

-> other_expense

или:

-> other_income

Если сама операция настолько неполная,
что невозможно понять её смысл:

-> unclear

Например:

"500"

может быть недостаточно для определения
назначения расхода.

Но:

"брелок 500"

означает понятный расход на товар,
поэтому это не unclear.

============================================================
ВАЛЮТА И СУММА
============================================================

Если валюта указана в тексте,
учитывай её как часть контекста.

Примеры:

"купил iPhone за 1000 долларов"
-> анализируй iPhone как technology,
а USD — как валюту операции.

"получил 500 евро"
-> учитывай EUR.

Не меняй и не придумывай валюту
только ради выбора категории.

Если валюта уже была надёжно определена
программой отдельно, не противоречь ей.

============================================================
ГЛАВНЫЙ ПРИНЦИП
============================================================

Сначала пойми смысл всей операции.

Затем определи:

1. что произошло;
2. что сделал пользователь;
3. что является предметом или услугой;
4. что означает бренд или модель;
5. кому предназначен товар или деньги;
6. какая категория лучше всего соответствует
   смыслу операции.

Не классифицируй по одному ключевому слову.

============================================================
РАЗРЕШЁННЫЕ КАТЕГОРИИ
============================================================

Можно вернуть ТОЛЬКО одну из следующих категорий:

{", ".join(sorted(categories))}

============================================================
ФОРМАТ ОТВЕТА
============================================================

Верни ТОЛЬКО название одной категории.

Без объяснений.
Без Markdown.
Без кавычек.
Без дополнительных слов.
"""

    # ========================================================
    # OPENROUTER API — ОПРЕДЕЛЕНИЕ КАТЕГОРИИ
    # ========================================================

    url = (
        "https://openrouter.ai/api/v1/"
        "chat/completions"
    )

    result_text = await ask_openrouter(prompt)

    if not result_text:
        return None

    result_text = (
        str(result_text)
        .strip()
        .lower()
        .replace("`", "")
    )

    result_text = result_text.splitlines()[0].strip()

    result_text = result_text.strip(
        " .,:;\"'"
    )

    print(
        "OPENROUTER CATEGORY INPUT:",
        repr(text),
    )

    print(
        "OPENROUTER CATEGORY OUTPUT:",
        repr(result_text),
    )

    if result_text in categories:
        return result_text

    print(
        "OpenRouter returned unknown category:",
        result_text,
    )

    return None


