# ============================================================
# ЛОКАЛЬНОЕ ОПРЕДЕЛЕНИЕ КАТЕГОРИИ
# ============================================================

def detect_category_local(
    text: str,
    transaction_type: str,
):
    text_lower = text.lower().strip()

    # --------------------------------------------------------
    # ДОХОД
    # --------------------------------------------------------

    if transaction_type == "income":

        # Нормализуем текст дохода
        text_normalized = re.sub(
            r"\s+",
            " ",
            text_lower.casefold().replace("ё", "е"),
        ).strip()

        matches = []

        for category, keywords in INCOME_CATEGORY_KEYWORDS.items():
            for keyword in keywords:
                keyword_normalized = re.sub(
                    r"\s+",
                    " ",
                    keyword.casefold().replace("ё", "е"),
                ).strip()

                if not keyword_normalized:
                    continue

                pattern = (
                    rf"(?<!\w)"
                    rf"{re.escape(keyword_normalized)}"
                    rf"(?!\w)"
                )

                if re.search(pattern, text_normalized):
                    matches.append(
                        (len(keyword_normalized), category)
                    )

        if not matches:
            return None

        # Выбираем самое длинное совпадение
        longest_match = max(
            length for length, category in matches
        )

        # При одинаковой длине сохраняем порядок словаря
        for length, category in matches:
            if length == longest_match:
                return category

        return None

    # --------------------------------------------------------
    # РАСХОДЫ — ПОИСК ПО ОСНОВНОМУ СЛОВАРЮ
    # --------------------------------------------------------

    text_normalized = re.sub(
        r"\s+",
        " ",
        text_lower.casefold().replace("ё", "е"),
    ).strip()

    matches = []

    for category, keywords in CATEGORY_KEYWORDS.items():
        for keyword in keywords:
            keyword_normalized = re.sub(
                r"\s+",
                " ",
                keyword.casefold().replace("ё", "е"),
            ).strip()

            if not keyword_normalized:
                continue

            pattern = (
                rf"(?<!\w)"
                rf"{re.escape(keyword_normalized)}"
                rf"(?!\w)"
            )

            if re.search(pattern, text_normalized):
                matches.append(
                    (len(keyword_normalized), category)
                )

    if not matches:
        return None

    # Более длинная фраза важнее отдельного слова
    longest_match = max(
        length for length, category in matches
    )

    # При равной длине используется порядок основного словаря
    for length, category in matches:
        if length == longest_match:
            return category

    return None


# ============================================================
# ОБЩЕЕ ОПРЕДЕЛЕНИЕ КАТЕГОРИИ
# ============================================================

async def detect_transaction_category(
    text: str,
    transaction_type: str,
    language: str,
):

    # --------------------------------------------------------
    # 1. СНАЧАЛА ЛОКАЛЬНЫЙ СЛОВАРЬ
    # --------------------------------------------------------

    local_category = detect_category_local(
        text,
        transaction_type,
    )

    if local_category:

        return local_category

    # --------------------------------------------------------
    # 2. ЕСЛИ НЕ НАШЛИ — OPENROUTER
    # --------------------------------------------------------

    ai_category = await openrouter_detect_category(
        text,
        transaction_type,
    )

    # --------------------------------------------------------
    # 3. ПРОВЕРЯЕМ ОТВЕТ OPENROUTER
    # --------------------------------------------------------

    if transaction_type == "income":

        allowed_categories = {
            "salary",
            "business",
            "benefits",
            "investment",
            "gift",
            "sale",
            "inheritance",
            "refund",
            "found_money",
            "other_income",
            "unclear",
        }

        if ai_category in allowed_categories:

            return ai_category

        return "other_income"

    # --------------------------------------------------------
    # РАСХОД
    # --------------------------------------------------------

    allowed_categories = {
        "food",
        "restaurants",
        "transport",
        "housing",
        "utilities",
        "rent",
        "shopping",
        "clothing",
        "health",
        "education",
        "entertainment",
        "subscriptions",
        "communication",
        "internet",
        "travel",
        "fuel",
        "car",
        "home",
        "technology",
        "gifts",
        "pets",
        "sports",
        "beauty",
        "taxes",
        "loans",
        "insurance",
        "investments",
        "charity",
        "other_expense",
        "unclear",
    }

    if ai_category in allowed_categories:

        return ai_category

    return "other_expense"


