# ============================================================
# TRANSLATION
# ============================================================

def t(
    language: str,
    key: str,
    **kwargs,
) -> str:
    if language not in TEXTS:
        language = DEFAULT_LANGUAGE

    text = TEXTS[language].get(key)

    if text is None:
        text = TEXTS[DEFAULT_LANGUAGE].get(
            key,
            key,
        )

    if kwargs:
        try:
            text = text.format(**kwargs)
        except (KeyError, ValueError):
            pass

    return text


def get_language(user_id: int) -> str:
    language = get_user_language(user_id)

    if language in TEXTS:
        return language

    return DEFAULT_LANGUAGE

def get_user_timezone_or_default(user_id: int) -> str:
    timezone = get_user_timezone(user_id)

    if timezone:
        return timezone

    language = get_language(user_id)

    if language == "ru":
        timezone = "Europe/Moscow"
    else:
        timezone = "America/New_York"

    update_user_settings(
        telegram_id=user_id,
        timezone=timezone,
    )

    return timezone

# ============================================================
# AMOUNT
# ============================================================

def normalize_amount(value: str):
    value = value.strip()
    value = value.replace(" ", "")
    value = value.replace(",", ".")

    if not re.fullmatch(
        r"\d+(?:\.\d{1,2})?",
        value,
    ):
        return None

    try:
        amount = float(value)
    except ValueError:
        return None

    if amount <= 0:
        return None

    return amount


def format_amount(amount: float) -> str:
    if float(amount).is_integer():
        return f"{int(amount):,}".replace(",", " ")

    return f"{amount:,.2f}".replace(",", " ")


# ============================================================
# TRANSACTION PARSER
# ============================================================

TRANSACTION_NUMBER_RE = re.compile(
    r"(?<!\d)"
    r"(?:\d{1,3}(?:[ \u00A0]\d{3})+|\d+)"
    r"(?:[.,]\d{1,2})?"
    r"(?!\d)"
)

# ============================================================
# КЭШ КОТИРОВОК
# ============================================================

INVESTMENT_QUOTES_CACHE_FILE = (
    "investment_quotes_cache.json"
)


def load_investment_quotes_cache():

    try:

        with open(
            INVESTMENT_QUOTES_CACHE_FILE,
            "r",
            encoding="utf-8",
        ) as file:

            data = json.load(file)

        if isinstance(data, dict):
            return data

    except (
        FileNotFoundError,
        json.JSONDecodeError,
        OSError,
    ):
        pass

    return {}


def save_investment_quotes_cache(
    cache: dict,
):

    try:

        with open(
            INVESTMENT_QUOTES_CACHE_FILE,
            "w",
            encoding="utf-8",
        ) as file:

            json.dump(
                cache,
                file,
                ensure_ascii=False,
                indent=2,
            )

    except OSError as e:

        print(
            "ОШИБКА СОХРАНЕНИЯ КЭША:",
            repr(e),
        )


INVESTMENT_QUOTES_CACHE = (
    load_investment_quotes_cache()
)


# ============================================================
# СОХРАНЕНИЕ КОТИРОВКИ
# ============================================================

def save_investment_quote_to_cache(
    cache_key: str,
    quote: dict,
):

    INVESTMENT_QUOTES_CACHE[
        cache_key
    ] = quote

    save_investment_quotes_cache(
        INVESTMENT_QUOTES_CACHE
    )


# ============================================================
# ПРОВЕРКА ВОЗРАСТА КОТИРОВКИ
# ============================================================

def investment_quote_is_fresh(
    quote: dict | None,
    max_age_hours: int = 24,
):

    if not isinstance(
        quote,
        dict,
    ):
        return False

    if quote.get("price") is None:
        return False

    fetched_at = quote.get(
        "fetched_at"
    )

    if not fetched_at:
        return False

    try:

        fetched_dt = datetime.fromisoformat(
            str(fetched_at)
        )

    except (
        TypeError,
        ValueError,
    ):

        return False

    now = datetime.now()

    # Если datetime вдруг содержит timezone,
    # убираем timezone для простого сравнения.
    if fetched_dt.tzinfo is not None:

        fetched_dt = (
            fetched_dt.replace(
                tzinfo=None
            )
        )

    age = (
        now
        - fetched_dt
    )

    return (
        age.total_seconds()
        < max_age_hours * 60 * 60
    )


# ============================================================
# ПОЛУЧЕНИЕ КОТИРОВКИ АКЦИИ
# ============================================================

async def get_investment_quote(
    company: dict,
    force: bool = False,
):

    # --------------------------------------------------------
    # ПРОВЕРЯЕМ API-КЛЮЧ
    # --------------------------------------------------------

    if not TWELVE_DATA_API_KEY:

        print(
            "ОШИБКА: "
            "TWELVE_DATA_API_KEY не найден "
            "в .env"
        )

        return None

    # --------------------------------------------------------
    # SYMBOL
    # --------------------------------------------------------

    symbol = (
        company.get("symbol")
        or company.get("ticker")
    )

    if not symbol:
        return None

    symbol = str(
        symbol
    ).upper().strip()

    # --------------------------------------------------------
    # ВАЛЮТА
    # --------------------------------------------------------

    currency = (
        company.get("currency")
        or "USD"
    )

    currency = str(
        currency
    ).upper().strip()

    # --------------------------------------------------------
    # БИРЖА
    # --------------------------------------------------------

    exchange = (
        company.get("exchange")
        or "MOEX"
        if currency == "RUB"
        else None
    )

    # --------------------------------------------------------
    # КЛЮЧ КЭША
    # --------------------------------------------------------

    cache_key = (
        f"{currency}:{symbol}"
    )

    # --------------------------------------------------------
    # СТАРАЯ СОХРАНЁННАЯ КОТИРОВКА
    # --------------------------------------------------------

    cached_quote = (
        INVESTMENT_QUOTES_CACHE.get(
            cache_key
        )
    )

    # --------------------------------------------------------
    # ЕСЛИ НЕ FORCE И КОТИРОВКА СВЕЖАЯ —
    # НЕ ДЕЛАЕМ НОВЫЙ ЗАПРОС
    # --------------------------------------------------------

    if (
        not force
        and investment_quote_is_fresh(
            cached_quote,
            max_age_hours=24,
        )
    ):

        return cached_quote

    # --------------------------------------------------------
    # SYMBOL ДЛЯ TWELVE DATA
    # --------------------------------------------------------

    request_symbol = symbol

    # --------------------------------------------------------
    # ПАРАМЕТРЫ TWELVE DATA
    # --------------------------------------------------------

    params = {
        "symbol": request_symbol,
        "interval": "1day",
        "outputsize": 2,
        "apikey": TWELVE_DATA_API_KEY,
    }

    if currency == "RUB" and exchange:

        params["exchange"] = exchange

    # --------------------------------------------------------
    # ЗАПРОС
    # --------------------------------------------------------

    url = (
        "https://api.twelvedata.com/"
        "time_series"
    )

    timeout = aiohttp.ClientTimeout(
        total=15,
        connect=5,
    )

    try:

        async with aiohttp.ClientSession(
            timeout=timeout,
            headers={
                "User-Agent": (
                    "Mozilla/5.0 "
                    "PocketFinanceAI/1.0"
                ),
                "Accept": (
                    "application/json"
                ),
            },
        ) as session:

            async with session.get(
                url,
                params=params,
            ) as response:

                response_text = (
                    await response.text()
                )

                # ------------------------------------------------
                # HTTP ОШИБКА
                # ------------------------------------------------

                if response.status != 200:

                    print(
                        "TWELVE DATA HTTP:",
                        response.status,
                        request_symbol,
                        response_text[:500],
                    )

                    if (
                        isinstance(
                            cached_quote,
                            dict,
                        )
                        and
                        cached_quote.get(
                            "price"
                        ) is not None
                    ):

                        return cached_quote

                    return None

                # ------------------------------------------------
                # JSON
                # ------------------------------------------------

                try:

                    data = json.loads(
                        response_text
                    )

                except json.JSONDecodeError:

                    print(
                        "TWELVE DATA: "
                        "не удалось прочитать JSON:",
                        request_symbol,
                    )

                    if (
                        isinstance(
                            cached_quote,
                            dict,
                        )
                        and
                        cached_quote.get(
                            "price"
                        ) is not None
                    ):

                        return cached_quote

                    return None

    except (
        asyncio.TimeoutError,
        TimeoutError,
        aiohttp.ClientError,
    ) as e:

        print(
            "ОШИБКА TWELVE DATA:",
            request_symbol,
            repr(e),
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    except Exception as e:

        print(
            "НЕОЖИДАННАЯ ОШИБКА "
            "TWELVE DATA:",
            request_symbol,
            repr(e),
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # ------------------------------------------------------------
    # ПРОВЕРЯЕМ ОШИБКУ TWELVE DATA В JSON
    # ------------------------------------------------------------

    if not isinstance(
        data,
        dict,
    ):

        print(
            "TWELVE DATA: "
            "неверный формат ответа:",
            request_symbol,
        )

        return cached_quote

    if data.get("status") == "error":

        print(
            "TWELVE DATA API:",
            request_symbol,
            data.get("code"),
            data.get("message"),
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # ------------------------------------------------------------
    # ПОЛУЧАЕМ VALUES
    # ------------------------------------------------------------

    values = data.get(
        "values"
    )

    if not isinstance(
        values,
        list,
    ) or not values:

        print(
            "TWELVE DATA: "
            "котировки отсутствуют:",
            request_symbol,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # ------------------------------------------------------------
    # ПОСЛЕДНЯЯ И ПРЕДЫДУЩАЯ КОТИРОВКИ
    # ------------------------------------------------------------

    latest = values[0]

    previous = (
        values[1]
        if len(values) > 1
        else None
    )

    if not isinstance(
        latest,
        dict,
    ):

        return cached_quote

    # ------------------------------------------------------------
    # ЦЕНА
    # ------------------------------------------------------------

    try:

        price = float(
            latest.get(
                "close"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        print(
            "TWELVE DATA: "
            "не удалось получить цену:",
            request_symbol,
            latest,
        )

        return cached_quote

    # ------------------------------------------------------------
    # ПРЕДЫДУЩАЯ ЦЕНА
    # ------------------------------------------------------------

    previous_price = None

    if isinstance(
        previous,
        dict,
    ):

        try:

            previous_price = float(
                previous.get(
                    "close"
                )
            )

        except (
            TypeError,
            ValueError,
        ):

            previous_price = None

    # ------------------------------------------------------------
    # ИЗМЕНЕНИЕ
    # ------------------------------------------------------------

    change = None
    change_percent = None

    if previous_price is not None:

        change = (
            price
            - previous_price
        )

        if previous_price != 0:

            change_percent = (
                change
                / previous_price
                * 100
            )

    # ------------------------------------------------------------
    # OPEN / HIGH / LOW
    # ------------------------------------------------------------

    try:

        open_price = float(
            latest.get(
                "open"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        open_price = None

    try:

        high_price = float(
            latest.get(
                "high"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        high_price = None

    try:

        low_price = float(
            latest.get(
                "low"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        low_price = None

    # ------------------------------------------------------------
    # ВОЛАТИЛЬНОСТЬ
    # ------------------------------------------------------------

    volatility_percent = None

    if (
        open_price is not None
        and open_price != 0
        and high_price is not None
        and low_price is not None
    ):

        volatility_percent = (
            (
                high_price
                - low_price
            )
            / open_price
            * 100
        )

    # ------------------------------------------------------------
    # ДАТА РЫНКА
    # ------------------------------------------------------------

    market_datetime = (
        latest.get(
            "datetime"
        )
    )

    # ------------------------------------------------------------
    # ВРЕМЯ ПОЛУЧЕНИЯ
    # ------------------------------------------------------------

    fetched_at = (
        datetime.now(
            ZoneInfo(
                "Europe/Moscow"
            )
        ).isoformat()
    )

    # ------------------------------------------------------------
    # СОЗДАЁМ КОТИРОВКУ
    # ------------------------------------------------------------

    quote = {

        "symbol": symbol,

        "price": price,

        "currency": currency,

        "change": change,

        "change_percent": (
            change_percent
        ),

        "open": open_price,

        "high": high_price,

        "low": low_price,

        "volatility_percent": (
            volatility_percent
        ),

        "market_datetime": (
            market_datetime
        ),

        "fetched_at": (
            fetched_at
        ),

        "source": "Twelve Data",
    }

    # ------------------------------------------------------------
    # СОХРАНЯЕМ В КЭШ
    # ------------------------------------------------------------

    INVESTMENT_QUOTES_CACHE[
        cache_key
    ] = quote

    save_investment_quotes_cache(
        INVESTMENT_QUOTES_CACHE
    )

    # ------------------------------------------------------------
    # ЛОГ
    # ------------------------------------------------------------

    print(
        "КОТИРОВКА ПОЛУЧЕНА:",
        request_symbol,
        price,
        currency,
    )

    return quote

    # --------------------------------------------------------
    # ПРОВЕРЯЕМ ОТВЕТ TWELVE DATA
    # --------------------------------------------------------

    if not isinstance(
        data,
        dict,
    ):

        print(
            "TWELVE DATA: "
            "неверный формат ответа:",
            symbol,
        )

        return cached_quote

    # --------------------------------------------------------
    # API МОЖЕТ ВЕРНУТЬ ОШИБКУ С HTTP 200
    # --------------------------------------------------------

    if data.get("status") == "error":

        print(
            "TWELVE DATA API ERROR:",
            symbol,
            data.get("message"),
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # --------------------------------------------------------
    # ПОЛУЧАЕМ VALUES
    # --------------------------------------------------------

    values = data.get(
        "values"
    )

    if not isinstance(
        values,
        list,
    ) or not values:

        print(
            "TWELVE DATA: "
            "нет values:",
            symbol,
            data,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # --------------------------------------------------------
    # ПОСЛЕДНЯЯ И ПРЕДЫДУЩАЯ ТОРГОВАЯ СЕССИЯ
    # --------------------------------------------------------

    latest = values[0]

    previous = (
        values[1]
        if len(values) > 1
        else None
    )

    # --------------------------------------------------------
    # ЦЕНА
    # --------------------------------------------------------

    try:

        price = float(
            latest["close"]
        )

    except (
        KeyError,
        TypeError,
        ValueError,
    ):

        print(
            "TWELVE DATA: "
            "не удалось получить close:",
            symbol,
            latest,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # --------------------------------------------------------
    # ИЗМЕНЕНИЕ ЗА ДЕНЬ
    # --------------------------------------------------------

    change = None
    change_percent = None

    if isinstance(
        previous,
        dict,
    ):

        try:

            previous_close = float(
                previous["close"]
            )

            change = (
                price
                - previous_close
            )

            if previous_close != 0:

                change_percent = (
                    change
                    / previous_close
                    * 100
                )

        except (
            KeyError,
            TypeError,
            ValueError,
        ):

            pass

    # --------------------------------------------------------
    # OPEN / HIGH / LOW
    # --------------------------------------------------------

    daily_open = None
    daily_high = None
    daily_low = None

    try:

        daily_open = float(
            latest["open"]
        )

    except (
        KeyError,
        TypeError,
        ValueError,
    ):

        pass

    try:

        daily_high = float(
            latest["high"]
        )

    except (
        KeyError,
        TypeError,
        ValueError,
    ):

        pass

    try:

        daily_low = float(
            latest["low"]
        )

    except (
        KeyError,
        TypeError,
        ValueError,
    ):

        pass

    # --------------------------------------------------------
    # ВОЛАТИЛЬНОСТЬ
    # --------------------------------------------------------

    volatility_percent = None

    if (
        daily_open is not None
        and daily_high is not None
        and daily_low is not None
        and daily_open != 0
    ):

        volatility_percent = (
            (
                daily_high
                - daily_low
            )
            / daily_open
            * 100
        )

    # --------------------------------------------------------
    # ВРЕМЯ РЫНКА
    # --------------------------------------------------------

    market_datetime = (
        latest.get(
            "datetime"
        )
    )

    # --------------------------------------------------------
    # ВРЕМЯ ПОЛУЧЕНИЯ ДАННЫХ
    # --------------------------------------------------------

    fetched_at = datetime.now(
        ZoneInfo("Europe/Moscow")
    ).isoformat()

    # --------------------------------------------------------
    # СОЗДАЁМ КОТИРОВКУ
    # --------------------------------------------------------

    quote = {
        "symbol": symbol,
        "price": price,
        "currency": currency,
        "change": change,
        "change_percent": change_percent,
        "open": daily_open,
        "high": daily_high,
        "low": daily_low,
        "volatility_percent": volatility_percent,
        "market_datetime": market_datetime,
        "fetched_at": fetched_at,
        "source": "Twelve Data",
    }

    # --------------------------------------------------------
    # СОХРАНЯЕМ В КЭШ
    # --------------------------------------------------------

    INVESTMENT_QUOTES_CACHE[
        cache_key
    ] = quote

    save_investment_quotes_cache(
        INVESTMENT_QUOTES_CACHE
    )

    print(
        "КОТИРОВКА ПОЛУЧЕНА:",
        symbol,
        price,
        currency,
        (
            f"{change_percent:.2f}%"
            if change_percent is not None
            else "изменение н/д"
        ),
    )

    return quote

    # ========================================================
    # ПРОВЕРЯЕМ ОТВЕТ TWELVE DATA
    # ========================================================

    if not isinstance(
        data,
        dict,
    ):

        return cached_quote

    if data.get("status") == "error":

        print(
            "TWELVE DATA ERROR:",
            symbol,
            data.get(
                "message"
            ),
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    values = data.get(
        "values"
    )

    if not isinstance(
        values,
        list,
    ):

        print(
            "TWELVE DATA: "
            "нет values:",
            symbol,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    if not values:

        print(
            "TWELVE DATA: "
            "пустой values:",
            symbol,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # ========================================================
    # ПОСЛЕДНИЙ ТОРГОВЫЙ ДЕНЬ
    # ========================================================

    latest = values[0]

    if not isinstance(
        latest,
        dict,
    ):

        return cached_quote

    # ========================================================
    # ЦЕНА
    # ========================================================

    try:

        price = float(
            latest.get(
                "close"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        price = None

    if (
        price is None
        or
        price <= 0
    ):

        print(
            "TWELVE DATA: "
            "некорректная цена:",
            symbol,
        )

        if (
            isinstance(
                cached_quote,
                dict,
            )
            and
            cached_quote.get(
                "price"
            ) is not None
        ):

            return cached_quote

        return None

    # ========================================================
    # ПРЕДЫДУЩЕЕ ЗАКРЫТИЕ
    # ========================================================

    previous_price = None

    if len(values) >= 2:

        previous = values[1]

        if isinstance(
            previous,
            dict,
        ):

            try:

                previous_price = float(
                    previous.get(
                        "close"
                    )
                )

            except (
                TypeError,
                ValueError,
            ):

                previous_price = None

            if (
                previous_price is not None
                and
                previous_price <= 0
            ):

                previous_price = None

    # ========================================================
    # ИЗМЕНЕНИЕ
    # ========================================================

    change = None
    change_percent = None

    if (
        previous_price is not None
        and
        previous_price > 0
    ):

        change = (
            price
            - previous_price
        )

        change_percent = (
            change
            / previous_price
            * 100
        )

    # ========================================================
    # HIGH / LOW / OPEN
    # ========================================================

    high = None
    low = None
    open_price = None

    try:

        high = float(
            latest.get(
                "high"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        high = None

    try:

        low = float(
            latest.get(
                "low"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        low = None

    try:

        open_price = float(
            latest.get(
                "open"
            )
        )

    except (
        TypeError,
        ValueError,
    ):

        open_price = None

    # ========================================================
    # ДНЕВНОЙ ДИАПАЗОН
    #
    # Используется существующей карточкой
    # как показатель волатильности.
    # ========================================================

    volatility_percent = None

    if (
        high is not None
        and
        low is not None
        and
        open_price is not None
        and
        open_price > 0
    ):

        volatility_percent = (
            (
                high
                - low
            )
            / open_price
            * 100
        )

    # ========================================================
    # ДАТА ПОСЛЕДНЕЙ КОТИРОВКИ
    # ========================================================

    market_datetime = (
        latest.get(
            "datetime"
        )
    )

    # ========================================================
    # СОХРАНЯЕМ КОТИРОВКУ
    # ========================================================

    quote = {
        "price": price,

        "change": change,

        "change_percent": (
            change_percent
        ),

        "currency": currency,

        "source": "Twelve Data",

        "fetched_at": (
            datetime.now().isoformat()
        ),

        "market_datetime": (
            market_datetime
        ),

        "previous_price": (
            previous_price
        ),

        "open": open_price,

        "high": high,

        "low": low,

        "volatility_percent": (
            volatility_percent
        ),
    }

    save_investment_quote_to_cache(
        cache_key,
        quote,
    )

    print(
        "КОТИРОВКА ОБНОВЛЕНА:",
        symbol,
        price,
        currency,
    )

    return quote

