def investments_keyboard(
    language: str,
):

    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text=t(
                        language,
                        "investment_search",
                    ),
                    callback_data="investment_search",
                ),
            ],
            [
                InlineKeyboardButton(
                    text=t(
                        language,
                        "investment_usa",
                    ),
                    callback_data="investment_region_usa",
                ),
            ],
            [
                InlineKeyboardButton(
                    text=t(
                        language,
                        "investment_europe",
                    ),
                    callback_data="investment_region_europe",
                ),
            ],
            [
                InlineKeyboardButton(
                    text=t(
                        language,
                        "investment_russia",
                    ),
                    callback_data="investment_region_russia",
                ),
            ],
            [
                InlineKeyboardButton(
                    text=t(
                        language,
                        "investment_other",
                    ),
                    callback_data="investment_region_other",
                ),
            ],
            [
                InlineKeyboardButton(
                    text=(
                        "🏠 В меню"
                        if language == "ru"
                        else "🏠 Main menu"
                    ),
                    callback_data="investment_main_menu",
                ),
            ],
        ]
    )


def investment_company_list_keyboard(
    language: str,
    region: str,
):

    companies = INVESTMENT_COMPANIES.get(
        region,
        [],
    )

    rows = []

    for index, company in enumerate(
        companies
    ):

        name = (
            company["name_ru"]
            if language == "ru"
            else company["name_en"]
        )

        rows.append(
            [
                InlineKeyboardButton(
                    text=name,
                    callback_data=(
                        f"investment_company:"
                        f"{region}:{index}"
                    ),
                )
            ]
        )

    rows.append(
        [
            InlineKeyboardButton(
                text=t(
                    language,
                    "investment_refresh",
                ),
                callback_data=(
                    f"investment_region:{region}"
                ),
            )
        ]
    )

    rows.append(
        [
            InlineKeyboardButton(
                text=t(
                    language,
                    "investment_back",
                ),
                callback_data="investments",
            ),
            InlineKeyboardButton(
                text=(
                    "🏠 В меню"
                    if language == "ru"
                    else "🏠 Main menu"
                ),
                callback_data="investment_main_menu",
            ),
        ]
    )

    return InlineKeyboardMarkup(
        inline_keyboard=rows
    )

# ============================================================
# НОРМАЛИЗАЦИЯ ПОИСКА КОМПАНИЙ
# ============================================================

def normalize_company_search(
    value: str,
) -> str:

    value = (
        value
        .strip()
        .casefold()
    )

    value = re.sub(
        r"\s+",
        " ",
        value,
    )

    return value


def find_investment_company(
    query: str,
):

    normalized_query = (
        normalize_company_search(
            query
        )
    )

    for region, companies in (
        INVESTMENT_COMPANIES.items()
    ):

        for index, company in enumerate(
            companies
        ):

            names = {
                company["name_ru"],
                company["name_en"],
                company["ticker"],
                company.get(
                    "symbol",
                    "",
                ),
            }

            for name in names:

                if not name:
                    continue

                if (
                    normalize_company_search(
                        name
                    )
                    == normalized_query
                ):

                    return (
                        region,
                        index,
                        company,
                    )

    return None


