# ОБЩИЕ НАЗВАНИЯ РЕГИОНОВ
# ============================================================

def investment_region_title(
    language: str,
    region: str,
):

    titles = {
        "ru": {
            "usa": "🇺🇸 США",
            "europe": "🇪🇺 Европа",
            "russia": "🇷🇺 Россия",
            "other": "🌎 Другие",
        },
        "en": {
            "usa": "🇺🇸 USA",
            "europe": "🇪🇺 Europe",
            "russia": "🇷🇺 Russia",
            "other": "🌎 Other",
        },
    }

    return titles.get(
        language,
        titles["en"],
    ).get(
        region,
        region,
    )


# ============================================================
# ИНВЕСТИЦИИ — РЕГИОН
# ============================================================

@dp.callback_query(
    F.data.startswith("investment_region:")
)
async def investment_region_handler(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id
    language = get_language(user_id)
    if not is_premium_active(user_id):
        await callback.answer()
        await callback.message.edit_text(
            premium_required_text(language),
            reply_markup=premium_required_keyboard(language),
        )
        return
    region = callback.data.split(
        ":",
        1,
    )[1]

    if region not in INVESTMENT_COMPANIES:

        await callback.answer()
        return

    await callback.answer()

    await callback.message.edit_text(
        investment_region_title(
            language,
            region,
        ),
        reply_markup=investment_company_list_keyboard(
            language,
            region,
        ),
    )


