# ============================================================
# ОПРЕДЕЛЕНИЕ ВОЛАТИЛЬНОСТИ
# ============================================================

def get_investment_volatility_key(
    quote: dict | None,
):

    if not isinstance(
        quote,
        dict,
    ):

        return "investment_neutral"

    volatility_percent = quote.get(
        "volatility_percent"
    )

    if volatility_percent is None:

        return "investment_neutral"

    try:

        volatility_percent = abs(
            float(volatility_percent)
        )

    except (
        TypeError,
        ValueError,
    ):

        return "investment_neutral"

    if volatility_percent < 1:

        return "investment_low"

    if volatility_percent <= 3:

        return "investment_medium"

    return "investment_high"


# ============================================================
# ФОРМИРОВАНИЕ ВЫВОДА
# ============================================================

def get_investment_conclusion(
    language: str,
    dynamic_key: str,
    volatility_key: str,
):

    if language == "ru":

        if (
            dynamic_key
            == "investment_positive"
            and
            volatility_key
            == "investment_low"
        ):

            return (
                "Компания показывает "
                "положительную динамику "
                "при относительно небольшом "
                "дневном диапазоне цены."
            )

        if (
            dynamic_key
            == "investment_positive"
            and
            volatility_key
            == "investment_high"
        ):

            return (
                "Компания показывает "
                "положительную динамику, "
                "но дневные колебания цены "
                "остаются высокими."
            )

        if (
            dynamic_key
            == "investment_negative"
            and
            volatility_key
            == "investment_high"
        ):

            return (
                "Компания показывает "
                "отрицательную динамику "
                "при высоких дневных "
                "колебаниях цены."
            )

        if (
            dynamic_key
            == "investment_negative"
        ):

            return (
                "Компания показывает "
                "отрицательную динамику "
                "за текущий торговый период."
            )

        if (
            dynamic_key
            == "investment_neutral"
        ):

            return (
                "Цена акции изменилась "
                "незначительно относительно "
                "предыдущего закрытия."
            )

        return (
            "Текущая динамика акции "
            "требует наблюдения за дальнейшим "
            "изменением цены."
        )

    if (
        dynamic_key
        == "investment_positive"
        and
        volatility_key
        == "investment_low"
    ):

        return (
            "The company is showing "
            "positive momentum with a "
            "relatively small daily price range."
        )

    if (
        dynamic_key
        == "investment_positive"
        and
        volatility_key
        == "investment_high"
    ):

        return (
            "The company is showing "
            "positive momentum, but daily "
            "price fluctuations remain high."
        )

    if (
        dynamic_key
        == "investment_negative"
        and
        volatility_key
        == "investment_high"
    ):

        return (
            "The company is showing "
            "negative momentum with high "
            "daily price fluctuations."
        )

    if (
        dynamic_key
        == "investment_negative"
    ):

        return (
            "The company is showing "
            "negative momentum during "
            "the current trading period."
        )

    if (
        dynamic_key
        == "investment_neutral"
    ):

        return (
            "The share price has changed "
            "only slightly compared with "
            "the previous close."
        )

    return (
        "The current share-price trend "
        "requires further observation."
    )


# ============================================================
# ФОРМИРОВАНИЕ КАРТОЧКИ
# ============================================================

def build_investment_company_text(
    language: str,
    company: dict,
    quote: dict | None,
):

    name = (
        company["name_ru"]
        if language == "ru"
        else company["name_en"]
    )

    description = (
        company["description_ru"]
        if language == "ru"
        else company["description_en"]
    )

    currency = (
        str(
            company.get(
                "currency",
                "USD",
            )
        )
        .upper()
    )

    currency_symbol = {
        "USD": "$",
        "RUB": "₽",
        "EUR": "€",
        "GBP": "£",
    }.get(
        currency,
        currency,
    )

    # ========================================================
    # ЦЕНА
    # ========================================================

    if (
        isinstance(
            quote,
            dict,
        )
        and
        quote.get("price") is not None
    ):

        try:

            price = float(
                quote["price"]
            )

        except (
            TypeError,
            ValueError,
        ):

            price = None

        if price is not None:

            price_text = (
                f"{price:,.2f}"
                .replace(",", " ")
                + f" {currency_symbol}"
            )

            # =================================================
            # ДИНАМИКА
            # =================================================

            change_percent = quote.get(
                "change_percent"
            )

            try:

                change_percent = (
                    float(change_percent)
                    if change_percent is not None
                    else None
                )

            except (
                TypeError,
                ValueError,
            ):

                change_percent = None

            if change_percent is None:

                dynamic_key = (
                    "investment_neutral"
                )

                dynamic_text = t(
                    language,
                    dynamic_key,
                )

            elif change_percent > 0:

                dynamic_key = (
                    "investment_positive"
                )

                dynamic_text = (
                    f"{t(language, dynamic_key)} "
                    f"(+{change_percent:.2f}%)"
                )

            elif change_percent < 0:

                dynamic_key = (
                    "investment_negative"
                )

                dynamic_text = (
                    f"{t(language, dynamic_key)} "
                    f"({change_percent:.2f}%)"
                )

            else:

                dynamic_key = (
                    "investment_neutral"
                )

                dynamic_text = t(
                    language,
                    dynamic_key,
                )

            # =================================================
            # ВОЛАТИЛЬНОСТЬ
            # =================================================

            volatility_key = (
                get_investment_volatility_key(
                    quote
                )
            )

            volatility_text = t(
                language,
                volatility_key,
            )

            conclusion = (
                get_investment_conclusion(
                    language,
                    dynamic_key,
                    volatility_key,
                )
            )

        else:

            price_text = t(
                language,
                "investment_price_unavailable",
            )

            dynamic_key = (
                "investment_neutral"
            )

            dynamic_text = t(
                language,
                dynamic_key,
            )

            volatility_key = (
                "investment_neutral"
            )

            volatility_text = t(
                language,
                volatility_key,
            )

            conclusion = (
                "Цена временно недоступна."
                if language == "ru"
                else
                "The price is temporarily unavailable."
            )

    else:

        price_text = t(
            language,
            "investment_price_unavailable",
        )

        dynamic_key = (
            "investment_neutral"
        )

        dynamic_text = t(
            language,
            dynamic_key,
        )

        volatility_key = (
            "investment_neutral"
        )

        volatility_text = t(
            language,
            volatility_key,
        )

        conclusion = (
            "Цена ещё не была получена "
            "из источника данных."
            if language == "ru"
            else
            "The price has not yet been "
            "received from the data source."
        )

    # ========================================================
    # ДАТА РЫНКА
    # ========================================================

    market_datetime = None

    if isinstance(
        quote,
        dict,
    ):

        market_datetime = quote.get(
            "market_datetime"
        )

    market_text = ""

    if market_datetime:

        market_text = (
            "\n\n"
            + (
                "🕒 Данные рынка: "
                if language == "ru"
                else
                "🕒 Market data: "
            )
            + str(
                market_datetime
            )
        )

    # ========================================================
    # ВРЕМЯ ОБНОВЛЕНИЯ КЭША
    # ========================================================

    fetched_at = None

    if isinstance(
        quote,
        dict,
    ):

        fetched_at = quote.get(
            "fetched_at"
        )

    updated_text = ""

    if fetched_at:

        try:

            fetched_dt = datetime.fromisoformat(
                str(fetched_at)
            )

            updated_text = (
                "\n"
                + (
                    "🕐 Получено: "
                    if language == "ru"
                    else
                    "🕐 Retrieved: "
                )
                + fetched_dt.strftime(
                    "%d.%m.%Y %H:%M"
                )
            )

        except (
            TypeError,
            ValueError,
        ):

            updated_text = ""

    return (
        f"📈 {name}\n\n"
        f"{description}\n\n"
        f"💵 {price_text}\n"
        f"📊 {company['ticker']}\n\n"
        f"📈 {dynamic_text}\n"
        f"⚠️ "
        f"{'Волатильность' if language == 'ru' else 'Volatility'}: "
        f"{volatility_text}\n\n"
        f"💡 {conclusion}"
        f"{market_text}"
        f"{updated_text}"
    )

# ============================================================
# КОТИРОВКИ РОССИЙСКИХ КОМПАНИЙ — MOEX ISS
# ============================================================

async def get_moex_investment_quote(
    company: dict,
):

    symbol = (
        company.get("symbol")
        or company.get("ticker")
    )

    if not symbol:
        return None

    symbol = symbol.upper()

    cache_key = f"RUB:{symbol}"

    # --------------------------------------------------------
    # СНАЧАЛА ПРОБУЕМ ВЗЯТЬ УЖЕ ПОЛУЧЕННУЮ КОТИРОВКУ
    # --------------------------------------------------------

    cached_quote = (
        INVESTMENT_QUOTES_CACHE.get(
            cache_key
        )
    )

    if cached_quote:

        return cached_quote

    return None

# ============================================================
# ОБНОВЛЕНИЕ ВСЕХ РОССИЙСКИХ КОТИРОВОК ОДНИМ ЗАПРОСОМ
# ============================================================

async def update_all_russian_quotes():

    url = (
        "https://iss.moex.com/iss/engines/stock/"
        "markets/shares/boards/TQBR/securities.json"
    )

    try:

        timeout = aiohttp.ClientTimeout(
            total=20
        )

        async with aiohttp.ClientSession(
            timeout=timeout
        ) as session:

            async with session.get(
                url,
                params={
                    "iss.meta": "off",
                    "iss.only": "marketdata,securities",
                },
            ) as response:

                if response.status != 200:

                    print(
                        "MOEX HTTP:",
                        response.status,
                    )

                    return False

                data = await response.json()

        # ----------------------------------------------------
        # MARKETDATA
        # ----------------------------------------------------

        marketdata = data.get(
            "marketdata",
            {}
        )
        securities = data.get(
            "securities",
            {}
        )
        columns = marketdata.get(
            "columns",
            []
        )

        rows = marketdata.get(
            "data",
            []
        )

        if not columns or not rows:

            print(
                "MOEX: ОБЩИЕ ДАННЫЕ ПУСТЫЕ"
            )

            return False

        # ----------------------------------------------------
        # ТИКЕРЫ НАШИХ РОССИЙСКИХ КОМПАНИЙ
        # ----------------------------------------------------

        russian_symbols = set()

        for company in INVESTMENT_COMPANIES.get(
            "russia",
            []
        ):

            symbol = (
                company.get("symbol")
                or company.get("ticker")
            )

            if symbol:

                russian_symbols.add(
                    symbol.upper()
                )

        updated = 0

        # ----------------------------------------------------
        # РАЗБИРАЕМ ВСЕ СТРОКИ MOEX
        # ----------------------------------------------------

        for row in rows:

            values = dict(
                zip(
                    columns,
                    row,
                )
            )

            symbol = values.get(
                "SECID"
            )

            if not symbol:

                continue

            symbol = str(
                symbol
            ).upper()

            if symbol not in russian_symbols:

                continue

            # ------------------------------------------------
            # ЦЕНА
            # ------------------------------------------------

            last = values.get(
                "LAST"
            )

            if last is None:

                last = values.get(
                    "LCLOSEPRICE"
                )

            if last is None:

                last = values.get(
                    "MARKETPRICE"
                )

            if last is None:

                continue

            try:

                last = float(last)

            except (
                TypeError,
                ValueError,
            ):

                continue
            

            # ------------------------------------------------
            # ИЗМЕНЕНИЕ
            # ------------------------------------------------

            change = values.get(
                "LASTCHANGE"
            )

            change_percent = values.get(
                "LASTTOPREVPRICE"
            )

            if change_percent is None:
                change_percent = values.get(
                    "LASTCHANGEPRCNT"
                )

            if change_percent is None:
                change_percent = values.get(
                    "CHANGEPRCNT"
                )

            previous_price = values.get(
                "PREVPRICE"
            )

            if previous_price is None:
                previous_price = values.get(
                    "LCLOSEPRICE"
                )

            # ------------------------------------------------
            # ПРЕДЫДУЩАЯ ЦЕНА ИЗ SECURITIES
            # ------------------------------------------------

            if previous_price is None:

                securities_columns = securities.get(
                    "columns",
                    []
                )

                securities_rows = securities.get(
                    "data",
                    []
                )

                for securities_row in securities_rows:

                    security_values = dict(
                        zip(
                            securities_columns,
                            securities_row,
                        )
                    )

                    security_symbol = str(
                        security_values.get(
                            "SECID",
                            ""
                        )
                    ).upper()

                    if security_symbol != symbol:
                        continue

                    previous_price = security_values.get(
                        "PREVPRICE"
                    )

                    if previous_price is None:
                        previous_price = security_values.get(
                            "LEGALCLOSEPRICE"
                        )

                    break

            try:

                if previous_price is not None:
                    previous_price = float(
                        str(previous_price)
                        .replace(",", ".")
                    )

            except (
                TypeError,
                ValueError,
            ):

                previous_price = None

            if (
                change_percent is None
                and previous_price is not None
                and previous_price != 0
            ):

                change_percent = (
                    (last - previous_price)
                    / previous_price
                    * 100
                )

            if (
                change is None
                and previous_price is not None
            ):

                change = (
                    last - previous_price
                )

            # ------------------------------------------------
            # OPEN / HIGH / LOW
            # ------------------------------------------------

            open_price = values.get(
                "OPEN"
            )

            high = values.get(
                "HIGH"
            )

            low = values.get(
                "LOW"
            )

            try:

                if open_price is not None:
                    open_price = float(
                        open_price
                    )

            except (
                TypeError,
                ValueError,
            ):

                open_price = None

            try:

                if high is not None:
                    high = float(high)

            except (
                TypeError,
                ValueError,
            ):

                high = None

            try:

                if low is not None:
                    low = float(low)

            except (
                TypeError,
                ValueError,
            ):

                low = None

            # ------------------------------------------------
            # ВОЛАТИЛЬНОСТЬ
            # ------------------------------------------------

            volatility_percent = None

            if (
                open_price is not None
                and open_price != 0
                and high is not None
                and low is not None
            ):

                volatility_percent = (
                    (
                        high - low
                    )
                    / open_price
                    * 100
                )

            # ------------------------------------------------
            # ВРЕМЯ
            # ------------------------------------------------

            market_datetime = (
                values.get(
                    "UPDATETIME"
                )
                or values.get(
                    "TIME"
                )
            )

            if market_datetime is not None:

                market_datetime = str(
                    market_datetime
                )

            fetched_at = datetime.now(
                ZoneInfo("Europe/Moscow")
            ).isoformat()

            # ------------------------------------------------
            # ГОТОВАЯ КОТИРОВКА
            # ------------------------------------------------

            quote = {

                "symbol": symbol,

                "price": last,

                "currency": "RUB",

                "change": change,

                "change_percent":
                    change_percent,

                "open": open_price,

                "high": high,

                "low": low,

                "volatility_percent":
                    volatility_percent,

                "market_datetime":
                    market_datetime,

                "fetched_at":
                    fetched_at,

                "source": "MOEX",
            }

            # ------------------------------------------------
            # СОХРАНЯЕМ В ОБЩИЙ КЭШ
            # ------------------------------------------------

            cache_key = (
                f"RUB:{symbol}"
            )

            INVESTMENT_QUOTES_CACHE[
                cache_key
            ] = quote

            updated += 1

            print(
                "MOEX КОТИРОВКА:",
                symbol,
                last,
                "RUB",
            )

        print(
            "MOEX: ОБНОВЛЕНО",
            f"{updated}/{len(russian_symbols)}",
        )

        return updated > 0

    except Exception as e:

        print(
            "ОШИБКА ОБЩЕГО MOEX:",
            repr(e),
        )

        return False


# ============================================================
# ОБНОВЛЕНИЕ ОДНОЙ КОМПАНИИ
# ============================================================

async def refresh_single_investment_company(
    company: dict,
    force: bool = False,
):

    try:

        # ----------------------------------------------------
        # РОССИЙСКИЕ КОМПАНИИ → MOEX
        # ----------------------------------------------------

        if company.get("currency") == "RUB":

            updated = await asyncio.wait_for(
                update_all_russian_quotes(),
                timeout=20,
            )

            if not updated:

                # Если MOEX временно не ответил,
                # пробуем показать последнюю цену
                return await get_moex_investment_quote(
                    company
                )

            return await get_moex_investment_quote(
                company
            )

        # ----------------------------------------------------
        # ВСЕ ОСТАЛЬНЫЕ → TWELVE DATA
        # ----------------------------------------------------

        quote = await asyncio.wait_for(
            get_investment_quote(
                company,
                force=force,
            ),
            timeout=20,
        )

        return quote

    except (
        asyncio.TimeoutError,
        TimeoutError,
    ):

        print(
            "ТАЙМАУТ КОТИРОВКИ:",
            company.get(
                "ticker",
                company.get(
                    "symbol",
                    "UNKNOWN",
                ),
            ),
        )

        # Даже при таймауте для РФ
        # пытаемся вернуть старую цену
        if company.get("currency") == "RUB":

            return await get_moex_investment_quote(
                company
            )

        return None

    except Exception as e:

        print(
            "ОШИБКА КОТИРОВКИ:",
            company.get(
                "ticker",
                company.get(
                    "symbol",
                    "UNKNOWN",
                ),
            ),
            repr(e),
        )

        if company.get("currency") == "RUB":

            return await get_moex_investment_quote(
                company
            )

        return None


# ============================================================
# ЕЖЕДНЕВНОЕ ОБНОВЛЕНИЕ ВСЕХ АКЦИЙ
# ============================================================

async def update_all_investment_quotes():

    print(
        "НАЧАЛО ОБНОВЛЕНИЯ КОТИРОВОК"
    )

    total = 0
    success = 0

    for region, companies in (
        INVESTMENT_COMPANIES.items()
    ):

        for company in companies:

            total += 1

            quote = await refresh_single_investment_company(
                company,
                force=False,
            )

            if (
                isinstance(
                    quote,
                    dict,
                )
                and
                quote.get(
                    "price"
                ) is not None
            ):

                success += 1

            # Небольшая пауза между запросами.
            # Это снижает вероятность упереться
            # в лимит API.
            await asyncio.sleep(
                8
            )

    print(
        "ОБНОВЛЕНИЕ КОТИРОВОК ЗАВЕРШЕНО:",
        f"{success}/{total}",
    )


# ============================================================
# ФОНОВОЕ ОБНОВЛЕНИЕ РАЗ В 24 ЧАСА
# ============================================================

async def investment_quotes_background_updater():

    while True:

        try:

            await update_all_investment_quotes()

        except Exception as e:

            print(
                "ОШИБКА ФОНОВОГО "
                "ОБНОВЛЕНИЯ КОТИРОВОК:",
                repr(e),
            )

        await asyncio.sleep(
            24 * 60 * 60
        )


# ============================================================
# ИНВЕСТИЦИИ — КАРТОЧКА КОМПАНИИ
# ============================================================

@dp.callback_query(
    F.data.startswith("investment_company:")
)
async def investment_company_handler(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    # --------------------------------------------------------
    # РАЗБИРАЕМ CALLBACK
    # --------------------------------------------------------

    parts = (
        callback.data or ""
    ).split(":")

    if len(parts) != 3:

        await callback.answer()
        return

    region = parts[1]

    try:

        index = int(
            parts[2]
        )

    except ValueError:

        await callback.answer()
        return

    # --------------------------------------------------------
    # ПОЛУЧАЕМ СПИСОК КОМПАНИЙ
    # --------------------------------------------------------

    companies = INVESTMENT_COMPANIES.get(
        region,
        [],
    )

    if not (
        0 <= index < len(companies)
    ):

        await callback.answer()
        return

    company = companies[index]

    # --------------------------------------------------------
    # ОТВЕЧАЕМ НА НАЖАТИЕ
    # --------------------------------------------------------

    await callback.answer()

    # --------------------------------------------------------
    # SYMBOL
    # --------------------------------------------------------

    symbol = (
        company.get("symbol")
        or company.get("ticker")
    )

    currency = (
        company.get("currency")
        or "USD"
    )

    if not symbol:

        await callback.message.edit_text(
            t(
                language,
                "investment_price_unavailable",
            ),
            reply_markup=investment_company_keyboard(
                language,
                region,
                index,
            ),
        )

        return

    symbol = str(
        symbol
    ).upper().strip()

    currency = str(
        currency
    ).upper().strip()

    # --------------------------------------------------------
    # КЭШ
    # --------------------------------------------------------

    cache_key = (
        f"{currency}:{symbol}"
    )

    cached_quote = (
        INVESTMENT_QUOTES_CACHE.get(
            cache_key
        )
    )

    # --------------------------------------------------------
    # ТЕКСТ КАРТОЧКИ
    # --------------------------------------------------------

    text = build_investment_company_text(
        language,
        company,
        cached_quote,
    )

    keyboard = investment_company_keyboard(
        language,
        region,
        index,
    )

    # --------------------------------------------------------
    # ПОКАЗЫВАЕМ КАРТОЧКУ
    # --------------------------------------------------------

    try:

        await callback.message.edit_text(
            text,
            reply_markup=keyboard,
        )

    except Exception as e:

        # Если сообщение уже содержит абсолютно
        # такой же текст и клавиатуру — просто
        # не считаем это ошибкой.

        if (
            "message is not modified"
            in str(e).lower()
        ):

            return

        print(
            "ОШИБКА ОТКРЫТИЯ КАРТОЧКИ "
            "ИНВЕСТИЦИИ:",
            repr(e),
        )

        return


# ============================================================
# ПРИНУДИТЕЛЬНОЕ ОБНОВЛЕНИЕ КАРТОЧКИ
# ============================================================

@dp.callback_query(
    F.data.startswith(
        "investment_company_refresh:"
    )
)
async def investment_company_refresh_handler(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    parts = callback.data.split(
        ":"
    )

    if len(parts) != 3:

        await callback.answer()
        return

    region = parts[1]

    try:

        index = int(
            parts[2]
        )

    except ValueError:

        await callback.answer()
        return

    companies = INVESTMENT_COMPANIES.get(
        region,
        [],
    )

    if not (
        0 <= index < len(companies)
    ):

        await callback.answer()
        return

    company = companies[index]

    await callback.answer()

    quote = await refresh_single_investment_company(
        company,
        force=True,
    )

    if (
        not isinstance(
            quote,
            dict,
        )
        or
        quote.get(
            "price"
        ) is None
    ):

        symbol = (
            company.get("symbol")
            or company.get("ticker")
        )

        currency = (
            company.get("currency")
            or "USD"
        )

        cache_key = (
            f"{str(currency).upper().strip()}:"
            f"{str(symbol).upper().strip()}"
        )

        quote = (
            INVESTMENT_QUOTES_CACHE.get(
                cache_key
            )
        )

    await callback.message.edit_text(
        build_investment_company_text(
            language,
            company,
            quote,
        ),
        reply_markup=investment_company_keyboard(
            language,
            region,
            index,
        ),
    )


