@dp.callback_query(
    F.data == "investment_search"
)
async def investment_search_handler(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    await state.set_state(
        FinanceStates.investment_search
    )

    await callback.answer()

    await callback.message.edit_text(
        t(
            language,
            "investment_search_prompt",
        ),
        reply_markup=InlineKeyboardMarkup(
            inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text="⬅️ Назад",
                        callback_data="investments",
                    ),
                    InlineKeyboardButton(
                        text=(
                            "🏠 В меню"
                            if language == "ru"
                            else "🏠 Main menu"
                        ),
                        callback_data="main_menu",
                    ),
                ],
            ]
        ),
    )


# ============================================================
# ОБРАБОТКА ПОИСКА КОМПАНИИ
# ============================================================

@dp.message(
    FinanceStates.investment_search
)
async def investment_search_input(
    message: Message,
    state: FSMContext,
):

    user_id = message.from_user.id
    language = get_language(user_id)

    query = (
        message.text or ""
    ).strip()

    if not query:

        await message.answer(
            t(
                language,
                "investment_not_found",
            )
        )

        return

    result = find_investment_company(
        query
    )

    if result is None:

        await message.answer(
            t(
                language,
                "investment_not_found",
            ),
            reply_markup=InlineKeyboardMarkup(
                inline_keyboard=[
                    [
                        InlineKeyboardButton(
                            text=t(
                                language,
                                "investment_back",
                            ),
                            callback_data="investments",
                        ),
                        InlineKeyboardButton(
                            text=(
                                "🏠 В меню"
                                if language == "ru"
                                else "🏠 Main menu"
                            ),
                            callback_data="main_menu",
                        ),
                    ],
                ]
            ),
        )

        return

    region, index, company = result

    await state.clear()

    symbol = (
        company.get("symbol")
        or company.get("ticker")
    )

    currency = (
        company.get("currency")
        or "USD"
    )

    cache_key = (
        f"{str(currency).upper().strip()}:"
        f"{str(symbol).upper().strip()}"
    )

    cached_quote = (
        INVESTMENT_QUOTES_CACHE.get(
            cache_key
        )
    )

    await message.answer(
        build_investment_company_text(
            language,
            company,
            cached_quote,
        ),
        reply_markup=investment_company_keyboard(
            language,
            region,
            index,
        ),
    )

