# ============================================================
# ПОЛНЫЙ РАЗБОР ОПЕРАЦИИ
# ============================================================

async def parse_transaction_text(
    text: str,
    transaction_type: str,
    language: str,
):
    """
    Сумма + валюта:
        OPENROUTER -> локальный fallback

    Категория:
        существующая система проекта:
        локальный словарь -> OPENROUTER -> Другое
    """

    # --------------------------------------------------------
    # 1. СУММА + ВАЛЮТА
    # --------------------------------------------------------

    try:

        ai_money = await parse_money_with_openrouter(
            text=text,
            transaction_type=transaction_type,
        )

    except Exception:

        ai_money = {
            "amount": None,
            "currency": None,
        }

    amount = ai_money.get(
        "amount"
    )

    currency = ai_money.get(
        "currency"
    )

    # --------------------------------------------------------
    # 2. ЕСЛИ AI НЕ ОПРЕДЕЛИЛ СУММУ —
    # ЛОКАЛЬНЫЙ FALLBACK
    # --------------------------------------------------------

    if amount is None:

        try:

            fallback_money = (
                extract_money_fallback(
                    text
                )
            )

        except Exception:

            fallback_money = {
                "amount": None,
                "currency": None,
            }

        amount = fallback_money.get(
            "amount"
        )

        currency = fallback_money.get(
            "currency"
        )

    # --------------------------------------------------------
    # 3. ТОЛЬКО RUB И USD
    # --------------------------------------------------------

    if currency not in {
        "RUB",
        "USD",
    }:

        if amount is not None:

            currency = "RUB"

        else:

            currency = None

    # --------------------------------------------------------
    # 4. КАТЕГОРИЯ
    #
    # ИСПОЛЬЗУЕМ СУЩЕСТВУЮЩУЮ ФУНКЦИЮ ПРОЕКТА.
    #
    # Она уже делает:
    #
    # локальный словарь
    #       ↓
    # OPENROUTER
    #       ↓
    # Другое
    #
    # --------------------------------------------------------

    try:

        category_result = (
            await detect_transaction_category(
                text=text,
                transaction_type=transaction_type,
                language=language,
            )
        )

    except Exception:

        category_result = None

    if isinstance(
        category_result,
        dict,
    ):

        category = (
            category_result.get(
                "category"
            )
        )

    else:

        category = category_result

    # --------------------------------------------------------
    # 5. ПОСЛЕДНЯЯ ЗАЩИТА
    # --------------------------------------------------------

    if not category:

        category = (
            "other_income"
            if transaction_type == "income"
            else "other_expense"
        )

    return {
        "amount": amount,
        "currency": currency,
        "category": category,
        "comment": text,
    }
# ============================================================
# ПРЕОБРАЗОВАНИЕ ЧИСЛА
# ============================================================

def parse_money_number(
    value: str,
):
    if not value:
        return None

    value = (
        value
        .strip()
        .replace("\u00A0", " ")
    )

    value = re.sub(
        r"\s+",
        "",
        value,
    )

    try:

        if "," in value and "." in value:

            if value.rfind(",") > value.rfind("."):

                value = (
                    value
                    .replace(".", "")
                    .replace(",", ".")
                )

            else:

                value = value.replace(
                    ",",
                    "",
                )

        elif "," in value:

            parts = value.split(",")

            if (
                len(parts) == 2
                and len(parts[1]) in (1, 2)
            ):

                value = (
                    parts[0]
                    + "."
                    + parts[1]
                )

            else:

                value = value.replace(
                    ",",
                    "",
                )

        amount = float(value)

        if amount <= 0:
            return None

        return amount

    except (
        TypeError,
        ValueError,
    ):
        return None


# ============================================================
# ЛОКАЛЬНЫЙ FALLBACK СУММЫ
# ============================================================

def extract_money_fallback(
    text: str,
):
    """
    Используется только если OPENROUTER
    не смог корректно определить сумму.

    Логика:
    1. Число рядом с валютой.
    2. Явная ценовая конструкция.
    3. Одно отдельное число.
    """

    if not text:
        return {
            "amount": None,
            "currency": None,
        }

    # --------------------------------------------------------
    # ВАЛЮТЫ
    # --------------------------------------------------------

    currency_patterns = {
        "RUB": (
            r"₽"
            r"|\bRUB\b"
            r"|\bруб(?:ль|ля|лей|ли)?\b"
            r"|\bруб\."
            r"|\bр\b"
        ),
        "USD": (
            r"\$"
            r"|\bUSD\b"
            r"|\bдоллар(?:а|ов|ы)?\b"
            r"|\bdollar(?:s)?\b"
        ),
    }

    currency_matches = []

    for currency, pattern in currency_patterns.items():

        for match in re.finditer(
            pattern,
            text,
            flags=re.IGNORECASE,
        ):

            currency_matches.append(
                {
                    "currency": currency,
                    "start": match.start(),
                    "end": match.end(),
                }
            )

    # --------------------------------------------------------
    # ЧИСЛА
    # --------------------------------------------------------

    number_matches = list(
        re.finditer(
            r"(?<![A-Za-zА-Яа-я0-9])"
            r"\d+"
            r"(?:[ \u00A0]\d{3})*"
            r"(?:[.,]\d{1,2})?"
            r"(?![A-Za-zА-Яа-я0-9])",
            text,
        )
    )

    if not number_matches:
        return {
            "amount": None,
            "currency": None,
        }

    found_currencies = {
        item["currency"]
        for item in currency_matches
    }

    # --------------------------------------------------------
    # 1. ЧИСЛО РЯДОМ С ВАЛЮТОЙ
    #
    # iPhone 16 за 10000 рублей
    # RTX 20000 за 50000 рублей
    # iPhone 16 за $1000
    # --------------------------------------------------------

    if len(found_currencies) == 1:

        currency = next(
            iter(found_currencies)
        )

        best_number = None
        best_distance = None

        for number_match in number_matches:

            number_center = (
                number_match.start()
                + number_match.end()
            ) / 2

            for currency_match in currency_matches:

                currency_center = (
                    currency_match["start"]
                    + currency_match["end"]
                ) / 2

                distance = abs(
                    number_center
                    - currency_center
                )

                if (
                    best_distance is None
                    or distance < best_distance
                ):

                    best_distance = distance
                    best_number = number_match

        if (
            best_number is not None
            and best_distance <= 20
        ):

            amount = parse_money_number(
                best_number.group(0)
            )

            if amount is not None:

                return {
                    "amount": amount,
                    "currency": currency,
                }

    # --------------------------------------------------------
    # 2. ЯВНЫЕ КОНСТРУКЦИИ ЦЕНЫ
    # --------------------------------------------------------

    price_patterns = [

        # Русский:
        r"\bза\b\s*[:=-]?\s*"
        r"(?:[$₽]\s*)?"
        r"(\d+(?:[ \u00A0]\d{3})*"
        r"(?:[.,]\d{1,2})?)",

        r"\b(?:"
        r"цена|"
        r"стоимость|"
        r"стоит|"
        r"стоил|"
        r"заплатил|"
        r"заплатила|"
        r"потратил|"
        r"потратила|"
        r"зарплата|"
        r"получил|"
        r"получила"
        r")\b"
        r"\s*[:=-]?\s*"
        r"(?:[$₽]\s*)?"
        r"(\d+(?:[ \u00A0]\d{3})*"
        r"(?:[.,]\d{1,2})?)",

        # English:
        r"\bfor\b\s*[:=-]?\s*"
        r"(?:[$₽]\s*)?"
        r"(\d+(?:[ \u00A0]\d{3})*"
        r"(?:[.,]\d{1,2})?)",

        r"\b(?:"
        r"price|"
        r"cost|"
        r"paid|"
        r"spent|"
        r"salary|"
        r"received"
        r")\b"
        r"\s*[:=-]?\s*"
        r"(?:[$₽]\s*)?"
        r"(\d+(?:[ \u00A0]\d{3})*"
        r"(?:[.,]\d{1,2})?)",
    ]

    for pattern in price_patterns:

        match = re.search(
            pattern,
            text,
            flags=re.IGNORECASE,
        )

        if not match:
            continue

        amount = parse_money_number(
            match.group(1)
        )

        if amount is None:
            continue

        if len(found_currencies) == 1:

            currency = next(
                iter(found_currencies)
            )

        else:

            currency = "RUB"

        return {
            "amount": amount,
            "currency": currency,
        }

    # --------------------------------------------------------
    # 3. СООБЩЕНИЕ СОСТОИТ ТОЛЬКО ИЗ ОДНОГО ЧИСЛА
    #
    # 10000
    # -> 10000 RUB
    #
    # RTX 20000
    # -> сюда НЕ попадёт
    # --------------------------------------------------------

    stripped_text = text.strip()

    if (
        len(number_matches) == 1
        and stripped_text
        == number_matches[0].group(0)
    ):

        amount = parse_money_number(
            number_matches[0].group(0)
        )

        if amount is not None:

            return {
                "amount": amount,
                "currency": "RUB",
            }

    return {
        "amount": None,
        "currency": None,
    }

# ============================================================
# OPENROUTER — ОБЩИЙ ЗАПРОС К API
# ============================================================

async def ask_openrouter(
    prompt: str,
    max_attempts: int = 2,
):
    if not OPENROUTER_API_KEY:
        print("OpenRouter error: API key is missing")
        return None

    url = (
        "https://openrouter.ai/api/v1/"
        "chat/completions"
    )

    headers = {
        "Authorization": (
            f"Bearer {OPENROUTER_API_KEY}"
        ),
        "Content-Type": "application/json",
    }

    payload = {
        "model": "openrouter/free",
        "messages": [
            {
                "role": "user",
                "content": prompt,
            }
        ],
        "max_tokens": 256,
    }

    for attempt in range(max_attempts):

        try:

            async with aiohttp.ClientSession(
                connector=aiohttp.TCPConnector(
                    family=socket.AF_INET
                )
            ) as session:

                async with session.post(
                    url,
                    headers=headers,
                    json=payload,
                    timeout=aiohttp.ClientTimeout(
                        total=20,
                    ),
                ) as response:

                    response_text = await response.text()

                    if response.status in {
                        429,
                        500,
                        502,
                        503,
                        504,
                    }:

                        print(
                            "OpenRouter temporary error:",
                            response.status,
                        )

                        if attempt == 0:

                            await asyncio.sleep(
                                1
                            )

                            continue

                        return None

                    if response.status != 200:

                        print(
                            "OpenRouter API error:",
                            response.status,
                            response_text,
                        )

                        return None

                    try:

                        result = json.loads(
                            response_text
                        )

                    except json.JSONDecodeError as e:

                        print(
                            "OpenRouter JSON error:",
                            e,
                        )

                        return None

            choices = result.get(
                "choices",
                [],
            )

            if not choices:

                print(
                    "OpenRouter error: no choices"
                )

                return None

            message = choices[0].get(
                "message",
                {},
            )

            result_content = message.get(
                "content"
            )

            if result_content is None:

                print(
                    "OpenRouter: content is None"
                )

                return None

            result_text = str(
                result_content
            ).strip()

            if not result_text:

                print(
                    "OpenRouter error: empty response"
                )

                return None

            return result_text

        except asyncio.TimeoutError:

            print(
                "OpenRouter request timeout"
            )

            if attempt == 0:

                await asyncio.sleep(
                    1
                )

                continue

            return None

        except Exception as e:

            print(
                "OpenRouter request exception:",
                e,
            )

            return None

    return None

# ============================================================
# OPENROUTER — СУММА И ВАЛЮТА
# ============================================================

async def parse_money_with_openrouter(
    text: str,
    transaction_type: str,
):
    operation_name = (
        "income"
        if transaction_type == "income"
        else "expense"
    )

    prompt = f"""
You are a financial transaction parser.

Transaction type:
{operation_name}

User message:
{text}

Determine ONLY the actual monetary amount
and its currency.

Understand the COMPLETE sentence using
grammar, syntax and meaning.

IMPORTANT:

Not every number is money.

A number can be:
- a product model;
- a device model;
- a version;
- a quantity;
- a size;
- a year;
- an article number;
- another product characteristic.

Examples:

"купил айфон 16 за 10000 рублей"
amount = 10000
currency = RUB

"купил iPhone 16 за $1000"
amount = 1000
currency = USD

"купил карту RTX 20000 за 50000 рублей"
amount = 50000
currency = RUB

"карта RTX 20000"
amount = null
currency = null

"купил 2 билета за 1500 рублей"
amount = 1500
currency = RUB

"заплатил 5000 рублей за билет"
amount = 5000
currency = RUB

"зарплата 120000 рублей"
amount = 120000
currency = RUB

"получил 300 долларов"
amount = 300
currency = USD

"bought 2 tickets for 1500 dollars"
amount = 1500
currency = USD

"RTX 20000"
amount = null
currency = null

DO NOT:
- choose the first number automatically;
- choose the last number automatically;
- choose the largest number automatically;
- treat a model number as a price;
- treat a quantity as the total price.

ONLY these currencies are allowed:

RUB
USD

If a clear monetary amount exists
without an explicit currency, use RUB.

If there is no clearly stated monetary amount,
return null.

Return ONLY valid JSON:

{{
    "amount": 10000,
    "currency": "RUB"
}}

or:

{{
    "amount": null,
    "currency": null
}}

No Markdown.
No explanations.
"""

    try:

        result = await ask_openrouter(
            prompt
        )

    except Exception:

        return {
            "amount": None,
            "currency": None,
        }

    if not result:

        return {
            "amount": None,
            "currency": None,
        }

    cleaned = result.strip()

    if cleaned.startswith(
        "```json"
    ):

        cleaned = cleaned[
            7:
        ]

    elif cleaned.startswith(
        "```JSON"
    ):

        cleaned = cleaned[
            7:
        ]

    if cleaned.endswith(
        "```"
    ):

        cleaned = cleaned[
            :-3
        ]

    cleaned = cleaned.strip()

    # --------------------------------------------------------
    # ЕСЛИ AI ДОБАВИЛ ЛИШНИЙ ТЕКСТ
    # --------------------------------------------------------

    if not cleaned.startswith("{"):

        json_match = re.search(
            r"\{.*\}",
            cleaned,
            flags=re.DOTALL,
        )

        if json_match:

            cleaned = (
                json_match.group(0)
            )

    try:

        parsed = json.loads(
            cleaned
        )

    except (
        json.JSONDecodeError,
        TypeError,
    ):

        return {
            "amount": None,
            "currency": None,
        }

    if not isinstance(
        parsed,
        dict,
    ):

        return {
            "amount": None,
            "currency": None,
        }

    amount = parsed.get(
        "amount"
    )

    currency = parsed.get(
        "currency"
    )

    # --------------------------------------------------------
    # ПРОВЕРКА СУММЫ
    # --------------------------------------------------------

    if amount is not None:

        try:

            amount = float(
                amount
            )

        except (
            TypeError,
            ValueError,
        ):

            amount = None

    if (
        amount is None
        or amount <= 0
    ):

        amount = None

    # --------------------------------------------------------
    # ПРОВЕРКА ВАЛЮТЫ
    # --------------------------------------------------------

    if (
        currency
        not in TRANSACTION_CURRENCIES
    ):

        currency = None

    if (
        amount is not None
        and currency is None
    ):

        currency = "RUB"

    if amount is None:

        currency = None

    return {
        "amount": amount,
        "currency": currency,
    }


# ============================================================
# ПОЛНЫЙ РАЗБОР ОПЕРАЦИИ
# ============================================================

async def parse_transaction_text(
    text: str,
    transaction_type: str,
    language: str,
):

    # ========================================================
    # 1. СУММА + ВАЛЮТА
    # ========================================================

    try:

        ai_money = await parse_money_with_openrouter(
            text=text,
            transaction_type=transaction_type,
        )

    except Exception:

        ai_money = {
            "amount": None,
            "currency": None,
        }

    amount = ai_money.get(
        "amount"
    )

    currency = ai_money.get(
        "currency"
    )

    # --------------------------------------------------------
    # FALLBACK СУММЫ
    # --------------------------------------------------------

    if amount is None:

        try:

            fallback_money = (
                extract_money_fallback(
                    text
                )
            )

        except Exception:

            fallback_money = {
                "amount": None,
                "currency": None,
            }

        amount = fallback_money.get(
            "amount"
        )

        currency = fallback_money.get(
            "currency"
        )

    # --------------------------------------------------------
    # ТОЛЬКО RUB / USD
    # --------------------------------------------------------

    if currency not in {
        "RUB",
        "USD",
    }:

        if amount is not None:

            currency = "RUB"

        else:

            currency = None

    # ========================================================
    # 2. КАТЕГОРИЯ
    # ЛОКАЛЬНЫЙ АНАЛИЗ → OPENROUTER → FALLBACK
