@dp.callback_query(
    F.data == "operation_confirm"
)
async def operation_confirm(
    callback: CallbackQuery,
    state: FSMContext,
):
    user_id = callback.from_user.id
    language = get_language(user_id)

    data = await state.get_data()

    if not data:
        await callback.answer(
            "Operation data not found."
            if language == "en"
            else "Данные операции не найдены.",
            show_alert=True,
        )
        return

    transaction_type = data.get("transaction_type")
    amount = data.get("amount")
    currency = data.get("currency")
    category = data.get("category")
    comment = data.get("comment", "")

    if transaction_type not in {
        "income",
        "expense",
    }:
        await callback.answer(
            "Invalid operation."
            if language == "en"
            else "Некорректная операция.",
            show_alert=True,
        )
        return

    try:
        amount = float(amount)
    except (TypeError, ValueError):
        await callback.answer(
            "Invalid amount."
            if language == "en"
            else "Некорректная сумма.",
            show_alert=True,
        )
        return

    if amount <= 0:
        await callback.answer(
            "Invalid amount."
            if language == "en"
            else "Некорректная сумма.",
            show_alert=True,
        )
        return

    if currency not in {"RUB", "USD"}:
        await callback.answer(
            "Invalid currency."
            if language == "en"
            else "Некорректная валюта.",
            show_alert=True,
        )
        return

    if not category:
        category = (
            "other_income"
            if transaction_type == "income"
            else "other_expense"
        )

    try:
        add_transaction(
            telegram_id=user_id,
            amount=amount,
            currency=currency,
            transaction_type=transaction_type,
            category=category,
            comment=comment,
        )

    except Exception as e:
        print(
            "Error saving transaction:",
            e,
        )

        await callback.answer(
            "Could not save the operation."
            if language == "en"
            else "Не удалось сохранить операцию.",
            show_alert=True,
        )
        return

    await state.clear()

    await callback.answer()

    try:
        await callback.message.delete()
    except Exception:
        pass

    await callback.message.answer(
        t(language, "operation_saved"),
        reply_markup=main_menu_keyboard(language),
    )


