def transaction_category_keyboard(
    transaction_type: str,
    language: str,
):
    builder = InlineKeyboardBuilder()

    if transaction_type == "income":
        categories = (
            INCOME_CATEGORIES_RU
            if language == "ru"
            else INCOME_CATEGORIES_EN
        )
    else:
        categories = (
            EXPENSE_CATEGORIES_RU
            if language == "ru"
            else EXPENSE_CATEGORIES_EN
        )

    for key, name in categories.items():
        builder.button(
            text=name,
            callback_data=f"operation_category_{key}",
        )

    builder.button(
        text="⬅️ Назад" if language == "ru" else "⬅️ Back",
        callback_data="operation_edit_back",
    )

    builder.adjust(2)

    return builder.as_markup()


