@dp.message(Command("start"))
async def start_handler(
    message: Message,
    state: FSMContext,
):
    await state.clear()

    user = message.from_user
    user_id = user.id

    existing_user = get_user(user_id)

    # --------------------------------------------------------
    # НОВЫЙ ПОЛЬЗОВАТЕЛЬ
    # --------------------------------------------------------

    if not existing_user:

        add_user(
            telegram_id=user_id,
            language="pending",
            username=user.username,
            first_name=user.first_name,
        )

        create_default_settings(user_id)

        text = (
            "👋 Добро пожаловать в PocketFinance AI!\n"
            "👋 Welcome to PocketFinance AI!\n\n"
            "📄 Юридические документы\n"
            "Перед использованием бота ознакомьтесь "
            "с юридическими документами и подтвердите "
            "их принятие.\n\n"
            "📄 Legal documents\n"
            "Before using the bot, please review "
            "the legal documents and confirm "
            "your acceptance."
        )

        await message.answer(
            text,
            reply_markup=documents_keyboard("ru"),
        )

        return

    # --------------------------------------------------------
    # ОБНОВЛЕНИЕ ПРОФИЛЯ
    # --------------------------------------------------------

    update_user_profile(
        telegram_id=user_id,
        username=user.username,
        first_name=user.first_name,
    )

    create_default_settings(user_id)

    # --------------------------------------------------------
    # ДОКУМЕНТЫ ЕЩЁ НЕ ПРИНЯТЫ
    # --------------------------------------------------------

    if not has_accepted_documents(user_id):

        text = (
            "📄 Юридические документы\n"
            "Перед использованием бота ознакомьтесь "
            "с юридическими документами и подтвердите "
            "их принятие.\n\n"
            "📄 Legal documents\n"
            "Before using the bot, please review "
            "the legal documents and confirm "
            "your acceptance."
        )

        await message.answer(
            text,
            reply_markup=documents_keyboard("ru"),
        )

        return

    # --------------------------------------------------------
    # ДОКУМЕНТЫ ПРИНЯТЫ, НО ЯЗЫК ЕЩЁ НЕ ВЫБРАН
    # --------------------------------------------------------

    language = get_user_language(user_id)

    if language not in {"ru", "en"}:

        await message.answer(
            t("ru", "choose_language"),
            reply_markup=language_keyboard(),
        )

        return

    # --------------------------------------------------------
    # ДОКУМЕНТЫ ПРИНЯТЫ + ЯЗЫК ВЫБРАН
    # --------------------------------------------------------

    await message.answer(
        t(language, "main_menu"),
        reply_markup=main_menu_keyboard(language),
    )


# ============================================================
# ПЕРВЫЙ ВЫБОР ЯЗЫКА
# ============================================================

@dp.callback_query(
    F.data.in_(
        {
            "language_ru",
            "language_en",
        }
    )
)
async def first_language_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    await state.clear()

    user = callback.from_user
    user_id = user.id

    language = callback.data.replace(
        "language_",
        "",
        1,
    )

    # --------------------------------------------------------
    # СОХРАНЯЕМ ВЫБРАННЫЙ ЯЗЫК
    # --------------------------------------------------------

    existing_user = get_user(user_id)

    if not existing_user:

        add_user(
            telegram_id=user_id,
            language=language,
            username=user.username,
            first_name=user.first_name,
        )

    else:

        change_language(
            user_id,
            language,
        )

        update_user_profile(
            telegram_id=user_id,
            username=user.username,
            first_name=user.first_name,
        )

    create_default_settings(user_id)

    await callback.answer()

    try:
        await callback.message.delete()
    except Exception:
        pass

    # --------------------------------------------------------
    # ПОСЛЕ ВЫБОРА ЯЗЫКА
    # --------------------------------------------------------

    await callback.message.answer(
        t(language, "language_changed"),
    )

    await callback.message.answer(
        t(language, "main_menu"),
        reply_markup=main_menu_keyboard(language),
    )


