# ПРИНЯТИЕ ДОКУМЕНТОВ
# ============================================================

@dp.callback_query(
    F.data == "accept_documents"
)
async def accept_documents_handler(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id

    await callback.answer()

    try:
        await asyncio.to_thread(
            accept_documents,
            telegram_id=user_id,
            username=callback.from_user.username,
            first_name=callback.from_user.first_name,
        )

    except Exception as e:
        print(
            "ОШИБКА ПРИНЯТИЯ ДОКУМЕНТОВ:",
            repr(e),
        )

        await callback.message.answer(
            "Не удалось сохранить принятие документов.\n"
            "Попробуйте нажать кнопку ещё раз."
        )
        return

    try:
        await asyncio.to_thread(
            create_default_settings,
            user_id,
        )

    except Exception as e:
        print(
            "ОШИБКА СОЗДАНИЯ НАСТРОЕК:",
            repr(e),
        )

    try:
        await callback.message.delete()
    except Exception:
        pass

    await callback.message.answer(
        t("ru", "choose_language"),
        reply_markup=language_keyboard(),
    )



