# ============================================================
# ОТОБРАЖЕНИЕ ЧЕРНОВИКА
# ============================================================

def format_receipt_draft(data: dict, language: str) -> str:

    currency = data.get("currency")

    symbol = (
        "₽" if currency == "RUB"
        else "$" if currency == "USD"
        else ""
    )

    amount = data.get("amount")

    amount_text = (
        f"{amount:.2f} {symbol}".strip()
        if amount is not None
        else ("Не определена" if language == "ru" else "Not detected")
    )

    date = data.get("date") or (
        "Не определена" if language == "ru" else "Not detected"
    )

    time = data.get("time") or (
        "Не определено" if language == "ru" else "Not detected"
    )

    currency_text = currency or (
        "Не определена" if language == "ru" else "Not detected"
    )

    categories = (
        EXPENSE_CATEGORIES_RU
        if language == "ru"
        else EXPENSE_CATEGORIES_EN
    )

    item_lines = []

    for i, item in enumerate(data.get("items", []), 1):

        price = item.get("amount")

        price_text = (
            f"{price:.2f} {symbol}".strip()
            if price is not None
            else ("Цена не распознана" if language == "ru" else "Price not detected")
        )

        category = categories.get(
            item.get("category", "other_expense"),
            item.get("category", "other_expense"),
        )

        item_lines.append(
            f"{i}. {item['name']} — {price_text}\n   {category}"
        )

    items_text = "\n".join(item_lines) or (
        "Товары не распознаны" if language == "ru" else "No items detected"
    )

    if language == "ru":
        return (
            "🧾 РАСПОЗНАННЫЙ ЧЕК\n\n"
            f"💰 Общая сумма: {amount_text}\n"
            f"💱 Валюта: {currency_text}\n"
            f"📅 Дата: {date}\n"
            f"🕒 Время: {time}\n\n"
            f"🛒 ТОВАРЫ:\n{items_text}\n\n"
            "Проверьте данные. Вы можете изменить любое поле."
        )

    return (
        "🧾 RECOGNIZED RECEIPT\n\n"
        f"💰 Total: {amount_text}\n"
        f"💱 Currency: {currency_text}\n"
        f"📅 Date: {date}\n"
        f"🕒 Time: {time}\n\n"
        f"🛒 ITEMS:\n{items_text}\n\n"
        "Check the data. You can edit any field."
    )


