# ЗАПУСК СКАНИРОВАНИЯ ЧЕКА
# ============================================================

@dp.callback_query(F.data == "receipt_scan")
async def receipt_scan_callback(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    if not is_premium_active(user_id):
        await callback.answer()
        await callback.message.edit_text(
            premium_required_text(language),
            reply_markup=premium_required_keyboard(language),
        )
        return

    await state.clear()
    await state.set_state(
        FinanceStates.waiting_receipt_photo
    )

    await callback.answer()

    try:
        await callback.message.delete()
    except Exception:
        pass

    prompt_message = await callback.message.answer(
        "📸 Отправьте фотографию чека. Распознавание может содержать ошибки."
        if language == "ru"
        else "📸 Send a photo of your receipt. Recognition may contain errors.",
        reply_markup=InlineKeyboardMarkup(
            inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text="❌ Отмена" if language == "ru" else "❌ Cancel",
                        callback_data="receipt_cancel",
                    )
                ]
            ]
        ),
    )

    # Сохраняем ID сообщения, чтобы удалить его после распознавания
    await state.update_data(
        receipt_prompt_message_id=prompt_message.message_id,
        receipt_prompt_chat_id=prompt_message.chat.id,
    )

# ============================================================
# РАСПОЗНАВАНИЕ И ПОДГОТОВКА ЧЕКА
# ============================================================

def parse_receipt_text(text: str) -> dict:
    lines = [
        re.sub(r"\s+", " ", line).strip()
        for line in text.splitlines()
        if line.strip()
    ]

    upper_text = text.upper()

    result = {
        "amount": None,
        "currency": None,
        "date": None,
        "time": None,
        "items": [],
    }

    # Валюта
    if re.search(r"RUB|РУБ|₽", upper_text):
        result["currency"] = "RUB"
    elif re.search(r"USD|ДОЛЛАР|\$", upper_text):
         result["currency"] = "USD"

    # Дата
    date_match = re.search(
        r"\b(\d{2})[./-](\d{2})[./-](20\d{2})\b",
        text
    )

    if date_match:
        day, month, year = date_match.groups()

        try:
            result["date"] = datetime.strptime(
                f"{day}.{month}.{year}",
                "%d.%m.%Y"
            ).date().isoformat()
        except ValueError:
            pass

    # Время
    time_match = re.search(
        r"\b([01]?\d|2[0-3]):([0-5]\d)(?::[0-5]\d)?\b",
        text
    )

    if time_match:
        result["time"] = (
            f"{int(time_match.group(1)):02d}:"
            f"{time_match.group(2)}"
        )


    # Строки, которые не являются товарами (RU + EN)
    excluded_words = (
        # Итоги и суммы — русский
        "итого", "всего", "к оплате", "сумма",
        "общая сумма", "сумма покупки", "сумма чека",
        "без скидок", "с учетом скидок",

        # Оплата — русский
        "наличные", "наличными", "безналичными",
        "оплата", "оплачено", "внесено",
        "получено", "сдача", "кредит",
        "банковская карта", "карта", "эквайринг",

        # Скидки и налоги — русский
        "скидка", "скидки", "ндс", "налог",
        "налогообложение", "ставка ндс",

        # Информация о магазине — русский
        "чек", "касса", "кассир", "продавец",
        "магазин", "адрес", "телефон",
        "инн", "кпп", "огрн", "ккт", "фн",
        "фп", "фд", "фискальный", "фиск",
        "документ", "номер чека", "продажа",
        "смена", "регистрация", "операция",

        # Завершение покупки — русский
        "спасибо за покупку", "спасибо",
        "приход", "расход", "возврат",

        # Totals — English
        "total", "grand total", "subtotal",
        "sub total", "amount due", "total due",
        "balance due", "total amount",
        "net total", "gross total",

        # Payment — English
        "cash", "cash payment", "card payment",
        "credit card", "debit card", "payment",
        "paid", "change", "tendered",
        "amount paid", "received", "refund",

        # Discounts and taxes — English
        "discount", "discounts", "tax",
        "taxes", "vat", "sales tax",
        "tax amount", "tax rate",

        # Store information — English
        "receipt", "cashier", "store",
        "address", "phone", "invoice",
        "invoice number", "receipt number",
        "transaction", "transaction id",
        "terminal", "register", "shift",
        "fiscal", "document number",
        "serial number", "tax id",

        # End of receipt — English
        "thank you", "thank you for shopping",
        "thank you for your purchase",
        "come again", "customer copy",
    )

    for line in lines:
        upper_line = line.upper().replace("Ё", "Е")

        if any(
            re.search(
                rf"(?<!\w){re.escape(word.upper())}(?!\w)",
                upper_line
            )
            for word in excluded_words
        ):
            continue

        # Ищем итоговую цену товара после знака "="
        equal_match = re.search(
            r"=\s*([0-9][0-9\s.,]*[.,]\d{2,3})\s*$",
            line
        )

        if not equal_match:
            continue

        raw_price = equal_match.group(1)
        raw_price = re.sub(r"\s+", "", raw_price)
        raw_price = re.sub(r"([,.])[,.]+", r"\1", raw_price)

        if re.search(r"[.,]\d{3}$", raw_price):
            if raw_price[-1] == "0":
                raw_price = raw_price[:-1]
            else:
                continue

        try:
            price = float(raw_price.replace(",", "."))
        except ValueError:
            continue

        if price <= 0:
            continue

        item_part = line[:equal_match.start()].strip()
        item_part = re.sub(r"^\s*\d+\s*", "", item_part)

        item_part = re.sub(
            r"\s+\d+[.,]\d{2}\s*[xх×*]\s*\d+(?:[.,]\d{1,3})?\s*$",
            "",
            item_part,
            flags=re.IGNORECASE,
        ).strip()

        name = re.sub(
            r"^[^А-Яа-яЁёA-Za-z]+|[^А-Яа-яЁёA-Za-z0-9]+$",
            "",
            item_part
        ).strip()

        if len(name) < 2:
            continue

        normalized_name = name.upper().replace("Ё", "Е")

        if any(
            word in normalized_name
            for word in (
                "ИТОГО",
                "ИТОГ",
                "ВСЕГО",
                "К ОПЛАТЕ",
                "СУММА",
                "НАЛИЧНЫМИ",
                "ВНЕСЕНО",
                "СДАЧА",
                "СКИДКА",
            )
        ):
            continue

        normalized_name = name.lower()
        normalized_name = normalized_name.replace("маспо", "масло")
        normalized_name = normalized_name.replace("ряненка", "ряженка")

        category = "other_expense"

        result["items"].append({
            "name": name,
            "amount": price,
            "category": category,
        })


    
    # Определяем общую сумму чека
    result["amount"] = extract_receipt_total(
        text,
        result["items"]
    )

    # Резерв: сумма товаров, если итог чека не найден
    if (
        result["amount"] is None
        and result["items"]
        and all(item["amount"] is not None for item in result["items"])
    ):
        result["amount"] = round(
            sum(item["amount"] for item in result["items"]),
            2
        )

    return result



def extract_receipt_total(text: str, items=None):
    lines = [
        re.sub(r"\s+", " ", line).strip()
        for line in text.splitlines()
        if line.strip()
    ]

    def parse_money(raw):
        raw = raw.replace(" ", "").replace("\u00A0", "")
        raw = re.sub(r"([,.])[,.]+", r"\1", raw)

        if re.search(r"[.,]\d{3}$", raw):
            if raw[-1] == "0":
                raw = raw[:-1]
            else:
                return None

        try:
            return float(raw.replace(",", "."))
        except ValueError:
            return None

    amount_pattern = re.compile(
        r"(?<!\d)(\d{1,3}(?:[ \u00A0]\d{3})+(?:[.,]\d{2,3})|"
        r"\d{1,7}[.,]\d{2,3})(?!\d)"
    )

    # Сумма распознанных товаров — резервный вариант.
    items_total = None

    if items:
        known_prices = [
            float(item["amount"])
            for item in items
            if item.get("amount") is not None
        ]

        if known_prices:
            items_total = round(sum(known_prices), 2)

    # Явные обозначения итоговой суммы ПОСЛЕ скидок.
    discounted_labels = (
        "ИТОГ С УЧЕТОМ СКИДОК",
        "ИТОГО С УЧЕТОМ СКИДОК",
        "ИТОГ СО СКИДКАМИ",
        "ИТОГО СО СКИДКАМИ",
        "ИТОГ С СКИДКАМИ",
        "ИТОГО С СКИДКАМИ",
        "ИТОГ СО СКИДКОЙ",
        "ИТОГО СО СКИДКОЙ",
        "ИТОГ С СКИДКОЙ",
        "ИТОГО С СКИДКОЙ",
        "ИТОГ ПОСЛЕ СКИДКИ",
        "ИТОГО ПОСЛЕ СКИДКИ",
        "TOTAL AFTER DISCOUNT",
        "TOTAL WITH DISCOUNT",
        "GRAND TOTAL",
        "TOTAL DUE",
        "AMOUNT DUE",
        "TOTAL TO PAY",
    )

    # Обозначения суммы ДО скидок.
    before_discount_labels = (
        "ИТОГ БЕЗ СКИДОК",
        "ИТОГО БЕЗ СКИДОК",
        "СУММА БЕЗ СКИДОК",
        "TOTAL BEFORE DISCOUNT",
        "TOTAL WITHOUT DISCOUNT",
        "SUBTOTAL",
    )

    # Обычные обозначения итога, если скидки отдельно не указаны.
    regular_labels = (
        "СУММА К ОПЛАТЕ",
        "ИТОГО К ОПЛАТЕ",
        "ИТОГ К ОПЛАТЕ",
        "ОБЩАЯ СУММА",
        "ИТОГОВАЯ СУММА",
        "К ОПЛАТЕ",
        "ИТОГО",
        "ИТОГ",
        "ВСЕГО",
        "TOTAL",
    )

    excluded_labels = (
        "НАЛИЧНЫЕ",
        "НАЛИЧНЫМИ",
        "ВНЕСЕНО",
        "ПОЛУЧЕНО",
        "СДАЧА",
        "ЭКОНОМИЯ",
        "БОНУС",
        "НДС",
        "CHANGE",
        "CASH",
        "TENDERED",
        "DISCOUNT",
        "SAVINGS",
    )

    discounted_candidates = []
    regular_candidates = []
    other_amounts = []

    for index, line in enumerate(lines):
        normalized = line.upper().replace("Ё", "Е")

        # Не учитываем строки с датами.
        if re.search(
            r"\b\d{1,2}[./-]\d{1,2}[./-]\d{2,4}\b",
            normalized
        ):
            continue

        # Итог БЕЗ скидок никогда не выбираем,
        # если есть отдельный итог С учётом скидок.
        if any(
            label in normalized
            for label in before_discount_labels
        ):
            continue

        # Проверяем наличие обозначения итоговой суммы.
        is_discounted_total = any(
            label in normalized
            for label in discounted_labels
        )

        is_regular_total = any(
            label in normalized
            for label in regular_labels
        )

        # Не принимаем оплату, сдачу и скидки за итог.
        if any(
            label in normalized
            for label in excluded_labels
        ) and not is_discounted_total and not is_regular_total:
            continue

        amounts = amount_pattern.findall(line)

        # Если подпись итога находится на отдельной строке,
        # проверяем следующую строку с суммой.
        if (
            (is_discounted_total or is_regular_total)
            and not amounts
            and index + 1 < len(lines)
        ):
            next_line = lines[index + 1]
            amounts = amount_pattern.findall(next_line)

        parsed_amounts = []

        for raw in amounts:
            amount = parse_money(raw)

            if amount is not None and amount > 0:
                parsed_amounts.append(amount)
                other_amounts.append((index, amount))

        if not parsed_amounts:
            continue

        if is_discounted_total:
            for amount in parsed_amounts:
                discounted_candidates.append((index, amount))

        elif is_regular_total:
            for amount in parsed_amounts:
                regular_candidates.append((index, amount))

    # 1. Приоритет — итог С учётом скидок.
    if discounted_candidates:
        return round(
            discounted_candidates[-1][1],
            2
        )

    # 2. Если отдельного итога со скидкой нет,
    # используем обычный обозначенный итог.
    if regular_candidates:
        return round(
            regular_candidates[-1][1],
            2
        )

    # 3. Если подписи итога не найдены,
    # используем сумму распознанных товаров.
    if items_total is not None:
        return items_total

    # 4. Последний резерв — последняя подходящая
    # денежная сумма в чеке, а не самая большая.
    if other_amounts:
        return round(other_amounts[-1][1], 2)

    return None


# ============================================================
# КНОПКИ ЧЕКА
# ============================================================

def receipt_keyboard(language: str):
    builder = InlineKeyboardBuilder()

    if language == "ru":
        builder.button(text="✅ Подтвердить", callback_data="receipt_confirm")
        builder.button(text="✏️ Изменить", callback_data="receipt_edit")
        builder.button(text="❌ Отменить", callback_data="receipt_cancel")
    else:
        builder.button(text="✅ Confirm", callback_data="receipt_confirm")
        builder.button(text="✏️ Edit", callback_data="receipt_edit")
        builder.button(text="❌ Cancel", callback_data="receipt_cancel")

    builder.adjust(1)
    return builder.as_markup()


# ============================================================
# ОТОБРАЖЕНИЕ ЧЕРНОВИКА
# ============================================================

def format_receipt_draft(data: dict, language: str) -> str:
    ru = language == "ru"

    lines = [
        "🧾 Чек — проверьте распознанные данные:"
        if ru else "🧾 Receipt — check the recognized data:",
        "",
    ]

    amount = data.get("amount")
    currency = data.get("currency")
    date = data.get("date")
    time = data.get("time")

    lines.append(
        f"💰 Сумма: {amount:.2f}" if amount is not None
        else ("💰 Сумма: не определена" if ru else "💰 Total: not recognized")
    )

    lines.append(
        f"💱 Валюта: {currency}" if currency
        else ("💱 Валюта: не определена" if ru else "💱 Currency: not recognized")
    )

    lines.append(
        f"📅 Дата: {date}" if date
        else ("📅 Дата: не определена" if ru else "📅 Date: not recognized")
    )

    lines.append(
        f"🕒 Время: {time}" if time
        else ("🕒 Время: не определено" if ru else "🕒 Time: not recognized")
    )

    lines.append("")
    lines.append("🛒 Товары:" if ru else "🛒 Items:")

    if not data.get("items"):
        lines.append("Не удалось распознать товары." if ru else "No items recognized.")
    else:
        for index, item in enumerate(data["items"], 1):
            price = item.get("amount")
            price_text = (
                f"{price:.2f}" if price is not None
                else ("цена не определена" if ru else "price not recognized")
            )

            category = item.get("category", "other_expense")

            categories = (
                EXPENSE_CATEGORIES_RU
                if ru
                else EXPENSE_CATEGORIES_EN
            )

            category_text = categories.get(category, category)

            lines.append(
                f"{index}. {item.get('name', '—')} — {price_text} ({category_text})"
            )

    lines.append("")
    lines.append(
        "Если данные распознаны неверно, нажмите «Изменить»."
        if ru else "If any data is incorrect, press Edit."
    )

    return "\n".join(lines)



# ============================================================
# РАСПОЗНАВАНИЕ ФОТОГРАФИИ ЧЕКА
# ============================================================




async def classify_receipt_items(items):
    # Допустимые категории расходов
    allowed_categories = {
        "food",
        "restaurants",
        "transport",
        "housing",
        "utilities",
        "rent",
        "shopping",
        "clothing",
        "health",
        "education",
        "entertainment",
        "subscriptions",
        "communication",
        "internet",
        "travel",
        "fuel",
        "car",
        "home",
        "technology",
        "gifts",
        "pets",
        "sports",
        "beauty",
        "taxes",
        "loans",
        "insurance",
        "investments",
        "charity",
        "other_expense",
    }

    # Если товаров нет — возвращаем пустой список
    if not items:
        return items

    # --------------------------------------------------------
    # 1. СНАЧАЛА ПРОВЕРЯЕМ ВСЕ ТОВАРЫ ПО ЛОКАЛЬНОМУ СЛОВАРЮ
    # --------------------------------------------------------

    pending = []

    for index, item in enumerate(items):
        name = str(item.get("name", "")).strip()

        if not name:
            item["category"] = "other_expense"
            continue

        try:
            local_category = detect_category_local(
                name,
                "expense",
            )
        except Exception as e:
            print("RECEIPT LOCAL CATEGORY ERROR:", repr(e))
            local_category = None

        if local_category in allowed_categories:
            item["category"] = local_category
            print(
                f"RECEIPT CATEGORY: LOCAL | {name} | {local_category}"
            )
        else:
            pending.append(index)

    # --------------------------------------------------------
    # 2. ЕСЛИ СЛОВАРЬ РАСПОЗНАЛ ВСЁ — ИИ НЕ НУЖЕН
    # --------------------------------------------------------

    if not pending:
        print("RECEIPT CATEGORY: ALL ITEMS CLASSIFIED LOCALLY")
        return items

    # --------------------------------------------------------
    # 3. ДВА ОБЩИХ ЗАПРОСА К ИИ ДЛЯ НЕРАСПОЗНАННЫХ ТОВАРОВ
    # --------------------------------------------------------

    categories_text = ", ".join(sorted(allowed_categories))

    for attempt in range(2):

        if not pending:
            break

        numbered_items = []

        for index in pending:
            name = str(items[index].get("name", "")).strip()
            numbered_items.append(f"{index}: {name}")

        prompt = f"""
You are a receipt product classification system.

Classify every product in the list into exactly one
of the allowed expense categories.

Allowed categories:
{categories_text}

Products:
{chr(10).join(numbered_items)}

Rules:
- Classify the actual product, not its brand alone.
- Food, drinks, sweets and groceries belong to food.
- Restaurant meals and food delivery belong to restaurants.
- Electronic devices belong to technology.
- Clothing, shoes and accessories belong to clothing.
- Medicines and medical products belong to health.
- If the category is genuinely unclear, use other_expense.
- Do not invent new categories.
- Do not omit any product.
- Use the exact product index as the JSON key.

Return ONLY valid JSON in this format:
{{
    "0": "food",
    "1": "technology"
}}

No Markdown.
No explanations.
"""

        print(
            f"RECEIPT AI BATCH ATTEMPT: {attempt + 1}"
        )
        print(
            "RECEIPT AI BATCH ITEMS:",
            numbered_items,
        )

        try:
            result = await ask_openrouter(
                prompt,
                max_attempts=1,
            )
        except Exception as e:
            print("RECEIPT AI BATCH ERROR:", repr(e))
            result = None

        if not result:
            print(
                f"RECEIPT AI BATCH: NO RESPONSE, ATTEMPT {attempt + 1}"
            )
            continue

        # ----------------------------------------------------
        # 4. ОЧИЩАЕМ И РАЗБИРАЕМ JSON
        # ----------------------------------------------------

        cleaned = result.strip()

        if cleaned.startswith("```json"):
            cleaned = cleaned[7:]
        elif cleaned.startswith("```"):
            cleaned = cleaned[3:]

        if cleaned.endswith("```"):
            cleaned = cleaned[:-3]

        cleaned = cleaned.strip()

        if not cleaned.startswith("{"):
            json_match = re.search(
                r"\{.*\}",
                cleaned,
                flags=re.DOTALL,
            )

            if json_match:
                cleaned = json_match.group(0)

        try:
            parsed = json.loads(cleaned)
        except (json.JSONDecodeError, TypeError):
            print("RECEIPT AI BATCH: INVALID JSON")
            continue

        if not isinstance(parsed, dict):
            print("RECEIPT AI BATCH: RESPONSE IS NOT A DICTIONARY")
            continue

        # ----------------------------------------------------
        # 5. СОХРАНЯЕМ ПРАВИЛЬНЫЕ КАТЕГОРИИ
        # ----------------------------------------------------

        still_pending = []

        for index in pending:
            ai_category = parsed.get(str(index))

            if isinstance(ai_category, str):
                ai_category = ai_category.strip().lower()
            else:
                ai_category = None

            if ai_category in allowed_categories:
                items[index]["category"] = ai_category

                print(
                    "RECEIPT CATEGORY: AI |",
                    items[index].get("name"),
                    "|",
                    ai_category,
                )
            else:
                still_pending.append(index)

        pending = still_pending

    # --------------------------------------------------------
    # 6. ЕСЛИ ПОСЛЕ ДВУХ ПОПЫТОК КАТЕГОРИЯ НЕ НАЙДЕНА
    # --------------------------------------------------------

    for index in pending:
        items[index]["category"] = "other_expense"

        print(
            "RECEIPT CATEGORY: FALLBACK |",
            items[index].get("name"),
        )

    return items



@dp.message(F.photo, FinanceStates.waiting_receipt_photo)
async def receipt_photo_handler(
    message: Message,
    state: FSMContext,
):
    user_id = message.from_user.id
    language = get_language(user_id)

    if not is_premium_active(user_id):
        await state.clear()
        await message.answer(
            premium_required_text(language),
            reply_markup=premium_required_keyboard(language),
        )
        return

    status_message = await message.answer(
        "⏳ Распознаю чек..."
        if language == "ru"
        else "⏳ Recognizing receipt..."
    )

    try:
        photo = message.photo[-1]
        file = await message.bot.get_file(photo.file_id)

        photo_bytes = BytesIO()

        await message.bot.download_file(
            file.file_path,
            destination=photo_bytes,
        )

        photo_bytes.seek(0)

        with Image.open(photo_bytes) as img:
            image = img.convert("L")

            # Увеличиваем изображение в 2 раза
            image = image.resize(
                (image.width * 2, image.height * 2),
                Image.Resampling.LANCZOS,
            )

            # Повышаем контраст
            image = ImageOps.autocontrast(image)

            image = ImageEnhance.Contrast(image).enhance(1.8)

            # Убираем мелкий шум
            image = image.filter(ImageFilter.SHARPEN)


        pytesseract.pytesseract.tesseract_cmd = "tesseract"
        
        recognized_text = await asyncio.to_thread(
            pytesseract.image_to_string,
            image,
            lang="rus+eng",
            config="--oem 3 --psm 6",
        )

        if not recognized_text.strip():
            await status_message.edit_text(
                "❌ Не удалось распознать чек. Попробуйте более чёткое фото."
                if language == "ru"
                else "❌ Could not recognize the receipt. Try a clearer photo."
            )
            return

        print("===== RAW RECEIPT OCR =====")
        print(recognized_text)
        print("===== END RAW RECEIPT OCR =====")

        receipt_data = parse_receipt_text(recognized_text)

        receipt_data["items"] = await classify_receipt_items(
            receipt_data.get("items", [])
        )

        # Сохраняем данные чека
        await state.update_data(
            receipt_draft=receipt_data
        )

        await state.set_state(
            FinanceStates.waiting_receipt_edit
        )

        # Получаем ID сообщения с просьбой прислать чек
        state_data = await state.get_data()

        prompt_message_id = state_data.get(
            "receipt_prompt_message_id"
        )

        prompt_chat_id = state_data.get(
            "receipt_prompt_chat_id"
        )

        # Удаляем сообщение бота с просьбой прислать фото
        if prompt_message_id and prompt_chat_id:
            try:
                await message.bot.delete_message(
                    chat_id=prompt_chat_id,
                    message_id=prompt_message_id,
                )
            except Exception as e:
                print("RECEIPT PROMPT DELETE ERROR:", repr(e))

        # Удаляем фотографию пользователя
        try:
            await message.delete()
        except Exception as e:
            print("RECEIPT PHOTO DELETE ERROR:", repr(e))

        # Удаляем сообщение «Распознаю чек...»
        try:
            await status_message.delete()
        except Exception as e:
            print("RECEIPT STATUS DELETE ERROR:", repr(e))

        # Отправляем результат распознавания
        await message.answer(
            format_receipt_draft(receipt_data, language),
            reply_markup=receipt_keyboard(language),
            parse_mode=None,
        )

    except Exception as e:
        print("RECEIPT OCR ERROR:", repr(e))

        await status_message.edit_text(
            "❌ Ошибка при распознавании чека. Попробуйте другое фото."
            if language == "ru"
            else "❌ Receipt recognition failed. Try another photo."
        )



