def receipt_edit_keyboard(language: str):
    builder = InlineKeyboardBuilder()

    if language == "ru":
        builder.button(text="💰 Общая сумма", callback_data="receipt_field_amount")
        builder.button(text="💱 Валюта", callback_data="receipt_field_currency")
        builder.button(text="📅 Дата", callback_data="receipt_field_date")
        builder.button(text="🕒 Время", callback_data="receipt_field_time")
        builder.button(text="🛒 Товары", callback_data="receipt_edit_items")
        builder.button(text="⬅️ Назад", callback_data="receipt_back_draft")
    else:
        builder.button(text="💰 Total", callback_data="receipt_field_amount")
        builder.button(text="💱 Currency", callback_data="receipt_field_currency")
        builder.button(text="📅 Date", callback_data="receipt_field_date")
        builder.button(text="🕒 Time", callback_data="receipt_field_time")
        builder.button(text="🛒 Items", callback_data="receipt_edit_items")
        builder.button(text="⬅️ Back", callback_data="receipt_back_draft")

    builder.adjust(2, 2, 1, 1)
    return builder.as_markup()


def receipt_items_keyboard(data: dict, language: str):
    builder = InlineKeyboardBuilder()

    for index, item in enumerate(data.get("items", [])):
        builder.button(
            text=f"{index + 1}. {item['name'][:25]}",
            callback_data=f"receipt_item_{index}",
        )

    builder.button(
        text="⬅️ Назад" if language == "ru" else "⬅️ Back",
        callback_data="receipt_edit",
    )

    builder.adjust(1)
    return builder.as_markup()


def receipt_item_category_keyboard(index: int, language: str):
    builder = InlineKeyboardBuilder()

    categories = (
        EXPENSE_CATEGORIES_RU
        if language == "ru"
        else EXPENSE_CATEGORIES_EN
    )

    for key, name in categories.items():
        builder.button(
            text=name,
            callback_data=f"receipt_item_category_{index}_{key}",
        )

    builder.button(
        text="⬅️ Назад" if language == "ru" else "⬅️ Back",
        callback_data=f"receipt_item_menu_{index}",
    )

    builder.adjust(2)
    return builder.as_markup()



