@dp.callback_query(F.data.startswith("receipt_field_"))
async def receipt_field_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    language = get_language(callback.from_user.id)
    field = callback.data.replace("receipt_field_", "", 1)

    if field == "currency":
        keyboard = InlineKeyboardMarkup(
            inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text="🇷🇺 Российский рубль (RUB)",
                        callback_data="receipt_currency_RUB",
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="🇺🇸 Доллар США (USD)",
                        callback_data="receipt_currency_USD",
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="⬅️ Назад" if language == "ru" else "⬅️ Back",
                        callback_data="receipt_back",
                    ),
                    InlineKeyboardButton(
                        text="❌ Отмена" if language == "ru" else "❌ Cancel",
                        callback_data="receipt_cancel",
                    ),
                ],
            ]
        )

        await callback.message.edit_text(
            "💱 Выберите валюту:" if language == "ru"
            else "💱 Select currency:",
            reply_markup=keyboard,
        )

        await callback.answer()
        return

    prompts = {
        "amount": (
            "Введите общую сумму чека:"
            if language == "ru" else "Enter the receipt total:"
        ),
        "date": (
            "Введите дату в формате ДД.ММ.ГГГГ:"
            if language == "ru" else "Enter date as DD.MM.YYYY:"
        ),
        "time": (
            "Введите время в формате ЧЧ:ММ:"
            if language == "ru" else "Enter time as HH:MM:"
        ),
    }

    if field not in prompts:
        await callback.answer("Неизвестное поле.", show_alert=True)
        return

    await state.update_data(receipt_pending_edit=field)
    await state.set_state(FinanceStates.waiting_receipt_edit_value)

    keyboard = InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text="⬅️ Назад" if language == "ru" else "⬅️ Back",
                    callback_data="receipt_back"
                ),
                InlineKeyboardButton(
                    text="❌ Отмена" if language == "ru" else "❌ Cancel",
                    callback_data="receipt_cancel",
                ),
            ]
        ]
    )

    prompt_message = await callback.message.edit_text(
        prompts[field],
        reply_markup=keyboard,
    )

    await state.update_data(
        receipt_prompt_message_id=prompt_message.message_id
    )

    await callback.answer()

@dp.callback_query(F.data.startswith("receipt_currency_"))
async def receipt_currency_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    language = get_language(callback.from_user.id)

    currency = callback.data.replace("receipt_currency_", "", 1)

    if currency not in ("RUB", "USD"):
        await callback.answer("Неизвестная валюта.", show_alert=True)
        return

    data = await state.get_data()
    receipt = data.get("receipt_draft")

    if not receipt:
        await callback.answer("Черновик не найден.", show_alert=True)
        return

    receipt["currency"] = currency

    await state.update_data(receipt_draft=receipt)
    await state.set_state(FinanceStates.waiting_receipt_edit)

    await callback.message.edit_text(
        format_receipt_draft(receipt, language),
        reply_markup=receipt_keyboard(language),
        parse_mode=None,
    )

    await callback.answer(
        "Валюта изменена." if language == "ru"
        else "Currency updated."
    )

