@dp.callback_query(F.data.startswith("receipt_item_menu_"))
async def receipt_item_menu_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    language = get_language(callback.from_user.id)
    index = int(callback.data.rsplit("_", 1)[1])

    data = await state.get_data()
    receipt = data.get("receipt_draft")

    if not receipt or index < 0 or index >= len(receipt.get("items", [])):
        await callback.answer("Товар не найден.", show_alert=True)
        return

    item = receipt["items"][index]

    await state.update_data(
        receipt_pending_item=index,
        receipt_pending_edit=None,
    )

    await state.set_state(FinanceStates.waiting_receipt_edit)

    await callback.message.edit_text(
        (
            f"{item.get('name', '—')}\n"
            f"Цена: {item.get('amount', '—')}\n\n"
            "Что изменить?"
        )
        if language == "ru"
        else (
            f"{item.get('name', '—')}\n"
            f"Price: {item.get('amount', '—')}\n\n"
            "What to change?"
        ),
        reply_markup=receipt_item_edit_keyboard(index, language),
    )

    await callback.answer()

@dp.callback_query(F.data.startswith("receipt_item_category_"))
async def receipt_item_category_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    language = get_language(callback.from_user.id)

    value = callback.data.replace(
        "receipt_item_category_", "", 1
    )

    try:
        index_text, category = value.split("_", 1)
        index = int(index_text)
    except (ValueError, IndexError):
        await callback.answer()
        return

    data = await state.get_data()
    receipt = data.get("receipt_draft")

    if (
        not receipt
        or index < 0
        or index >= len(receipt.get("items", []))
        or category not in EXPENSE_CATEGORIES_RU
    ):
        await callback.answer("Ошибка категории.", show_alert=True)
        return

    receipt["items"][index]["category"] = category

    await state.update_data(
        receipt_draft=receipt,
        receipt_pending_item=index,
        receipt_pending_edit=None,
    )

    await state.set_state(FinanceStates.waiting_receipt_edit)

    item = receipt["items"][index]

    await callback.message.edit_text(
        (
            f"{item.get('name', '—')}\n"
            f"Цена: {item.get('amount', '—')}\n\n"
            "Что изменить?"
        )
        if language == "ru"
        else (
            f"{item.get('name', '—')}\n"
            f"Price: {item.get('amount', '—')}\n\n"
            "What to change?"
        ),
        reply_markup=receipt_item_edit_keyboard(index, language),
    )

    await callback.answer(
        "Категория изменена."
        if language == "ru"
        else "Category updated."
    )

