# ============================================================

@dp.message(FinanceStates.waiting_receipt_edit_value)
async def receipt_edit_value_handler(
    message: Message,
    state: FSMContext,
):
    language = get_language(message.from_user.id)
    data = await state.get_data()

    field = data.get("receipt_pending_edit")
    receipt = data.get("receipt_draft")

    if not receipt or not field:
        await message.answer("Черновик чека не найден.")
        return

    value = (message.text or "").strip()

    try:
        if field == "amount":
            amount = float(value.replace(",", "."))
            if amount <= 0:
                raise ValueError
            receipt["amount"] = round(amount, 2)

        elif field == "currency":
            currency = value.upper()
            if currency not in ("RUB", "USD"):
                raise ValueError
            receipt["currency"] = currency

        elif field == "date":
            receipt_date = datetime.strptime(value, "%d.%m.%Y")
            receipt["date"] = receipt_date.date().isoformat()

        elif field == "time":
            receipt_time = datetime.strptime(value, "%H:%M")
            receipt["time"] = receipt_time.strftime("%H:%M")

        elif field.startswith("item_name_"):
            index = int(field.rsplit("_", 1)[1])

            if not value or not (0 <= index < len(receipt["items"])):
                raise ValueError

            receipt["items"][index]["name"] = value

        elif field.startswith("item_amount_"):
            index = int(field.rsplit("_", 1)[1])
            price = float(value.replace(",", "."))

            if price <= 0 or not (0 <= index < len(receipt["items"])):
                raise ValueError

            receipt["items"][index]["amount"] = round(price, 2)

    except (ValueError, TypeError, IndexError):
        await message.answer(
            "❌ Неверный формат. Попробуйте ещё раз."
            if language == "ru"
            else "❌ Invalid format. Please try again."
        )
        return

    await state.update_data(receipt_draft=receipt)

    
    # Удаляем сообщение бота с просьбой ввести значение
    prompt_message_id = data.get("receipt_prompt_message_id")

    if prompt_message_id:
        await message.bot.delete_message(
            chat_id=message.chat.id,
            message_id=prompt_message_id,
        )

    # Удаляем сообщение пользователя с введённым значением
    await message.delete()


    await state.update_data(receipt_prompt_message_id=None)

    if field.startswith("item_name_") or field.startswith("item_amount_"):
        index = int(field.rsplit("_", 1)[1])

        await state.update_data(
            receipt_pending_item=index,
            receipt_pending_edit=None,
        )
        await state.set_state(FinanceStates.waiting_receipt_edit)

        item = receipt["items"][index]

        await message.answer(
            (
                f"Товар: {item['name']}\n"
                f"Цена: {item['amount']}\n\n"
                "Что хотите изменить?"
            )
            if language == "ru"
            else (
                f"Item: {item['name']}\n"
                f"Price: {item['amount']}\n\n"
                "What would you like to edit?"
            ),
            reply_markup=receipt_item_edit_keyboard(index, language),
        )

    else:
        await state.set_state(FinanceStates.waiting_receipt_edit)

        await message.answer(
            format_receipt_draft(receipt, language),
            reply_markup=receipt_keyboard(language),
            parse_mode=None,
        )


