@dp.callback_query(F.data == "receipt_confirm")
async def receipt_confirm_callback(
    callback: CallbackQuery,
    state: FSMContext,
):
    user_id = callback.from_user.id
    language = get_language(user_id)

    data = await state.get_data()
    receipt = data.get("receipt_draft")

    if not receipt:
        await callback.answer(
            "Данные чека не найдены."
            if language == "ru"
            else "Receipt data not found.",
            show_alert=True,
        )
        return

    currency = receipt.get("currency")
    date = receipt.get("date")
    time = receipt.get("time")
    amount = receipt.get("amount")
    items = receipt.get("items", [])

    # Проверяем валюту
    if currency not in ("RUB", "USD"):
        await callback.answer(
            "Укажите валюту в меню редактирования."
            if language == "ru"
            else "Please specify the currency in Edit.",
            show_alert=True,
        )
        return

    # Проверяем дату и время
    if not date or not time:
        await callback.answer(
            "Укажите дату и время чека."
            if language == "ru"
            else "Please specify the receipt date and time.",
            show_alert=True,
        )
        return

    # Проверяем общую сумму
    if amount is None or float(amount) <= 0:
        await callback.answer(
            "Укажите общую сумму чека."
            if language == "ru"
            else "Please specify the receipt total.",
            show_alert=True,
        )
        return

    # Проверяем товары и цены
    if not items or any(
        item.get("amount") is None
        or float(item["amount"]) <= 0
        for item in items
    ):
        await callback.answer(
            "У некоторых товаров отсутствует цена. Исправьте её."
            if language == "ru"
            else "Some item prices are missing. Please edit them.",
            show_alert=True,
        )
        return

    # Проверяем сумму товаров, но не блокируем сохранение
    items_total = round(
        sum(float(item["amount"]) for item in items),
        2,
    )

    if abs(items_total - float(amount)) > 0.01:
        print(
            f"RECEIPT TOTAL MISMATCH: "
            f"items={items_total:.2f}, receipt={float(amount):.2f}"
        )

    created_at = f"{date}T{time}:00"

    try:
        print("RECEIPT SAVE START")
        print("USER ID:", user_id)
        print("ITEMS COUNT:", len(items))

        saved_ids = []

        for item in items:
            transaction_id = add_transaction(
                telegram_id=user_id,
                amount=float(item["amount"]),
                currency=currency,
                transaction_type="expense",
                category=item.get("category", "other_expense"),
                comment=f"Чек: {item['name']}",
                created_at=created_at,
            )

            saved_ids.append(transaction_id)

        print("RECEIPT SAVED IDS:", saved_ids)

    except Exception as e:
        print("RECEIPT SAVE ERROR:", repr(e))

        await callback.answer(
            "Ошибка сохранения чека."
            if language == "ru"
            else "Receipt saving error.",
            show_alert=True,
        )
        return


    await state.clear()
    await callback.answer()

    try:
        await callback.message.delete()
    except Exception:
        pass

    await callback.message.answer(
        "✅ Чек сохранён. Все товары добавлены в расходы."
        if language == "ru"
        else "✅ Receipt saved. All items were added to expenses.",
        reply_markup=main_menu_keyboard(language),
    )


