def _build_category_names(
    source,
    language,
):

    result = {}

    for key in source:

        if key == "other_income":

            result[key] = (
                "➕ Другое"
                if language == "ru"
                else "➕ Other"
            )

        elif key == "other_expense":

            result[key] = (
                "➖ Другое"
                if language == "ru"
                else "➖ Other"
            )

        else:

            result[key] = (
                key
                .replace(
                    "_",
                    " ",
                )
                .capitalize()
            )

    return result


