async def delete_operation_input_messages(
    message: Message,
    state: FSMContext,
):

    data = await state.get_data()

    prompt_message_id = data.get(
        "operation_prompt_message_id"
    )

    # Сначала удаляем сообщение бота.
    if prompt_message_id:
        try:
            await message.bot.delete_message(
                chat_id=message.chat.id,
                message_id=prompt_message_id,
            )
        except Exception:
            pass

    # Затем удаляем сообщение пользователя.
    try:
        await message.delete()
    except Exception:
        pass

