# ОБРАБОТКА ТЕКСТА ДОХОДОВ И РАСХОДОВ
# ============================================================

@dp.message(FinanceStates.waiting_income_input)
async def income_text_input(
    message: Message,
    state: FSMContext,
):
    user_id = message.from_user.id
    language = get_language(user_id)

    text = (message.text or "").strip()

    if not text:
        await message.answer(
            "Please enter an income."
            if language == "en"
            else "Введите доход."
        )
        return

    # РАСПОЗНАВАНИЕ СУММЫ И КАТЕГОРИИ

    parsed = await parse_transaction_text(
        text=text,
        transaction_type="income",
        language=language,
    )

    amount = parsed.get("amount")
    category = parsed.get("category")

    if amount is None:
        await message.answer(
            "I couldn't determine the monetary amount. "
            "Please include the income amount."
            if language == "en"
            else "Не удалось определить сумму. Укажите сумму дохода."
        )
        return

    # ОПРЕДЕЛЕНИЕ ВАЛЮТЫ

    currencies = find_currency_mentions(text)

    if len(currencies) > 1:
        await message.answer(
            "Please specify only one currency: RUB or USD."
            if language == "en"
            else "Укажите только одну валюту: RUB или USD."
        )
        return

    currency = (
        currencies[0]
        if currencies
        else get_default_currency(user_id)
    )

    if currency not in {"RUB", "USD"}:
        currency = "RUB"

    # СОХРАНЕНИЕ ДАННЫХ В FSM

    await state.update_data(
        transaction_type="income",
        amount=amount,
        currency=currency,
        category=category,
        comment=text,
        raw_text=text,
    )

    # УДАЛЕНИЕ СООБЩЕНИЙ ВВОДА
    await delete_operation_input_messages(
        message,
        state,
    )

    # ПОКАЗ ПРЕДВАРИТЕЛЬНОГО ПРОСМОТРА
    await show_transaction_confirmation(
        message,
        state,
    )


@dp.message(FinanceStates.waiting_expense_input)
async def expense_text_input(
    message: Message,
    state: FSMContext,
):
    user_id = message.from_user.id
    language = get_language(user_id)

    text = (message.text or "").strip()

    if not text:
        await message.answer(
            "Please enter an expense."
            if language == "en"
            else "Введите расход."
        )
        return

    # РАСПОЗНАВАНИЕ СУММЫ И КАТЕГОРИИ

    parsed = await parse_transaction_text(
        text=text,
        transaction_type="expense",
        language=language,
    )

    amount = parsed.get("amount")
    category = parsed.get("category")

    if amount is None:
        await message.answer(
            "I couldn't determine the monetary amount. "
            "Please include the expense amount."
            if language == "en"
            else "Не удалось определить сумму. Укажите сумму расхода."
        )
        return

    # ОПРЕДЕЛЕНИЕ ВАЛЮТЫ

    currencies = find_currency_mentions(text)

    if len(currencies) > 1:
        await message.answer(
            "Please specify only one currency: RUB or USD."
            if language == "en"
            else "Укажите только одну валюту: RUB или USD."
        )
        return

    currency = (
        currencies[0]
        if currencies
        else get_default_currency(user_id)
    )

    if currency not in {"RUB", "USD"}:
        currency = "RUB"

    # СОХРАНЕНИЕ ДАННЫХ В FSM

    await state.update_data(
        transaction_type="expense",
        amount=amount,
        currency=currency,
        category=category,
        comment=text,
        raw_text=text,
    )

    # УДАЛЕНИЕ СООБЩЕНИЙ ВВОДА
    await delete_operation_input_messages(
        message,
        state,
    )

    # ПОКАЗ ПРЕДВАРИТЕЛЬНОГО ПРОСМОТРА
    await show_transaction_confirmation(
        message,
        state,
    )

