def build_transaction_preview(data: dict, language: str):

    transaction_type = data.get("transaction_type")
    amount = data.get("amount")
    currency = data.get("currency", "RUB")
    category = data.get("category")
    comment = data.get("comment", "")

    if language == "ru":

        operation_name = (
            "Доход"
            if transaction_type == "income"
            else "Расход"
        )

        category_name = get_category_display_name(
            category,
            language,
        )

        return (
            f"📋 Предварительный просмотр\n\n"
            f"**Тип:** {operation_name}\n"
            f"**Название:** {comment or 'Не указано'}\n"
            f"**Сумма:** {format_amount(amount)} {currency}\n"
            f"**Категория:** {category_name}\n\n"
            "Проверьте данные перед сохранением."
        )

    operation_name = (
        "Income"
        if transaction_type == "income"
        else "Expense"
    )

    category_name = get_category_display_name(
        category,
        language,
    )

    return (
        f"📋 Transaction preview\n\n"
        f"**Type:** {operation_name}\n"
        f"**Description:** {comment or 'Not specified'}\n"
        f"**Amount:** {format_amount(amount)} {currency}\n"
        f"**Category:** {category_name}\n\n"
        "Check the details before saving."
    )

# ============================================================
# ПОКАЗ ПРЕДВАРИТЕЛЬНОГО ПРОСМОТРА
# ============================================================

async def show_transaction_confirmation(
    message: Message,
    state: FSMContext,
):

    user_id = message.from_user.id
    language = get_language(user_id)

    data = await state.get_data()

    transaction_type = data.get("transaction_type")
    amount = data.get("amount")
    currency = data.get("currency")
    category = data.get("category")

    if transaction_type not in {"income", "expense"}:

        await message.answer(
            "Operation not found."
            if language == "en"
            else "Операция не найдена."
        )
        return

    if not amount or float(amount) <= 0:

        await message.answer(
            "Invalid amount."
            if language == "en"
            else "Некорректная сумма."
        )
        return

    if currency not in {"RUB", "USD"}:
        currency = get_default_currency(user_id)

    if currency not in {"RUB", "USD"}:
        currency = "RUB"

    if not category:
        category = (
            "other_income"
            if transaction_type == "income"
            else "other_expense"
        )

    await state.update_data(
        currency=currency,
        category=category,
    )

    if transaction_type == "income":

        await state.set_state(
            FinanceStates.waiting_income_confirmation
        )

    else:

        await state.set_state(
            FinanceStates.waiting_expense_confirmation
        )

    data = await state.get_data()

    await message.answer(
        build_transaction_preview(
            data,
            language,
        ),
        reply_markup=transaction_preview_keyboard(language),
        parse_mode="Markdown",
    )

