@dp.callback_query(
    F.data.startswith("operation_category_")
)
async def operation_category_select(
    callback: CallbackQuery,
    state: FSMContext,
):
    user_id = callback.from_user.id
    language = get_language(user_id)

    category = callback.data.replace(
        "operation_category_",
        "",
        1,
    )

    data = await state.get_data()
    transaction_type = data.get("transaction_type")

    # Проверяем, что категория подходит типу операции

    if transaction_type == "income":
        valid_categories = INCOME_CATEGORIES_RU
    elif transaction_type == "expense":
        valid_categories = EXPENSE_CATEGORIES_RU
    else:
        await callback.answer(
            "Операция не найдена." if language == "ru" else "Operation not found.",
            show_alert=True,
        )
        return

    if category not in valid_categories:
        await callback.answer(
            "Неизвестная категория." if language == "ru" else "Unknown category.",
            show_alert=True,
        )
        return

    await state.update_data(
        category=category,
        edit_field=None,
    )

    if transaction_type == "income":
        await state.set_state(
            FinanceStates.waiting_income_confirmation
        )
    else:
        await state.set_state(
            FinanceStates.waiting_expense_confirmation
        )

    updated_data = await state.get_data()

    await callback.message.edit_text(
        build_transaction_preview(
            updated_data,
            language,
        ),
        reply_markup=transaction_preview_keyboard(language),
        parse_mode="Markdown",
    )

    await callback.answer(
        "Категория изменена."
        if language == "ru"
        else "Category updated."
    )


