@dp.message(FinanceStates.waiting_operation_edit)
async def operation_edit_input(
    message: Message,
    state: FSMContext,
):
    user_id = message.from_user.id
    language = get_language(user_id)

    data = await state.get_data()

    transaction_type = data.get("transaction_type")
    edit_field = data.get("edit_field")

    text = (message.text or "").strip()

    if not text:
        await message.answer(
            "Введите значение."
            if language == "ru"
            else "Please enter a value."
        )
        return

    # РЕДАКТИРОВАНИЕ СУММЫ

    if edit_field == "amount":

        try:
            amount = parse_money_number(
                text.replace(",", ".")
            )

            if amount is None:
                raise ValueError

            amount = float(amount)

        except (ValueError, TypeError):
            await message.answer(
                "Введите корректную сумму."
                if language == "ru"
                else "Enter a valid amount."
            )
            return

        if amount <= 0:
            await message.answer(
                "Введите корректную сумму."
                if language == "ru"
                else "Enter a valid amount."
            )
            return

        await state.update_data(
            amount=amount,
        )

    # РЕДАКТИРОВАНИЕ КОММЕНТАРИЯ

    elif edit_field == "comment":

        await state.update_data(
            comment=text,
        )

    else:

        await message.answer(
            "Неизвестное поле редактирования."
            if language == "ru"
            else "Unknown editing field."
        )
        return

    if transaction_type == "income":

        await state.set_state(
            FinanceStates.waiting_income_confirmation
        )

    elif transaction_type == "expense":

        await state.set_state(
            FinanceStates.waiting_expense_confirmation
        )

    else:
        await message.answer(
            "Операция не найдена."
            if language == "ru"
            else "Operation not found."
        )
        return

    await state.update_data(
        edit_field=None,
    )

    updated_data = await state.get_data()

    await message.answer(
        build_transaction_preview(
            updated_data,
            language,
        ),
        reply_markup=transaction_preview_keyboard(language),
        parse_mode="Markdown",
    )


