# ЧАСТЬ 4/9
# СТАТИСТИКА + ФИНАНСОВАЯ ДИСЦИПЛИНА
# ============================================================


# ============================================================
# ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ДЛЯ РАБОТЫ С ТРАНЗАКЦИЯМИ
# ============================================================

def transaction_value(transaction, key, default=None):
    """
    Позволяет работать как с dict, так и с sqlite3.Row.
    """
    if transaction is None:
        return default

    if isinstance(transaction, dict):
        return transaction.get(key, default)

    try:
        return transaction[key]
    except (KeyError, IndexError, TypeError):
        return default


def get_user_transactions_safe(user_id: int):
    """
    Безопасно получает все операции пользователя.
    """
    try:
        transactions = get_transactions(user_id)

        if transactions is None:
            return []

        return list(transactions)

    except Exception as e:
        print(
            f"Error getting transactions for {user_id}: {e}"
        )
        return []


def transaction_type_is_income(transaction):
    value = transaction_value(
        transaction,
        "transaction_type",
    )

    if value is None:
        value = transaction_value(
            transaction,
            "type",
        )

    return str(value).lower() in {
        "income",
        "in",
        "доход",
    }


def transaction_amount(transaction):
    value = transaction_value(
        transaction,
        "amount",
        0,
    )

    try:
        return float(value or 0)
    except (TypeError, ValueError):
        return 0.0


def transaction_currency(transaction):
    value = transaction_value(
        transaction,
        "currency",
        "RUB",
    )

    return str(value or "RUB").upper()


def transaction_category(transaction):
    value = transaction_value(
        transaction,
        "category",
        "other_expense",
    )

    return str(
        value or "other_expense"
    )


def transaction_date(transaction):
    value = transaction_value(
        transaction,
        "created_at",
    )

    if value is None:
        value = transaction_value(
            transaction,
            "date",
        )

    if value is None:
        value = transaction_value(
            transaction,
            "timestamp",
        )

    return value




# ============================================================
# КОНВЕРТАЦИЯ В RUB
# ============================================================

def approximate_rub_value(
    amount: float,
    currency: str,
):
    """
    Для статистики используем приблизительную конвертацию.
    Если курс USD недоступен, USD не конвертируется.
    """
    currency = currency.upper()

    if currency == "RUB":
        return amount

    usd_rate = exchange_cache.get(
        "USD"
    )

    if currency == "USD" and usd_rate:
        try:
            return amount * float(usd_rate)
        except (TypeError, ValueError):
            return None

    return None


# ============================================================
# ПЕРИОДЫ СТАТИСТИКИ
# ============================================================

def get_statistics_period(
    period: str,
):
    """
    Возвращает границы периода в формате,
    совместимом с created_at в database.py.

    Возвращает:
        (start_date, end_date, title)
    """

    now = datetime.now(MOSCOW_TZ)

    # В базе datetime.now().isoformat() сохраняется
    # без timezone, поэтому границы тоже делаем naive.
    now_naive = now.replace(
        tzinfo=None
    )

    if period == "month":

        start = datetime(
            now_naive.year,
            now_naive.month,
            1,
        )

        if now_naive.month == 12:
            end = datetime(
                now_naive.year + 1,
                1,
                1,
            )
        else:
            end = datetime(
                now_naive.year,
                now_naive.month + 1,
                1,
            )

        return (
            start.isoformat(),
            end.isoformat(),
            "📅 Этот месяц",
        )

    if period == "3months":

        year = now_naive.year
        month = now_naive.month - 2

        while month <= 0:
            month += 12
            year -= 1

        start = datetime(
            year,
            month,
            1,
        )

        if now_naive.month == 12:
            end = datetime(
                now_naive.year + 1,
                1,
                1,
            )
        else:
            end = datetime(
                now_naive.year,
                now_naive.month + 1,
                1,
            )

        return (
            start.isoformat(),
            end.isoformat(),
            "📅 Последние 3 месяца",
        )

    if period == "6months":

        year = now_naive.year
        month = now_naive.month - 5

        while month <= 0:
            month += 12
            year -= 1

        start = datetime(
            year,
            month,
            1,
        )

        if now_naive.month == 12:
            end = datetime(
                now_naive.year + 1,
                1,
                1,
            )
        else:
            end = datetime(
                now_naive.year,
                now_naive.month + 1,
                1,
            )

        return (
            start.isoformat(),
            end.isoformat(),
            "📅 Последние 6 месяцев",
        )

    if period == "year":

        start = datetime(
            now_naive.year,
            1,
            1,
        )

        end = datetime(
            now_naive.year + 1,
            1,
            1,
        )

        return (
            start.isoformat(),
            end.isoformat(),
            "📅 Этот год",
        )

    if period == "all":

        start = datetime(
            1970,
            1,
            1,
        )

        end = datetime(
            9999,
            12,
            31,
            23,
            59,
            59,
        )

        return (
            start.isoformat(),
            end.isoformat(),
            "📈 За всё время",
        )

    return (
        None,
        None,
        "📊 Статистика",
    )


