# ============================================================
# РАСЧЁТ ОСНОВНОЙ СТАТИСТИКИ
# ============================================================

def calculate_statistics(
    transactions,
    only_current_month=False,
):
    now = datetime.now(MOSCOW_TZ)

    income_rub = 0.0
    expense_rub = 0.0

    income_original = {}
    expense_original = {}

    count = 0

    for transaction in transactions:

        created = transaction_date(
            transaction
        )

        if only_current_month and created:

            try:

                if isinstance(
                    created,
                    str,
                ):
                    parsed_date = datetime.fromisoformat(
                        created.replace(
                            "Z",
                            "+00:00",
                        )
                    )
                elif isinstance(
                    created,
                    datetime,
                ):
                    parsed_date = created
                else:
                    parsed_date = None

                if parsed_date:

                    if parsed_date.tzinfo is None:
                        parsed_date = parsed_date.replace(
                            tzinfo=MOSCOW_TZ
                        )
                    else:
                        parsed_date = parsed_date.astimezone(
                            MOSCOW_TZ
                        )

                    if (
                        parsed_date.year != now.year
                        or parsed_date.month != now.month
                    ):
                        continue

            except Exception:
                pass

        amount = transaction_amount(
            transaction
        )

        if amount <= 0:
            continue

        currency = transaction_currency(
            transaction
        )

        is_income = transaction_type_is_income(
            transaction
        )

        count += 1

        original_dict = (
            income_original
            if is_income
            else expense_original
        )

        original_dict[currency] = (
            original_dict.get(currency, 0)
            + amount
        )

        rub_value = approximate_rub_value(
            amount,
            currency,
        )

        if rub_value is None:
            continue

        if is_income:
            income_rub += rub_value
        else:
            expense_rub += rub_value

    balance = (
        income_rub - expense_rub
    )

    return {
        "income_rub": income_rub,
        "expense_rub": expense_rub,
        "balance": balance,
        "count": count,
        "income_original": income_original,
        "expense_original": expense_original,
    }


# ============================================================
# ТЕКСТ ОСНОВНОЙ СТАТИСТИКИ
# ============================================================

def build_statistics_text(
    language: str,
    statistics,
    title=None,
):

    if title is None:
        title = (
            "📊 Statistics"
            if language == "en"
            else "📊 Статистика"
        )

    income = statistics["income_rub"]
    expense = statistics["expense_rub"]
    balance = statistics["balance"]
    count = statistics["count"]

    if language == "en":

        return (
            f"{title}\n\n"
            f"💰 Income: {format_amount(income)} ₽\n"
            f"💸 Expenses: {format_amount(expense)} ₽\n"
            f"💵 Balance: {format_amount(balance)} ₽\n\n"
            f"🧾 Operations: {count}"
        )

    return (
        f"{title}\n\n"
        f"💰 Доходы: {format_amount(income)} ₽\n"
        f"💸 Расходы: {format_amount(expense)} ₽\n"
        f"💵 Баланс: {format_amount(balance)} ₽\n\n"
        f"🧾 Операций: {count}"
    )


# ============================================================
# ФИЛЬТРАЦИЯ ТРАНЗАКЦИЙ ПО ПЕРИОДУ
# ============================================================

def filter_transactions_by_period(
    transactions,
    period: str,
):

    start_date, end_date, _ = get_statistics_period(
        period
    )

    if start_date is None:
        return transactions

    result = []

    for transaction in transactions:

        created = transaction_date(
            transaction
        )

        if not created:
            continue

        try:

            if isinstance(
                created,
                str,
            ):
                parsed = datetime.fromisoformat(
                    created.replace(
                        "Z",
                        "+00:00",
                    )
                )
            else:
                parsed = created

            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(
                    MOSCOW_TZ
                ).replace(
                    tzinfo=None
                )

            if (
                parsed.isoformat() >= start_date
                and parsed.isoformat() < end_date
            ):
                result.append(
                    transaction
                )

        except Exception:
            continue

    return result

# ============================================================
# КОНВЕРТАЦИЯ ВАЛЮТ ДЛЯ ОТОБРАЖЕНИЯ
# ============================================================

def convert_to_rub(
    amount: float,
    currency: str,
    rates: dict,
):

    if not rates:
        return None

    currency = str(
        currency
    ).upper()

    if currency == "RUB":

        return float(amount)

    rate = rates.get(
        currency
    )

    if rate is None:
        return None

    try:

        return float(amount) * float(rate)

    except (
        TypeError,
        ValueError,
    ):

        return None


def convert_from_rub(
    amount_rub: float,
    currency: str,
    rates: dict,
):

    if not rates:
        return None

    currency = str(
        currency
    ).upper()

    if currency == "RUB":

        return float(amount_rub)

    rate = rates.get(
        currency
    )

    if rate is None:
        return None

    try:

        return float(amount_rub) / float(rate)

    except (
        TypeError,
        ValueError,
        ZeroDivisionError,
    ):

        return None


# ============================================================
# ТЕКСТ СТАТИСТИКИ ПО КАТЕГОРИЯМ
# ============================================================

def build_category_statistics_text(
    language: str,
    transactions,
    transaction_type: str,
    period_title: str,
    display_currency: str,
    rates: dict,
):

    categories = {}

    total = 0.0
    count = 0

    # ========================================================
    # СИМВОЛ ВЫБРАННОЙ ВАЛЮТЫ
    # ========================================================

    currency_symbols = {
        "RUB": "₽",
        "USD": "$",
    }

    currency_symbol = currency_symbols.get(
        display_currency,
        display_currency,
    )

    # ========================================================
    # КОНВЕРТАЦИЯ
    # ========================================================

    def convert_amount(
        amount,
        source_currency,
    ):

        if source_currency == display_currency:

            return float(amount)

        rub_value = convert_to_rub(
            float(amount),
            source_currency,
            rates,
        )

        if rub_value is None:

            return None

        return convert_from_rub(
            rub_value,
            display_currency,
            rates,
        )

    # ========================================================
    # СБОР ДАННЫХ
    # ========================================================

    for transaction in transactions:

        is_income = transaction_type_is_income(
            transaction
        )

        if transaction_type == "income":

            if not is_income:
                continue

        else:

            if is_income:
                continue

        amount = transaction_amount(
            transaction
        )

        if amount <= 0:
            continue

        currency = transaction_currency(
            transaction
        )

        category = transaction_category(
            transaction
        )

        converted_amount = convert_amount(
            amount,
            currency,
        )

        if converted_amount is None:
            continue

        count += 1

        if category not in categories:

            categories[category] = {
                "total": 0.0,
                "count": 0,
            }

        categories[category]["total"] += (
            converted_amount
        )

        categories[category]["count"] += 1

        total += converted_amount

    # ========================================================
    # ЗАГОЛОВОК
    # ========================================================

    if language == "en":

        title = (
            "💰 Income"
            if transaction_type == "income"
            else "💸 Expenses"
        )

        if count == 1:

            operations_text = "1 operation"

        else:

            operations_text = (
                f"{count} operations"
            )

    else:

        title = (
            "💰 Доходы"
            if transaction_type == "income"
            else "💸 Расходы"
        )

        if (
            count % 10 == 1
            and count % 100 != 11
        ):

            operations_text = (
                f"{count} операция"
            )

        elif (
            count % 10 in {2, 3, 4}
            and count % 100 not in {12, 13, 14}
        ):

            operations_text = (
                f"{count} операции"
            )

        else:

            operations_text = (
                f"{count} операций"
            )

    lines = [
        title,
        f"{period_title} · {operations_text}",
        "",
    ]

    # ========================================================
    # НЕТ ОПЕРАЦИЙ
    # ========================================================

    if not categories:

        lines.append(
            "No operations for this period."
            if language == "en"
            else "За этот период операций нет."
        )

        return "\n".join(lines)

    # ========================================================
    # КАТЕГОРИИ
    # ========================================================

    sorted_categories = sorted(
        categories.items(),
        key=lambda item: item[1]["total"],
        reverse=True,
    )

    for category, data in sorted_categories:

        if category == "services":
            name = (
                "🛠️ Services"
                if language == "en"
                else "🛠️ Услуги"
            )
        else:
            name = get_category_display_name(
                category,
                language,
            )

        category_count = data["count"]

        if language == "en":

            if category_count == 1:

                category_operations = (
                    "1 operation"
                )

            else:

                category_operations = (
                    f"{category_count} operations"
                )

        else:

            if (
                category_count % 10 == 1
                and category_count % 100 != 11
            ):

                category_operations = (
                    f"{category_count} операция"
                )

            elif (
                category_count % 10 in {2, 3, 4}
                and category_count % 100
                not in {12, 13, 14}
            ):

                category_operations = (
                    f"{category_count} операции"
                )

            else:

                category_operations = (
                    f"{category_count} операций"
                )

        lines.append(
            name
        )

        lines.append(
            f"{format_amount(data['total'])} "
            f"{currency_symbol} · "
            f"{category_operations}"
        )

        lines.append("")

    # ========================================================
    # ИТОГО
    # ========================================================

    if language == "en":

        lines.append(
            f"Total · "
            f"{format_amount(total)} "
            f"{currency_symbol}"
        )

    else:

        lines.append(
            f"Итого · "
            f"{format_amount(total)} "
            f"{currency_symbol}"
        )

    return "\n".join(lines)

# ============================================================
# ТЕКСТ ИСТОРИИ ОПЕРАЦИЙ
# ============================================================

def build_transaction_history_text(
    language: str,
    transactions,
    period_title: str,
    display_currency: str,
    rates: dict,
):

    count = len(transactions)

    # ========================================================
    # СИМВОЛ ВЫБРАННОЙ ВАЛЮТЫ
    # ========================================================

    currency_symbols = {
        "RUB": "₽",
        "USD": "$",
    }

    currency_symbol = currency_symbols.get(
        display_currency,
        display_currency,
    )

    # ========================================================
    # КОНВЕРТАЦИЯ
    # ========================================================

    def convert_amount(
        amount,
        source_currency,
    ):

        if source_currency == display_currency:

            return float(amount)

        rub_value = convert_to_rub(
            float(amount),
            source_currency,
            rates,
        )

        if rub_value is None:

            return None

        return convert_from_rub(
            rub_value,
            display_currency,
            rates,
        )

    # ========================================================
    # ЗАГОЛОВОК
    # ========================================================

    if language == "en":

        if count == 1:
            operations_text = "1 operation"

        else:
            operations_text = (
                f"{count} operations"
            )

        lines = [
            "🧾 Transaction history",
            f"{period_title} · {operations_text}",
            "",
        ]

    else:

        if (
            count % 10 == 1
            and count % 100 != 11
        ):

            operations_text = (
                f"{count} операция"
            )

        elif (
            count % 10 in {2, 3, 4}
            and count % 100 not in {12, 13, 14}
        ):

            operations_text = (
                f"{count} операции"
            )

        else:

            operations_text = (
                f"{count} операций"
            )

        lines = [
            "🧾 История операций",
            f"{period_title} · {operations_text}",
            "",
        ]

    # ========================================================
    # НЕТ ОПЕРАЦИЙ
    # ========================================================

    if not transactions:

        lines.append(
            "No operations for this period."
            if language == "en"
            else "За этот период операций нет."
        )

        return "\n".join(lines)

    # ========================================================
    # ОПЕРАЦИИ
    # ========================================================

    for transaction in transactions:

        amount = transaction_amount(
            transaction
        )

        source_currency = transaction_currency(
            transaction
        )

        category = transaction_category(
            transaction
        )

        comment = transaction_value(
            transaction,
            "comment",
            "",
        )

        created = transaction_date(
            transaction
        )

        is_income = transaction_type_is_income(
            transaction
        )

        category_name = get_category_display_name(
            category,
            language,
        )

        # ====================================================
        # КОНВЕРТИРОВАННАЯ СУММА
        # ====================================================

        converted_amount = convert_amount(
            amount,
            source_currency,
        )

        if converted_amount is None:

            converted_amount = amount

        # ====================================================
        # ДАТА И ВРЕМЯ
        # ====================================================

        try:

            if isinstance(
                created,
                str,
            ):

                parsed_date = datetime.fromisoformat(
                    created.replace(
                        "Z",
                        "+00:00",
                    )
                )

                if parsed_date.tzinfo is not None:

                    parsed_date = parsed_date.astimezone(
                        MOSCOW_TZ
                    )

                date_text = parsed_date.strftime(
                    "%d.%m · %H:%M"
                )

            elif isinstance(
                created,
                datetime,
            ):

                date_text = created.strftime(
                    "%d.%m · %H:%M"
                )

            else:

                date_text = str(created)

        except Exception:

            date_text = str(created)

        # ====================================================
        # ЗНАК ОПЕРАЦИИ
        # ====================================================

        sign = "＋" if is_income else "−"

        # ====================================================
        # ОСНОВНАЯ ИНФОРМАЦИЯ
        # ====================================================

        lines.append(
            date_text
        )

        lines.append(
            f"{sign} "
            f"{format_amount(converted_amount)} "
            f"{currency_symbol}"
        )

        if comment:

            lines.append(
                f"{category_name} · {comment}"
            )

        else:

            lines.append(
                category_name
            )

        lines.append("")

    return "\n".join(lines)


# ============================================================
# ОСНОВНАЯ СТРАНИЦА СТАТИСТИКИ
# ============================================================

async def render_statistics(
    message: Message,
    user_id: int,
    edit=False,
):

    language = get_language(
        user_id
    )

    if language == "en":

        text = (
            "📊 Statistics\n\n"
            "Choose what you want to view:"
        )

    else:

        text = (
            "📊 Статистика\n\n"
            "Выберите, что хотите посмотреть:"
        )

    keyboard = statistics_keyboard(
        language
    )

    if edit:

        try:
            await message.edit_text(
                text,
                reply_markup=keyboard,
            )
            return
        except Exception:
            pass

    await message.answer(
        text,
        reply_markup=keyboard,
    )


