@dp.callback_query(
    F.data.startswith("stats_period_")
)
async def stats_period_callback(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id

    language = get_language(
        user_id
    )

    parts = callback.data.split(
        "_"
    )

    if len(parts) != 4:

        await callback.answer(
            "Invalid period.",
            show_alert=True,
        )

        return

    section = parts[2]
    period = parts[3]

    if section not in {
        "income",
        "expense",
        "history",
    }:

        await callback.answer(
            "Invalid section.",
            show_alert=True,
        )

        return

    start_date, end_date, period_title = (
        get_statistics_period(
            period
        )
    )

    transactions = get_user_transactions_safe(
        user_id
    )

    transactions = filter_transactions_by_period(
        transactions,
        period,
    )

    # ========================================================
    # ВАЛЮТА И КУРСЫ
    # ========================================================

    display_currency = get_default_currency(
        user_id
    )

    if display_currency not in {
        "RUB",
        "USD",
    }:

        display_currency = "RUB"

    rates = await get_exchange_rates()

    if not rates:

        display_currency = "RUB"

    # ========================================================
    # ПЕРИОД
    # ========================================================

    if language == "ru":

        current_period_title = period_title

    else:

        current_period_title = (
            period_title
            .replace(
                "Этот месяц",
                "This month",
            )
            .replace(
                "Последние 3 месяца",
                "Last 3 months",
            )
            .replace(
                "Последние 6 месяцев",
                "Last 6 months",
            )
            .replace(
                "Этот год",
                "This year",
            )
            .replace(
                "За всё время",
                "All time",
            )
        )

    # ========================================================
    # ИСТОРИЯ
    # ========================================================

    if section == "history":

        text = build_transaction_history_text(
            language,
            transactions,
            current_period_title,
            display_currency,
            rates,
        )

    # ========================================================
    # ДОХОДЫ / РАСХОДЫ
    # ========================================================

    else:

        text = build_category_statistics_text(
            language,
            transactions,
            section,
            current_period_title,
            display_currency,
            rates,
        )

    await callback.answer()

    keyboard = statistics_result_keyboard(
        language,
        section,
        period,
    )

    try:

        await callback.message.edit_text(
            text,
            reply_markup=keyboard,
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=keyboard,
        )




