# ============================================================
# ЧАСТЬ 6/9
# КУРСЫ ВАЛЮТ ЦБ РФ
# ============================================================


# ============================================================
# КЭШ КУРСОВ
# ============================================================

exchange_cache = {}
exchange_cache_time = None

CBR_EXCHANGE_URL = (
    "https://www.cbr.ru/scripts/XML_daily.asp"
)


# ============================================================
# ЗАПРОС КУРСОВ ЦБ РФ
# ============================================================

async def fetch_exchange_rates():
    global exchange_cache
    global exchange_cache_time

    timeout = aiohttp.ClientTimeout(
        total=5
    )

    try:

        async with aiohttp.ClientSession(
            timeout=timeout
        ) as session:

            async with session.get(
                CBR_EXCHANGE_URL
            ) as response:

                if response.status != 200:
                    print(
                        "CBR HTTP status:",
                        response.status,
                    )
                    return None

                xml_data = await response.text(
                    encoding="windows-1251"
                )

        root = ET.fromstring(
            xml_data
        )

        rates = {
            "RUB": 1.0
        }

        for currency in root.findall(
            "Valute"
        ):

            char_code = currency.findtext(
                "CharCode"
            )

            if not char_code:
                continue

            char_code = char_code.upper()

            if char_code not in EXCHANGE_CURRENCIES:
                continue

            nominal_text = currency.findtext(
                "Nominal",
                "1",
            )

            value_text = currency.findtext(
                "Value",
                "0",
            )

            try:

                nominal = float(
                    nominal_text.replace(
                        ",",
                        ".",
                    )
                )

                value = float(
                    value_text.replace(
                        ",",
                        ".",
                    )
                )

            except (
                TypeError,
                ValueError,
            ):
                continue

            if nominal <= 0:
                continue

            # ЦБ показывает стоимость NOMINAL единиц.
            rates[char_code] = (
                value / nominal
            )

        # ----------------------------------------------------
        # ПРОВЕРКА МИНИМАЛЬНОГО НАБОРА
        # ----------------------------------------------------

        if "USD" not in rates:
            print(
                "USD rate was not found in CBR response."
            )

            return None

        exchange_cache = rates
        exchange_cache_time = datetime.now(
            MOSCOW_TZ
        )

        return rates

    except asyncio.TimeoutError as e:

        print(
            "CBR timeout:",
            e,
        )

        return None

    except aiohttp.ClientError as e:

        print(
            "CBR network error:",
            e,
        )

        return None

    except ET.ParseError as e:

        print(
            "CBR XML parse error:",
            e,
        )

        return None

    except Exception as e:

        print(
            "CBR exchange error:",
            e,
        )

        return None


# ============================================================
# ПОЛУЧЕНИЕ КУРСОВ С КЭШЕМ
# ============================================================

async def get_exchange_rates(
    force_refresh=False,
):
    global exchange_cache_time

    now = datetime.now(
        MOSCOW_TZ
    )

    # При обычном открытии используем кэш 1 час.
    if not force_refresh:

        if (
            exchange_cache
            and exchange_cache_time
        ):

            try:

                age = (
                    now
                    - exchange_cache_time
                ).total_seconds()

                if age < 3600:
                    return exchange_cache

            except Exception:
                pass

    # При принудительном обновлении
    # всегда запрашиваем актуальные данные.
    rates = await fetch_exchange_rates()

    # Если получили новые данные,
    # fetch_exchange_rates() должен обновить кэш
    # и время последнего обновления.
    if rates:
        return rates

    # Если ЦБ недоступен,
    # возвращаем последний успешный кэш.
    if exchange_cache:
        return exchange_cache

    return None

# ============================================================
# ФОРМАТИРОВАНИЕ КУРСА
# ============================================================

def format_rate(
    value
):
    try:

        value = float(value)

        if value >= 100:
            return f"{value:,.2f}".replace(
                ",",
                " ",
            )

        if value >= 10:
            return f"{value:,.3f}".replace(
                ",",
                " ",
            )

        return f"{value:,.4f}".replace(
            ",",
            " ",
        )

    except (
        TypeError,
        ValueError,
    ):

        return "—"


