def build_exchange_rates_text(
    language: str,
    rates,
):
    if not rates:

        if language == "en":

            return (
                "💱 Exchange rates\n\n"
                "Unable to load exchange rates "
                "right now. Please try again later."
            )

        return (
            "💱 Курсы валют\n\n"
            "Не удалось загрузить курсы валют. "
            "Попробуйте ещё раз позже."
        )

    if language == "en":

        lines = [
            "💱 Exchange rates",
            "",
            "🇷🇺 Central Bank of Russia",
            "",
        ]

    else:

        lines = [
            "💱 Курсы валют",
            "",
            "🇷🇺 Центральный банк России",
            "",
        ]

    symbols = {
        "USD": "$",
        "EUR": "€",
        "GBP": "£",
        "CNY": "¥",
    }

    for currency in (
        "USD",
        "EUR",
        "GBP",
        "CNY",
    ):

        if currency not in rates:
            continue

        rate = rates[currency]

        symbol = symbols.get(
            currency,
            currency,
        )

        name = CURRENCY_NAMES[
            currency
        ][language]

        if language == "en":

            lines.append(
                f"{symbol} {currency} — "
                f"{format_rate(rate)} ₽"
            )

        else:

            lines.append(
                f"{symbol} {currency} — "
                f"{format_rate(rate)} ₽"
            )

    if exchange_cache_time:

        update_time = exchange_cache_time.astimezone(
            MOSCOW_TZ
        ).strftime(
            "%d.%m.%Y %H:%M"
        )

        if language == "en":

            lines.append(
                f"\nUpdated: {update_time} MSK"
            )

        else:

            lines.append(
                f"\nОбновлено: {update_time} МСК"
            )

    return "\n".join(
        lines
    )


