@dp.callback_query(
    F.data.startswith("currency_source_"),
    FinanceStates.waiting_currency_source,
)
async def currency_converter_select_source(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    currency = callback.data.replace(
        "currency_source_",
        "",
        1,
    )

    if currency not in CONVERTER_CURRENCIES:
        await callback.answer(
            "Unknown currency",
            show_alert=True,
        )
        return

    await state.update_data(
        source_currency=currency
    )

    await state.set_state(
        FinanceStates.waiting_currency_target
    )

    text = (
        f"💱 From: {currency}\n\n"
        "Choose the target currency:"
        if language == "en"
        else
        f"💱 Исходная валюта: {currency}\n\n"
        "Выберите итоговую валюту:"
    )

    await callback.answer()

    await callback.message.edit_text(
        text,
        reply_markup=currency_converter_keyboard(
            language,
            "target",
        ),
    )


