def format_converter_number(
    value: Decimal,
    language: str,
) -> str:

    result = f"{value:,.2f}"

    if language == "ru":
        result = (
            result
            .replace(",", " ")
            .replace(".", ",")
        )

    return result


# ============================================================
# ВВОД СУММЫ И КОНВЕРТАЦИЯ
# ============================================================

@dp.message(
    FinanceStates.waiting_currency_amount
)
async def currency_converter_amount(
    message: Message,
    state: FSMContext,
):

    user_id = message.from_user.id
    language = get_language(user_id)

    if not message.text:
        await message.answer(
            "Введите сумму цифрами."
            if language == "ru"
            else "Please enter a numeric amount."
        )
        return

    amount_text = (
        message.text
        .strip()
        .replace(" ", "")
        .replace("\u00a0", "")
        .replace(",", ".")
    )

    try:
        amount = Decimal(amount_text)

        if not amount.is_finite() or amount <= 0:
            raise InvalidOperation

    except (InvalidOperation, ValueError):

        await message.answer(
            "Введите корректную сумму, например: 878,99 или 343."
            if language == "ru"
            else "Enter a valid amount, for example: 878.99 or 343."
        )
        return

    data = await state.get_data()

    source = data.get("source_currency")
    target = data.get("target_currency")

    if (
        source not in CONVERTER_CURRENCIES
        or target not in CONVERTER_CURRENCIES
    ):
        await state.clear()

        await message.answer(
            "Ошибка конвертации. Откройте конвертер заново."
            if language == "ru"
            else "Conversion error. Please open the converter again.",
            reply_markup=main_menu_keyboard(language),
        )
        return

    # Получаем курсы ЦБ с существующим кэшем.
    rates = await get_exchange_rates()

    if (
        not rates
        or source not in rates
        or target not in rates
    ):
        await message.answer(
            "Не удалось получить курс одной из валют. Попробуйте позже."
            if language == "ru"
            else "Unable to obtain one of the currency rates. Please try again later.",
            reply_markup=currency_converter_cancel_keyboard(
                language
            ),
        )
        return

    # Стоимость одной единицы валюты в рублях.
    source_rate = Decimal(str(rates[source]))
    target_rate = Decimal(str(rates[target]))

    if source_rate <= 0 or target_rate <= 0:
        await message.answer(
            "Некорректный курс валют."
            if language == "ru"
            else "Invalid exchange rate."
        )
        return

    # Расчёт через рубль.
    exchange_rate = source_rate / target_rate
    result = amount * exchange_rate

    # Удаляем сообщение бота с просьбой ввести сумму.
    data = await state.get_data()
    prompt_message_id = data.get(
        "currency_amount_prompt_message_id"
    )

    if prompt_message_id:
        try:
            await message.bot.delete_message(
                chat_id=message.chat.id,
                message_id=prompt_message_id,
            )
        except Exception:
            pass

    # Удаляем введённую пользователем сумму.
    try:
        await message.delete()
    except Exception:
        pass

    # Удаляем сообщение пользователя с введённой суммой.
    try:
        await message.delete()
    except Exception:
        pass

    
    source_name = (
        CONVERTER_CURRENCIES[source][1]
        if language == "ru"
        else CONVERTER_CURRENCIES[source][2]
    )

    target_name = (
        CONVERTER_CURRENCIES[target][1]
        if language == "ru"
        else CONVERTER_CURRENCIES[target][2]
    )

    amount_formatted = format_converter_number(
        amount,
        language,
    )

    result_formatted = format_converter_number(
        result,
        language,
    )

    rate_formatted = format_converter_number(
        exchange_rate,
        language,
    )

    if language == "en":

        result_text = (
            "💱 Currency conversion\n\n"
            f"From: {source_name} ({source})\n"
            f"To: {target_name} ({target})\n\n"
            f"💰 {amount_formatted} {source}\n"
            "⬇️\n"
            f"💰 {result_formatted} {target}\n\n"
            f"Exchange rate: 1 {source} = "
            f"{rate_formatted} {target}\n\n"
            "🇷🇺 Based on Central Bank of Russia rates."
        )

    else:

        result_text = (
            "💱 Результат конвертации\n\n"
            f"Исходная валюта: {source_name} ({source})\n"
            f"Итоговая валюта: {target_name} ({target})\n\n"
            f"💰 {amount_formatted} {source}\n"
            "⬇️\n"
            f"💰 {result_formatted} {target}\n\n"
            f"Курс: 1 {source} = "
            f"{rate_formatted} {target}\n\n"
            "🇷🇺 Расчёт по курсам Центрального банка России."
        )

    await state.clear()

    await message.answer(
        result_text,
        reply_markup=currency_converter_home_keyboard(
            language
        ),
    )


# ============================================================
# ОТМЕНА И ВОЗВРАТ В ГЛАВНОЕ МЕНЮ
# ============================================================

@dp.callback_query(
    F.data.in_({
        "currency_converter_cancel",
        "currency_converter_home",
    })
)
async def currency_converter_back_home(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id
    language = get_language(user_id)

    await state.clear()

    await callback.answer()

    text = (
        "🏠 Main menu"
        if language == "en"
        else "🏠 Главное меню"
    )

    await callback.message.edit_text(
        text,
        reply_markup=main_menu_keyboard(language),
    )


# ============================================================
# РЕНДЕР КУРСОВ
# ============================================================

async def render_exchange_rates(
    message: Message,
    user_id: int,
    edit=False,
    force_refresh=False,
):
    language = get_language(
        user_id
    )

    rates = await get_exchange_rates(
        force_refresh=force_refresh
    )

    text = build_exchange_rates_text(
        language,
        rates,
    )

    keyboard = exchange_rates_keyboard(
        language
    )

    if edit:

        try:

            await message.edit_text(
                text,
                reply_markup=keyboard,
            )

        except Exception as e:

            if "message is not modified" in str(e):
                return

            print(
                "Exchange rates edit error:",
                e,
            )

        return

    await message.answer(
        text,
        reply_markup=keyboard,
    )

# ============================================================
# CALLBACK КУРСОВ
# ============================================================

@dp.callback_query(
    F.data == "exchange_rates"
)
async def exchange_rates_callback(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id

    if not has_accepted_documents(
        user_id
    ):
        await callback.answer(
            "Use /start first.",
            show_alert=True,
        )
        return

    await callback.answer()

    await render_exchange_rates(
        callback.message,
        user_id,
        edit=True,
        force_refresh=True,
    )

# ============================================================
# ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ КОНВЕРТАЦИИ
# ============================================================

def get_rub_value(
    amount: float,
    currency: str,
    rates=None,
):
    currency = (
        currency or "RUB"
    ).upper()

    if currency == "RUB":
        return float(amount)

    if not rates:
        rates = exchange_cache

    rate = rates.get(
        currency
    )

    if rate is None:
        return None

    try:

        return float(amount) * float(
            rate
        )

    except (
        TypeError,
        ValueError,
    ):

        return None


def get_currency_value(
    rub_amount: float,
    currency: str,
    rates=None,
):
    currency = (
        currency or "RUB"
    ).upper()

    if currency == "RUB":
        return float(rub_amount)

    if not rates:
        rates = exchange_cache

    rate = rates.get(
        currency
    )

    if not rate:
        return None

    try:

        return float(rub_amount) / float(
            rate
        )

    except (
        TypeError,
        ValueError,
    ):

        return None


