def reminder_type_keyboard( 
    language: str, 
): 
 
    buttons = [] 
 
    for reminder_type, names in REMINDER_TYPES.items(): 
 
        buttons.append( 
            [ 
                InlineKeyboardButton( 
                    text=names[language], 
                    callback_data=( 
                        f"reminder_type:{reminder_type}" 
                    ), 
                ) 
            ] 
        ) 
 
    if language == "en": 
 
        buttons.append( 
            [ 
                InlineKeyboardButton( 
                    text="⬅️ Back", 
                    callback_data="reminder_cancel", 
                ), 
                InlineKeyboardButton( 
                    text="🏠 Menu", 
                    callback_data="back_to_menu", 
                ), 
            ] 
        ) 
 
    else: 
 
        buttons.append( 
            [ 
                InlineKeyboardButton( 
                    text="⬅️ Назад", 
                    callback_data="reminder_cancel", 
                ), 
                InlineKeyboardButton( 
                    text="🏠 Меню", 
                    callback_data="back_to_menu", 
                ), 
            ] 
        ) 
 
    return InlineKeyboardMarkup( 
        inline_keyboard=buttons 
    )


