def reminder_time_keyboard(
    language: str,
):

    times = [
        "08:00",
        "09:00",
        "10:00",
        "12:00",
        "18:00",
        "19:00",
        "20:00",
        "21:00",
    ]

    keyboard = []

    row = []

    for time_value in times:

        row.append(
            InlineKeyboardButton(
                text=time_value,
                callback_data=(
                    f"reminder_time:{time_value}"
                ),
            )
        )

        if len(row) == 2:

            keyboard.append(row)
            row = []

    if row:
        keyboard.append(row)

    keyboard.append(
        [
            InlineKeyboardButton(
                text=(
                    "✏️ Enter another time"
                    if language == "en"
                    else "✏️ Ввести другое время"
                ),
                callback_data="reminder_time_custom",
            )
        ]
    )

    keyboard.append(
        [
            InlineKeyboardButton(
                text=(
                    "🌍 Change timezone"
                    if language == "en"
                    else "🌍 Изменить часовой пояс"
                ),
                callback_data="reminder_change_timezone",
            )
        ]
    )

    keyboard.append(
        [
            InlineKeyboardButton(
                text=(
                    "❌ Cancel"
                    if language == "en"
                    else "❌ Отмена"
                ),
                callback_data="reminder_cancel",
            ),
            InlineKeyboardButton(
                text=(
                    "🏠 Menu"
                    if language == "en"
                    else "🏠 Меню"
                ),
                callback_data="back_to_menu",
            ),
        ]
    )

    return InlineKeyboardMarkup(
        inline_keyboard=keyboard
    )


# ============================================================
# СПИСОК НАПОМИНАНИЙ
# ============================================================

def reminder_list_keyboard(
    language: str,
    reminders,
):

    keyboard = []

    for reminder in reminders:

        reminder_id = transaction_value(
            reminder,
            "id",
        )

        reminder_type = transaction_value(
            reminder,
            "reminder_type",
        )

        reminder_time = transaction_value(
            reminder,
            "reminder_time",
        )

        timezone_name = transaction_value(
            reminder,
            "timezone",
            "Europe/Moscow",
        )

        if reminder_id is None:
            continue

        name = REMINDER_TYPES.get(
            reminder_type,
            {},
        ).get(
            language,
            reminder_type or "Reminder",
        )

        timezone_label = REMINDER_TIMEZONES.get(
            timezone_name,
            {},
        ).get(
            language,
            timezone_name,
        )

        keyboard.append(
            [
                InlineKeyboardButton(
                    text=(
                        f"{name} — "
                        f"{reminder_time or '—'}"
                    ),
                    callback_data=(
                        f"reminder_manage:{reminder_id}"
                    ),
                )
            ]
        )

    keyboard.append(
        [
            InlineKeyboardButton(
                text=(
                    "➕ Add"
                    if language == "en"
                    else "➕ Добавить"
                ),
                callback_data="reminder_add",
            )
        ]
    )

    keyboard.append(
        [
            InlineKeyboardButton(
                text=(
                    "⬅️ Back"
                    if language == "en"
                    else "⬅️ Назад"
                ),
                callback_data="reminders",
            ),
            InlineKeyboardButton(
                text=(
                    "🏠 Menu"
                    if language == "en"
                    else "🏠 Меню"
                ),
                callback_data="back_to_menu",
            ),
        ]
    )

    return InlineKeyboardMarkup(
        inline_keyboard=keyboard
    )


# ============================================================
# УПРАВЛЕНИЕ НАПОМИНАНИЕМ
# ============================================================

def reminder_actions_keyboard(
    language: str,
    reminder_id,
):

    if language == "en":

        return InlineKeyboardMarkup(
            inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text="🕐 Change time",
                        callback_data=(
                            f"reminder_change_time:{reminder_id}"
                        ),
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="🌍 Change timezone",
                        callback_data=(
                            f"reminder_change_timezone_id:{reminder_id}"
                        ),
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="🗑 Delete",
                        callback_data=(
                            f"reminder_delete:{reminder_id}"
                        ),
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="❌ Cancel",
                        callback_data="reminder_cancel",
                    ),
                    InlineKeyboardButton(
                        text="🏠 Menu",
                        callback_data="back_to_menu",
                    ),
                ],
            ]
        )

    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text="🕐 Изменить время",
                    callback_data=(
                        f"reminder_change_time:{reminder_id}"
                    ),
                )
            ],
            [
                InlineKeyboardButton(
                    text="🌍 Изменить часовой пояс",
                    callback_data=(
                        f"reminder_change_timezone_id:{reminder_id}"
                    ),
                )
            ],
            [
                InlineKeyboardButton(
                    text="🗑 Удалить",
                    callback_data=(
                        f"reminder_delete:{reminder_id}"
                    ),
                )
            ],
            [
                InlineKeyboardButton(
                    text="❌ Отмена",
                    callback_data="reminder_cancel",
                ),
                InlineKeyboardButton(
                    text="🏠 Меню",
                    callback_data="back_to_menu",
                ),
            ],
        ]
    )


# ============================================================
# ГЛАВНЫЙ ЭКРАН НАПОМИНАНИЙ
# ============================================================

async def render_reminders(
    message: Message,
    user_id: int,
    edit=False,
):

    language = get_language(
        user_id
    )

    if language == "en":

        text = (
            "⏰ Reminders\n\n"
            "Set daily reminders to keep your "
            "financial records up to date.\n\n"
            "Each reminder has its own timezone "
            "and time."
        )

    else:

        text = (
            "⏰ Напоминания\n\n"
            "Установите ежедневные напоминания, "
            "чтобы не забывать вести учёт финансов.\n\n"
            "Для каждого напоминания можно выбрать "
            "свой часовой пояс и время."
        )

    keyboard = reminders_keyboard(
        language
    )

    if edit:

        try:

            await message.edit_text(
                text,
                reply_markup=keyboard,
            )

            return

        except Exception:
            pass

    await message.answer(
        text,
        reply_markup=keyboard,
    )


# ============================================================
# ОТМЕНА СОЗДАНИЯ / ИЗМЕНЕНИЯ
# ============================================================

@dp.callback_query(
    F.data == "reminder_cancel"
)
async def reminder_cancel_callback(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id

    await state.clear()

    await callback.answer()

    await render_reminders(
        callback.message,
        user_id,
        edit=True,
    )


# ============================================================
# CALLBACK ГЛАВНОГО ЭКРАНА
# ============================================================

@dp.callback_query(
    F.data == "reminders"
)
async def reminders_callback(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id

    if not has_accepted_documents(
        user_id
    ):

        await callback.answer(
            "Use /start first.",
            show_alert=True,
        )

        return

    await callback.answer()

    await render_reminders(
        callback.message,
        user_id,
        edit=True,
    )


