@dp.callback_query(
    F.data.startswith("reminder_type:")
)
async def reminder_type_callback(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id

    language = get_language(
        user_id
    )

    reminder_type = callback.data.split(
        ":",
        1,
    )[1]

    if reminder_type not in REMINDER_TYPES:

        await callback.answer(
            "Invalid reminder.",
            show_alert=True,
        )

        return

    await state.update_data(
        reminder_type=reminder_type,
        edit_reminder_id=None,
    )

    await state.set_state(
        FinanceStates.waiting_reminder_time
    )

    await callback.answer()

    if language == "en":

        text = (
            "🌍 Choose a timezone\n\n"
            "The reminder will be sent according "
            "to the local time in this timezone."
        )

    else:

        text = (
            "🌍 Выберите часовой пояс\n\n"
            "Напоминание будет отправляться "
            "по местному времени выбранного "
            "часового пояса."
        )

    try:

        await callback.message.edit_text(
            text,
            reply_markup=reminder_timezone_new_keyboard(
                language
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=reminder_timezone_new_keyboard(
                language
            ),
        )


