# УПРАВЛЕНИЕ КОНКРЕТНЫМ НАПОМИНАНИЕМ
# ============================================================

@dp.callback_query(
    F.data.startswith("reminder_manage:")
)
async def reminder_manage_callback(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id

    language = get_language(
        user_id
    )

    try:

        reminder_id = int(
            callback.data.split(
                ":",
                1,
            )[1]
        )

    except (
        ValueError,
        IndexError,
    ):

        await callback.answer(
            "Invalid reminder.",
            show_alert=True,
        )

        return

    reminder = None

    try:

        reminders = get_reminders(
            user_id
        )

        for item in reminders or []:

            item_id = transaction_value(
                item,
                "id",
            )

            if str(item_id) == str(
                reminder_id
            ):

                reminder = item
                break

    except Exception as e:

        print(
            "Reminder lookup error:",
            e,
        )

    if reminder is None:

        await callback.answer(
            (
                "Reminder not found."
                if language == "en"
                else "Напоминание не найдено."
            ),
            show_alert=True,
        )

        return

    reminder_type = transaction_value(
        reminder,
        "reminder_type",
        "",
    )

    reminder_time = transaction_value(
        reminder,
        "reminder_time",
        "—",
    )

    timezone_name = transaction_value(
        reminder,
        "timezone",
        "Europe/Moscow",
    )

    name = REMINDER_TYPES.get(
        reminder_type,
        {},
    ).get(
        language,
        reminder_type,
    )

    timezone_label = REMINDER_TIMEZONES.get(
        timezone_name,
        {},
    ).get(
        language,
        timezone_name,
    )

    if language == "en":

        text = (
            "⏰ Reminder\n\n"
            f"{name}\n"
            f"Time: {reminder_time}\n"
            f"Timezone: {timezone_label}"
        )

    else:

        text = (
            "⏰ Напоминание\n\n"
            f"{name}\n"
            f"Время: {reminder_time}\n"
            f"Часовой пояс: {timezone_label}"
        )

    await callback.answer()

    try:

        await callback.message.edit_text(
            text,
            reply_markup=reminder_actions_keyboard(
                language,
                reminder_id,
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=reminder_actions_keyboard(
                language,
                reminder_id,
            ),
        )


# ============================================================
