# ============================================================

@dp.callback_query(
    F.data.startswith("reminder_change_time:")
)
async def reminder_change_time_callback(
    callback: CallbackQuery,
    state: FSMContext,
):

    user_id = callback.from_user.id

    language = get_language(
        user_id
    )

    try:

        reminder_id = int(
            callback.data.split(
                ":",
                1,
            )[1]
        )

    except (
        ValueError,
        IndexError,
    ):

        await callback.answer(
            "Invalid reminder.",
            show_alert=True,
        )

        return

    reminder = None

    try:

        reminders = get_reminders(
            user_id
        )

        for item in reminders or []:

            if str(
                transaction_value(
                    item,
                    "id",
                )
            ) == str(reminder_id):

                reminder = item
                break

    except Exception as e:

        print(
            "Reminder lookup error:",
            e,
        )

    if reminder is None:

        await callback.answer(
            (
                "Reminder not found."
                if language == "en"
                else "Напоминание не найдено."
            ),
            show_alert=True,
        )

        return

    timezone_name = transaction_value(
        reminder,
        "timezone",
        "Europe/Moscow",
    )

    await state.update_data(
        edit_reminder_id=reminder_id,
        edit_reminder_timezone=timezone_name,
    )

    await state.set_state(
        FinanceStates.waiting_reminder_time
    )

    await callback.answer()

    if language == "en":

        text = (
            "🕐 Enter the new time\n\n"
            "Use HH:MM format.\n"
            "For example: 09:30 or 23:45."
        )

    else:

        text = (
            "🕐 Введите новое время\n\n"
            "Используйте формат ЧЧ:ММ.\n"
            "Например: 09:30 или 23:45."
        )

    try:

        await callback.message.edit_text(
            text,
            reply_markup=reminder_cancel_keyboard(
                language
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=reminder_cancel_keyboard(
                language
            ),
        )


# ============================================================
# СОХРАНЕНИЕ НОВОГО ВРЕМЕНИ
# ============================================================

async def update_existing_reminder_time(
    user_id: int,
    language: str,
    time_value: str,
    state: FSMContext,
):

    data = await state.get_data()

    reminder_id = data.get(
        "edit_reminder_id"
    )

    if reminder_id is None:

        return False

    updated = update_reminder(
        reminder_id,
        user_id,
        reminder_time=time_value,
    )

    if not updated:

        return False

    await state.clear()

    if language == "en":

        text = (
            "✅ Reminder updated.\n\n"
            f"New time: {time_value}"
        )

    else:

        text = (
            "✅ Напоминание изменено.\n\n"
            f"Новое время: {time_value}"
        )

    return text


