@dp.message(
    FinanceStates.waiting_reminder_time
)
async def reminder_time_text(
    message: Message,
    state: FSMContext,
):

    user_id = message.from_user.id

    language = get_language(
        user_id
    )

    time_value = (
        message.text or ""
    ).strip()

    if not re.fullmatch(
        r"(?:[01]\d|2[0-3]):[0-5]\d",
        time_value,
    ):

        await message.answer(
            (
                "Enter time in HH:MM format."
                if language == "en"
                else "Введите время в формате ЧЧ:ММ."
            ),
            reply_markup=reminder_cancel_keyboard(
                language
            ),
        )

        return

    data = await state.get_data()

    edit_reminder_id = data.get(
        "edit_reminder_id"
    )

    # --------------------------------------------------------
    # ИЗМЕНЕНИЕ СУЩЕСТВУЮЩЕГО
    # --------------------------------------------------------

    if edit_reminder_id is not None:

        text = await update_existing_reminder_time(
            user_id,
            language,
            time_value,
            state,
        )

        if not text:

            await message.answer(
                (
                    "Could not update reminder."
                    if language == "en"
                    else "Не удалось изменить напоминание."
                ),
                reply_markup=reminder_cancel_keyboard(
                    language
                ),
            )

            return

        await message.answer(
            text,
            reply_markup=reminders_keyboard(
                language
            ),
        )

        return

    # --------------------------------------------------------
    # СОЗДАНИЕ НОВОГО
    # --------------------------------------------------------

    if not data.get("timezone"):

        await message.answer(
            (
                "Choose a timezone first."
                if language == "en"
                else "Сначала выберите часовой пояс."
            ),
            reply_markup=reminder_timezone_new_keyboard(
                language
            ),
        )

        return

    text = await save_reminder_from_state(
        user_id,
        language,
        time_value,
        state,
    )

    if not text:

        await message.answer(
            (
                "Could not save reminder."
                if language == "en"
                else "Не удалось сохранить напоминание."
            ),
            reply_markup=reminder_cancel_keyboard(
                language
            ),
        )

        return

    await message.answer(
        text,
        reply_markup=reminders_keyboard(
            language
        ),
    )


# ============================================================
# ПЛАНИРОВЩИК НАПОМИНАНИЙ
# ============================================================

reminder_scheduler_task = None


async def reminder_scheduler():

    """
    Проверяет напоминания каждую минуту.

    Для каждого напоминания используется
    его собственный часовой пояс.

    После успешной отправки напоминание
    удаляется из базы данных.
    """

    while True:

        try:

            now_utc = datetime.now(
                ZoneInfo("UTC")
            )

            try:

                reminders = get_enabled_reminders()

            except Exception as e:

                print(
                    "Get enabled reminders error:",
                    e,
                )

                reminders = []

            for reminder in reminders or []:

                user_id = transaction_value(
                    reminder,
                    "telegram_id",
                )

                reminder_id = transaction_value(
                    reminder,
                    "id",
                )

                reminder_type = transaction_value(
                    reminder,
                    "reminder_type",
                )

                reminder_time = transaction_value(
                    reminder,
                    "reminder_time",
                )

                timezone_name = transaction_value(
                    reminder,
                    "timezone",
                    "Europe/Moscow",
                )

                if not user_id:
                    continue

                if not reminder_id:
                    continue

                if not reminder_time:
                    continue

                if not timezone_name:
                    timezone_name = "Europe/Moscow"

                try:

                    user_timezone = ZoneInfo(
                        timezone_name
                    )

                except Exception as e:

                    print(
                        f"Invalid timezone "
                        f"{timezone_name} "
                        f"for reminder "
                        f"{reminder_id}:",
                        e,
                    )

                    continue

                local_now = now_utc.astimezone(
                    user_timezone
                )

                current_time = local_now.strftime(
                    "%H:%M"
                )

                if str(reminder_time) != current_time:
                    continue

                language = get_language(
                    int(user_id)
                )

                # ------------------------------------------------
                # ТЕКСТ НАПОМИНАНИЯ
                # ------------------------------------------------

                if language == "en":

                    if reminder_type == "daily_expenses":

                        text = (
                            "💸 Don't forget to record an expense."
                        )

                    elif reminder_type == "daily_income":

                        text = (
                            "💰 Don't forget to record an income."
                        )

                    elif reminder_type == "daily_finance":

                        text = (
                            "📊 Check your finances."
                        )

                    else:

                        text = (
                            "⏰ Check your finances."
                        )

                else:

                    if reminder_type == "daily_expenses":

                        text = (
                            "💸 Не забудьте записать расход."
                        )

                    elif reminder_type == "daily_income":

                        text = (
                            "💰 Не забудьте записать доход."
                        )

                    elif reminder_type == "daily_finance":

                        text = (
                            "📊 Проверьте свои финансы."
                        )

                    else:

                        text = (
                            "⏰ Проверьте свои финансы."
                        )

                # ------------------------------------------------
                # ОТПРАВКА И УДАЛЕНИЕ
                # ------------------------------------------------

                try:

                    await bot.send_message(
                        int(user_id),
                        text,
                    )

                    deleted = delete_reminder(
                        int(reminder_id),
                        int(user_id),
                    )

                    if deleted:

                        print(
                            f"Reminder {reminder_id} "
                            f"sent and deleted "
                            f"for user {user_id}"
                        )

                    else:

                        print(
                            f"Reminder {reminder_id} "
                            f"was sent, but was not deleted "
                            f"for user {user_id}"
                        )

                except Exception as e:

                    print(
                        f"Could not send reminder "
                        f"to {user_id}:",
                        e,
                    )

        except Exception as e:

            print(
                "Reminder scheduler error:",
                e,
            )

        await asyncio.sleep(
            60
        )


# ============================================================
# ЗАПУСК ПЛАНИРОВЩИКА
# ============================================================

def start_reminder_scheduler():

    global reminder_scheduler_task

    if (
        reminder_scheduler_task is None
        or reminder_scheduler_task.done()
    ):

        reminder_scheduler_task = (
            asyncio.create_task(
                reminder_scheduler()
            )
        )

    return reminder_scheduler_task


