# ============================================================
# ОТОБРАЖЕНИЕ UTC-СМЕЩЕНИЯ
# ============================================================

def get_timezone_utc_label(timezone_name: str) -> str:

    timezone = pytz.timezone(timezone_name)

    now = datetime.now()

    winter_offset = timezone.localize(
        datetime(now.year, 1, 15, 12, 0)
    ).strftime("%z")

    summer_offset = timezone.localize(
        datetime(now.year, 7, 15, 12, 0)
    ).strftime("%z")

    def format_offset(offset):
        sign = offset[0]
        hours = offset[1:3]
        minutes = offset[3:5]

        return f"UTC{sign}{hours}:{minutes}"

    winter = format_offset(winter_offset)
    summer = format_offset(summer_offset)

    if winter == summer:
        return winter

    return f"{winter} / {summer}"


