def timezone_cities_keyboard(
    region: str,
    language: str,
):

    cities = TIMEZONE_CITIES.get(region, [])

    keyboard = []

    for city_en, city_ru, country_en, country_ru, timezone_name in cities:

        if language == "en":
            city_name = city_en
            country_name = country_en
        else:
            city_name = city_ru
            country_name = country_ru

        utc_label = get_timezone_utc_label(timezone_name)

        keyboard.append([
            InlineKeyboardButton(
                text=f"📍 {city_name}, {country_name} ({utc_label})",
                callback_data=(
                    f"timezone_select_{timezone_name.replace('/', '~')}"
                ),
            )
        ])

    back_text = (
        "⬅️ Back to regions"
        if language == "en"
        else "⬅️ Назад к регионам"
    )

    keyboard.append([
        InlineKeyboardButton(
            text=back_text,
            callback_data="settings_timezone",
        )
    ])

    return InlineKeyboardMarkup(
        inline_keyboard=keyboard
    )


