@dp.callback_query(
    F.data.startswith("timezone_region_")
)
async def timezone_region_select(
    callback: CallbackQuery,
):

    region = callback.data.replace(
        "timezone_region_",
        "",
        1,
    )

    user_id = callback.from_user.id
    language = get_language(user_id)

    region_names = {
        "africa": ("Africa", "Африка"),
        "america": ("Americas", "Америка"),
        "asia": ("Asia", "Азия"),
        "europe": ("Europe", "Европа"),
        "oceania": ("Oceania", "Океания"),
        "other": ("Other", "Другие"),
    }

    if region not in region_names:
        await callback.answer(
            "Unknown region",
            show_alert=True,
        )
        return

    region_name = region_names[region][
        0 if language == "en" else 1
    ]

    text = (
        f"🌍 {region_name}\n\n"
        + (
            "Choose a city and time zone:"
            if language == "en"
            else "Выберите город и часовой пояс:"
        )
    )

    await callback.answer()

    await callback.message.edit_text(
        text,
        reply_markup=timezone_cities_keyboard(
            region,
            language,
        ),
    )


