@dp.callback_query(
    F.data.startswith("timezone_select_")
)
async def timezone_select(
    callback: CallbackQuery,
):

    user_id = callback.from_user.id

    timezone_name = callback.data.replace(
        "timezone_select_",
        "",
        1,
    ).replace("~", "/")

    language = get_language(user_id)

    # Проверяем, существует ли такой часовой пояс
    try:
        pytz.timezone(timezone_name)

    except pytz.exceptions.UnknownTimeZoneError:
        await callback.answer(
            "Unknown time zone" if language == "en"
            else "Неизвестный часовой пояс",
            show_alert=True,
        )
        return

    # Сохраняем часовой пояс пользователя
    update_user_settings(
        telegram_id=user_id,
        timezone=timezone_name,
    )

    await callback.answer(
        "Time zone saved" if language == "en"
        else "Часовой пояс сохранён"
    )

    # Возвращаем пользователя в настройки
    await render_settings(
        callback.message,
        user_id,
        edit=True,
    )


