def get_user_timezone_obj(user_id: int):
    """
    Возвращает объект часового пояса пользователя.
    """

    timezone_name = get_user_timezone_or_default(
        user_id
    )

    return pytz.timezone(timezone_name)


def get_user_now(user_id: int):
    """
    Возвращает текущее время в часовом поясе пользователя.
    """

    timezone = get_user_timezone_obj(
        user_id
    )

    return datetime.now(timezone)


