async def render_settings(
    message: Message,
    user_id: int,
    edit=False,
):
    language = get_language(
        user_id
    )

    try:
        default_currency = get_default_currency(
            user_id
        )
    except Exception:
        default_currency = "RUB"

    if default_currency not in TRANSACTION_CURRENCIES:
        default_currency = "RUB"

    timezone_name = get_user_timezone_or_default(
        user_id
    )

    if language == "en":

        currency_name = {
            "RUB": "RUB ₽",
            "USD": "USD $",
        }.get(
            default_currency,
            default_currency,
        )

        text = (
            "⚙️ Settings\n\n"
            f"🌐 Language: English\n"
            f"💱 Default currency: {currency_name}\n"
            f"🌍 Time zone: {timezone_name}"
        )

    else:

        currency_name = {
            "RUB": "RUB ₽",
            "USD": "USD $",
        }.get(
            default_currency,
            default_currency,
        )

        text = (
            "⚙️ Настройки\n\n"
            f"🌐 Язык: Русский\n"
            f"💱 Валюта по умолчанию: {currency_name}\n"
            f"🌍 Часовой пояс: {timezone_name}"
        )

    keyboard = settings_keyboard(
        language
    )

    if edit:

        try:

            await message.edit_text(
                text,
                reply_markup=keyboard,
            )

            return

        except Exception:
            pass

    await message.answer(
        text,
        reply_markup=keyboard,
    )


