# Сообщения незавершённых платежей
pending_payment_messages = {}

async def cleanup_payment_messages(bot, user_id):
    data = pending_payment_messages.pop(user_id, None)

    if not data:
        return

    chat_id = user_id

    for message_id in (
        data.get("invoice_id"),
        data.get("notice_id"),
    ):
        if message_id:
            try:
                await bot.delete_message(
                    chat_id=chat_id,
                    message_id=message_id,
                )
            except Exception as error:
                print("PAYMENT MESSAGE DELETE ERROR:", repr(error))

# ============================================================
# DATABASE: ТАБЛИЦЫ ПЛАТЕЖЕЙ
# ============================================================

def ensure_payment_tables(connection):

    cursor = connection.cursor()

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS premium_subscriptions (
            telegram_id INTEGER PRIMARY KEY,
            started_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,

            FOREIGN KEY (telegram_id)
                REFERENCES users(telegram_id)
                ON DELETE CASCADE
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS star_payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            telegram_id INTEGER NOT NULL,
            telegram_payment_charge_id TEXT NOT NULL UNIQUE,
            amount INTEGER NOT NULL,
            currency TEXT NOT NULL,
            payment_type TEXT NOT NULL,
            payload TEXT,
            created_at TEXT NOT NULL,

            FOREIGN KEY (telegram_id)
                REFERENCES users(telegram_id)
                ON DELETE CASCADE
        )
    """)


# ============================================================
# ДОБАВЛЕНИЕ МЕСЯЦЕВ К ДАТЕ
# ============================================================

def add_calendar_months(date_value, months):

    month_index = date_value.month - 1 + months

    year = date_value.year + month_index // 12

    month = month_index % 12 + 1

    day = min(
        date_value.day,
        calendar.monthrange(year, month)[1],
    )

    return date_value.replace(
        year=year,
        month=month,
        day=day,
    )


# ============================================================
# ПРОВЕРКА PREMIUM
# ============================================================

def is_premium_active(telegram_id: int) -> bool:

    if telegram_id == 6860467092:
        return True
        
    connection = get_connection()

    try:

        ensure_payment_tables(connection)

        cursor = connection.cursor()

        cursor.execute(
            """
            SELECT expires_at
            FROM premium_subscriptions
            WHERE telegram_id = ?
            """,
            (telegram_id,),
        )

        row = cursor.fetchone()

        if row is None:
            return False

        expires_at = datetime.fromisoformat(row[0])

        return expires_at > datetime.now()

    finally:
        connection.close()





# ============================================================
# СОХРАНЕНИЕ УСПЕШНОГО ПЛАТЕЖА
# ============================================================

def save_successful_star_payment(
    telegram_id: int,
    payment,
    payment_type: str,
    months: int = 0,
) -> bool:

    connection = get_connection()

    try:

        ensure_payment_tables(connection)

        cursor = connection.cursor()

        now = datetime.now()

        now_text = now.isoformat(timespec="seconds")

        cursor.execute(
            """
            INSERT OR IGNORE INTO star_payments (
                telegram_id,
                telegram_payment_charge_id,
                amount,
                currency,
                payment_type,
                payload,
                created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                telegram_id,
                payment.telegram_payment_charge_id,
                payment.total_amount,
                payment.currency,
                payment_type,
                payment.invoice_payload,
                now_text,
            ),
        )

        # Не обрабатываем повторно один и тот же платёж.
        if cursor.rowcount == 0:
            connection.rollback()
            return False

        if payment_type == "premium":

            cursor.execute(
                """
                SELECT started_at, expires_at
                FROM premium_subscriptions
                WHERE telegram_id = ?
                """,
                (telegram_id,),
            )

            row = cursor.fetchone()

            if row is not None:

                old_started = datetime.fromisoformat(row[0])
                old_expires = datetime.fromisoformat(row[1])

            else:

                old_started = now
                old_expires = now

            if old_expires > now:

                subscription_start = old_started
                extension_start = old_expires

            else:

                subscription_start = now
                extension_start = now

            new_expiration = add_calendar_months(
                extension_start,
                months,
            )

            cursor.execute(
                """
                INSERT INTO premium_subscriptions (
                    telegram_id,
                    started_at,
                    expires_at
                )
                VALUES (?, ?, ?)

                ON CONFLICT(telegram_id)
                DO UPDATE SET
                    started_at = excluded.started_at,
                    expires_at = excluded.expires_at
                """,
                (
                    telegram_id,
                    subscription_start.isoformat(timespec="seconds"),
                    new_expiration.isoformat(timespec="seconds"),
                ),
            )

        connection.commit()

        return True

    except Exception:

        connection.rollback()
        raise

    finally:

        connection.close()


