def premium_keyboard(language: str):

    plans = []

    for months in (1, 3, 6, 12):

        base_price = PREMIUM_PLANS[months]["price"]
        discount = PREMIUM_PLANS[months]["discount"]

        price = round(base_price * (100 - discount) / 100)

        if language == "en":
            period = {
                1: "1 month",
                3: "3 months",
                6: "6 months",
                12: "1 year",
            }[months]
        else:
            period = {
                1: "1 месяц",
                3: "3 месяца",
                6: "6 месяцев",
                12: "1 год",
            }[months]

        label = f"{period} — {price} ⭐"

        if discount:
            label += f" (-{discount}%)"

        plans.append(
            InlineKeyboardButton(
                text=label,
                callback_data=f"premium_plan:{months}",
            )
        )

    back_text = "◀️ Back" if language == "en" else "◀️ Назад"

    return InlineKeyboardMarkup(
        inline_keyboard=[
            [plans[0], plans[1]],
            [plans[2], plans[3]],
            [
                InlineKeyboardButton(
                    text=back_text,
                    callback_data="settings",
                )
            ],
        ]
    )

