@dp.callback_query(F.data.startswith("premium_confirm:"))
async def premium_confirm_callback(callback: CallbackQuery):

    user_id = callback.from_user.id
    language = get_language(user_id)

    try:
        months = int(callback.data.split(":")[1])
    except (ValueError, IndexError):
        await callback.answer("Invalid plan.", show_alert=True)
        return

    if months not in PREMIUM_PLANS:
        await callback.answer("Invalid plan.", show_alert=True)
        return

    base_price = PREMIUM_PLANS[months]["price"]
    discount = PREMIUM_PLANS[months]["discount"]

    price = round(base_price * (100 - discount) / 100)

    periods = {
        1: ("1 month", "1 месяц"),
        3: ("3 months", "3 месяца"),
        6: ("6 months", "6 месяцев"),
        12: ("1 year", "1 год"),
    }

    period = periods[months][0 if language == "en" else 1]

    payload = (
        f"pf:premium:{user_id}:{months}:{price}:{uuid.uuid4().hex[:12]}"
    )

    title = "PocketFinance Premium"

    description = (
        f"Premium subscription for {period}."
        if language == "en"
        else f"Подписка Premium на срок: {period}."
    )

    label = f"Premium — {period}"

    notice = (
        "Complete the payment using the invoice below."
        if language == "en"
        else "Оплатите подписку с помощью счёта ниже."
    )

    cancel_text = (
        "❌ Cancel purchase"
        if language == "en"
        else "❌ Отменить покупку"
    )

    await callback.answer()

    try:
        # Удаляем предыдущий счёт, если он был
        await cleanup_payment_messages(callback.bot, user_id)

        # Сообщение с инструкцией и кнопкой отмены
        await callback.message.edit_text(
            notice,
            reply_markup=InlineKeyboardMarkup(
                inline_keyboard=[
                    [
                        InlineKeyboardButton(
                            text=cancel_text,
                            callback_data="payment_cancel",
                        )
                    ]
                ]
            ),
        )

        notice_id = callback.message.message_id

        # Создаём новый счёт
        invoice_message = await callback.bot.send_invoice(
            chat_id=user_id,
            title=title,
            description=description,
            payload=payload,
            provider_token="",
            currency="XTR",
            prices=[
                LabeledPrice(
                    label=label,
                    amount=price,
                )
            ],
        )

        pending_payment_messages[user_id] = {
            "invoice_id": invoice_message.message_id,
            "notice_id": notice_id,
        }

    except Exception as error:
        print("PREMIUM INVOICE ERROR:", repr(error))

        await callback.message.answer(
            "Could not create the payment invoice. Please try again."
            if language == "en"
            else "Не удалось создать счёт. Попробуйте ещё раз.",
            reply_markup=main_menu_keyboard(language),
        )


