@dp.callback_query(F.data.startswith("donate_amount:"))
async def donate_amount_callback(callback: CallbackQuery):

    user_id = callback.from_user.id
    language = get_language(user_id)

    try:
        amount = int(callback.data.split(":")[1])
    except (ValueError, IndexError):
        await callback.answer("Invalid amount.", show_alert=True)
        return

    if amount not in DONATION_AMOUNTS:
        await callback.answer("Invalid amount.", show_alert=True)
        return

    if language == "en":

        text = (
            "⭐ <b>Confirm your donation</b>\n\n"
            f"Amount: <b>{amount} Stars</b>\n\n"
            "Thank you for supporting PocketFinance AI!"
        )

        confirm_text = "✅ Confirm"
        back_text = "◀️ Back"
        cancel_text = "❌ Cancel"

    else:

        text = (
            "⭐ <b>Подтверждение пожертвования</b>\n\n"
            f"Сумма: <b>{amount} звёзд</b>\n\n"
            "Спасибо за поддержку PocketFinance AI!"
        )

        confirm_text = "✅ Подтвердить"
        back_text = "◀️ Назад"
        cancel_text = "❌ Отмена"

    keyboard = InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text=confirm_text,
                    callback_data=f"donate_confirm:{amount}",
                )
            ],
            [
                InlineKeyboardButton(
                    text=back_text,
                    callback_data="donate",
                ),
                InlineKeyboardButton(
                    text=cancel_text,
                    callback_data="settings",
                ),
            ],
        ]
    )

    await callback.answer()

    await callback.message.edit_text(
        text,
        reply_markup=keyboard,
        parse_mode="HTML",
    )


