@dp.callback_query(F.data.startswith("donate_confirm:"))
async def donate_confirm_callback(callback: CallbackQuery):

    user_id = callback.from_user.id
    language = get_language(user_id)

    try:
        amount = int(callback.data.split(":")[1])
    except (ValueError, IndexError):
        await callback.answer("Invalid amount.", show_alert=True)
        return

    if amount not in DONATION_AMOUNTS:
        await callback.answer("Invalid amount.", show_alert=True)
        return

    payload = (
        f"pf:donate:{user_id}:{amount}:{uuid.uuid4().hex[:12]}"
    )

    title = (
        "Support PocketFinance AI"
        if language == "en"
        else "Поддержка PocketFinance AI"
    )

    description = (
        "Donation to support PocketFinance AI."
        if language == "en"
        else "Пожертвование на развитие PocketFinance AI."
    )

    label = "Donation" if language == "en" else "Пожертвование"

    notice = (
        "Complete the donation using the invoice below."
        if language == "en"
        else "Оплатите пожертвование с помощью счёта ниже."
    )

    cancel_text = (
        "❌ Cancel donation"
        if language == "en"
        else "❌ Отменить пожертвование"
    )

    await callback.answer()

    try:
        await cleanup_payment_messages(callback.bot, user_id)

        await callback.message.edit_text(
            notice,
            reply_markup=InlineKeyboardMarkup(
                inline_keyboard=[
                    [
                        InlineKeyboardButton(
                            text=cancel_text,
                            callback_data="payment_cancel",
                        )
                    ]
                ]
            ),
        )

        notice_id = callback.message.message_id

        invoice_message = await callback.bot.send_invoice(
            chat_id=user_id,
            title=title,
            description=description,
            payload=payload,
            provider_token="",
            currency="XTR",
            prices=[
                LabeledPrice(
                    label=label,
                    amount=amount,
                )
            ],
        )

        pending_payment_messages[user_id] = {
            "invoice_id": invoice_message.message_id,
            "notice_id": notice_id,
        }

    except Exception as error:
        print("DONATION INVOICE ERROR:", repr(error))

        await callback.message.answer(
            "Could not create the donation invoice. Please try again."
            if language == "en"
            else "Не удалось создать счёт. Попробуйте ещё раз.",
            reply_markup=main_menu_keyboard(language),
        )

