@dp.pre_checkout_query()
async def process_pre_checkout(
    query,
):

    try:

        parts = query.invoice_payload.split(":")

        if query.currency != "XTR":
            raise ValueError("Invalid currency")

        if len(parts) < 5 or parts[0] != "pf":
            raise ValueError("Invalid payload")

        payment_type = parts[1]
        payload_user_id = int(parts[2])

        if payload_user_id != query.from_user.id:
            raise ValueError("Wrong user")

        if payment_type == "premium":

            if len(parts) != 6:
                raise ValueError("Invalid Premium payload")

            months = int(parts[3])
            price = int(parts[4])

            if months not in PREMIUM_PLANS:
                raise ValueError("Invalid Premium plan")

            if price != PREMIUM_PLANS[months]["price"]:
                raise ValueError("Price changed")

            if query.total_amount != price:
                raise ValueError("Incorrect payment amount")

        elif payment_type == "donate":

            if len(parts) != 5:
                raise ValueError("Invalid donation payload")

            amount = int(parts[3])

            if amount not in DONATION_AMOUNTS:
                raise ValueError("Invalid donation amount")

            if query.total_amount != amount:
                raise ValueError("Incorrect donation amount")

        else:

            raise ValueError("Unknown payment type")

        await query.answer(ok=True)

    except Exception as error:

        print("PRE-CHECKOUT ERROR:", repr(error))

        await query.answer(
            ok=False,
            error_message=(
                "Payment verification failed. Please create a new invoice."
            ),
        )


