@dp.message(F.successful_payment)
async def successful_payment_handler(message: Message):

    user_id = message.from_user.id
    language = get_language(user_id)

    payment = message.successful_payment

    try:

        parts = payment.invoice_payload.split(":")

        if payment.currency != "XTR":
            raise ValueError("Invalid payment currency")

        if len(parts) < 5 or parts[0] != "pf":
            raise ValueError("Invalid payment payload")

        payment_type = parts[1]
        payload_user_id = int(parts[2])

        if payload_user_id != user_id:
            raise ValueError("Wrong payment user")

        months = 0

        if payment_type == "premium":

            if len(parts) != 6:
                raise ValueError("Invalid Premium payload")

            months = int(parts[3])
            payload_amount = int(parts[4])

            if months not in PREMIUM_PLANS:
                raise ValueError("Invalid Premium plan")

            base_price = PREMIUM_PLANS[months]["price"]
            discount = PREMIUM_PLANS[months]["discount"]

            expected_amount = round(
                base_price * (100 - discount) / 100
            )

            if payload_amount != expected_amount:
                raise ValueError("Invalid Premium price")

        elif payment_type == "donate":

            if len(parts) != 5:
                raise ValueError("Invalid donation payload")

            expected_amount = int(parts[3])

            if expected_amount not in DONATION_AMOUNTS:
                raise ValueError("Invalid donation amount")

        else:

            raise ValueError("Unknown payment type")

        if payment.total_amount != expected_amount:
            raise ValueError("Incorrect paid amount")

        saved = save_successful_star_payment(
            telegram_id=user_id,
            payment=payment,
            payment_type=payment_type,
            months=months,
        )

        if not saved:
            await cleanup_payment_messages(message.bot, user_id)

            try:
                await message.delete()
            except Exception:
                pass

            await message.answer(
                "🏠 Главное меню"
                if language == "ru"
                else "🏠 Main menu",
                reply_markup=main_menu_keyboard(language),
            )
            return

        # Удаляем счёт и сообщение с инструкцией
        await cleanup_payment_messages(message.bot, user_id)

        # Удаляем системное сообщение об успешной оплате
        try:
            await message.delete()
        except Exception:
            pass

        # Показываем только главное меню
        await message.answer(
            "🏠 Главное меню"
            if language == "ru"
            else "🏠 Main menu",
            reply_markup=main_menu_keyboard(language),
        )

    except Exception as error:

        print("SUCCESSFUL PAYMENT ERROR:", repr(error))

        await message.answer(
            "Payment received, but processing failed. Please contact support."
            if language == "en"
            else "Оплата получена, но возникла ошибка обработки. Обратитесь в поддержку."
        )


