@dp.callback_query(
    F.data.startswith("settings_set_language:")
)
async def settings_set_language(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id

    new_language = callback.data.split(
        ":",
        1,
    )[1]

    if new_language not in {
        "ru",
        "en",
    }:

        await callback.answer(
            "Invalid language.",
            show_alert=True,
        )

        return

    try:

        change_language(
            user_id,
            new_language,
        )

    except TypeError:

        try:

            change_language(
                telegram_id=user_id,
                language=new_language,
            )

        except Exception as e:

            print(
                "Language change error:",
                e,
            )

            await callback.answer(
                "Could not change language.",
                show_alert=True,
            )

            return

    except Exception as e:

        print(
            "Language change error:",
            e,
        )

        await callback.answer(
            "Could not change language.",
            show_alert=True,
        )

        return

    await callback.answer()

    if new_language == "en":

        text = (
            "✅ Language changed to English."
        )

    else:

        text = (
            "✅ Язык изменён на русский."
        )

    try:

        await callback.message.edit_text(
            text,
            reply_markup=settings_keyboard(
                new_language
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=settings_keyboard(
                new_language
            ),
        )


