@dp.callback_query(
    F.data.startswith("set_default_currency:")
)
async def set_default_currency(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id
    language = get_language(
        user_id
    )

    currency = callback.data.split(
        ":",
        1,
    )[1]

    if currency not in {"RUB", "USD"}:

        await callback.answer(
            "Invalid currency.",
            show_alert=True,
        )

        return

    try:

        update_user_settings(
            user_id=user_id,
            default_currency=currency,
        )

    except TypeError:

        try:

            update_user_settings(
                user_id,
                default_currency=currency,
            )

        except TypeError:

            try:

                update_user_settings(
                    user_id,
                    currency,
                )

            except Exception as e:

                print(
                    "Currency update error:",
                    e,
                )

                await callback.answer(
                    "Could not update currency.",
                    show_alert=True,
                )

                return

        except Exception as e:

            print(
                "Currency update error:",
                e,
            )

            await callback.answer(
                "Could not update currency.",
                show_alert=True,
            )

            return

    except Exception as e:

        print(
            "Currency update error:",
            e,
        )

        await callback.answer(
            "Could not update currency.",
            show_alert=True,
        )

        return

    await callback.answer()

    currency_text = (
        "RUB ₽"
        if currency == "RUB"
        else "USD $"
    )

    if language == "en":

        text = (
            "✅ Default currency updated.\n\n"
            f"Currency: {currency_text}"
        )

    else:

        text = (
            "✅ Валюта по умолчанию изменена.\n\n"
            f"Валюта: {currency_text}"
        )

    try:

        await callback.message.edit_text(
            text,
            reply_markup=settings_keyboard(
                language
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=settings_keyboard(
                language
            ),
        )


