async def render_information(
    message: Message,
    user_id: int,
    edit=False,
):
    language = get_language(
        user_id
    )

    if language == "en":

        text = (
            "ℹ️ About PocketFinance AI\n\n"
            "PocketFinance AI helps you record "
            "income and expenses, view financial "
            "statistics and receive financial "
            "recommendations.\n\n"
            "⚠️ The bot provides informational "
            "financial analysis and does not "
            "guarantee any financial result."
        )

    else:

        text = (
            "ℹ️ О PocketFinance AI\n\n"
            "PocketFinance AI помогает записывать "
            "доходы и расходы, просматривать "
            "финансовую статистику и получать "
            "рекомендации.\n\n"
            "⚠️ Бот предоставляет информационный "
            "финансовый анализ и не гарантирует "
            "какой-либо финансовый результат."
        )

    keyboard = information_keyboard(
        language
    )

    if edit:

        try:

            await message.edit_text(
                text,
                reply_markup=keyboard,
            )

            return

        except Exception:
            pass

    await message.answer(
        text,
        reply_markup=keyboard,
    )

# ============================================================
# CALLBACK ИНФОРМАЦИИ
# ============================================================

@dp.callback_query(
    F.data == "information"
)
async def information_callback(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id

    if not has_accepted_documents(
        user_id
    ):
        await callback.answer(
            "Use /start first.",
            show_alert=True,
        )
        return

    await callback.answer()

    await render_information(
        callback.message,
        user_id,
        edit=True,
    )

# ============================================================
# ПОДТВЕРЖДЕНИЕ УДАЛЕНИЯ
# ============================================================

def delete_data_confirmation_keyboard(
    language: str
):
    if language == "en":

        return InlineKeyboardMarkup(
            inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text="🗑 Yes, delete everything",
                        callback_data="delete_data_confirm",
                    )
                ],
                [
                    InlineKeyboardButton(
                        text="❌ Cancel",
                        callback_data="settings",
                    )
                ],
            ]
        )

    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(
                    text="🗑 Да, удалить всё",
                    callback_data="delete_data_confirm",
                )
            ],
            [
                InlineKeyboardButton(
                    text="❌ Отмена",
                    callback_data="settings",
                )
            ],
        ]
    )


@dp.callback_query(
    F.data == "delete_data"
)
async def delete_data_start(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id
    language = get_language(
        user_id
    )

    if language == "en":

        text = (
            "⚠️ Delete all data?\n\n"
            "This will permanently delete your "
            "financial data, transactions, settings, "
            "reminders and other data stored by the bot.\n\n"
            "This action cannot be undone."
        )

    else:

        text = (
            "⚠️ Удалить все данные?\n\n"
            "Будут безвозвратно удалены ваши "
            "финансовые данные, операции, настройки, "
            "напоминания и другие данные, сохранённые ботом.\n\n"
            "Это действие нельзя отменить."
        )

    await callback.answer()

    try:

        await callback.message.edit_text(
            text,
            reply_markup=delete_data_confirmation_keyboard(
                language
            ),
        )

    except Exception:

        await callback.message.answer(
            text,
            reply_markup=delete_data_confirmation_keyboard(
                language
            ),
        )


# ============================================================
# ОКОНЧАТЕЛЬНОЕ УДАЛЕНИЕ
# ============================================================

@dp.callback_query(
    F.data == "delete_data_confirm"
)
async def delete_data_confirm(
    callback: CallbackQuery,
):
    user_id = callback.from_user.id

    # Получаем язык ДО удаления пользователя.
    language = get_language(
        user_id
    )

    try:

        deleted = delete_user_data(
            user_id
        )

    except TypeError:

        try:

            deleted = delete_user_data(
                telegram_id=user_id
            )

        except Exception as e:

            print(
                "Delete user data error:",
                e,
            )

            await callback.answer(
                "Could not delete your data.",
                show_alert=True,
            )

            return

    except Exception as e:

        print(
            "Delete user data error:",
            e,
        )

        await callback.answer(
            "Could not delete your data.",
            show_alert=True,
        )

        return

    await callback.answer()

    # --------------------------------------------------------
    # ПОСЛЕ УДАЛЕНИЯ ПОЛЬЗОВАТЕЛЬ БОЛЬШЕ НЕ СЧИТАЕТСЯ
    # ЗАРЕГИСТРИРОВАННЫМ.
    #
    # При следующем /start:
    # язык → документы → принятие → меню.
    # --------------------------------------------------------

    if language == "en":

        text = (
            "🗑 Your data has been deleted.\n\n"
            "All data stored by PocketFinance AI "
            "has been removed.\n\n"
            "If you want to use the bot again, "
            "send /start."
        )

    else:

        text = (
            "🗑 Ваши данные удалены.\n\n"
            "Все данные, сохранённые PocketFinance AI, "
            "были удалены.\n\n"
            "Если хотите использовать бота снова, "
            "отправьте /start."
        )

    try:

        await callback.message.edit_text(
            text,
        )

    except Exception:

        await callback.message.answer(
            text,
        )


# ============================================================
# ЗАПУСК БОТА
# ============================================================

async def main():

    print("БОТ ЗАПУСКАЕТСЯ")

    try:

        me = await bot.get_me()

        print(
            "TELEGRAM OK:",
            me.username,
        )

        asyncio.create_task(
            run_admin_server(bot)
        )

        print(
            "АДМИН-ПАНЕЛЬ ЗАПУЩЕНА"
        )

        start_reminder_scheduler()

        print(
            "ПЛАНИРОВЩИК НАПОМИНАНИЙ ЗАПУЩЕН"
        )

        print(
            "БОТ ЖДЁТ СООБЩЕНИЯ"
        )

        await dp.start_polling(
            bot,
            handle_signals=True,
        )

    except Exception as e:

        print(
            "ОШИБКА ЗАПУСКА БОТА:",
            repr(e),
        )


if __name__ == "__main__":

    asyncio.run(
        main()
    )
